			aBIErrorCollection["263"] = new MessageError(errorCode: "263", shortDesc: "INVALID UPDATE CODE", narrative: "THIS MESSAGE IS GENERATED IN RESPONSE TO AN ENTRY SUMMARY INPUT TRANSACTION (APPLICATION EI). THE 10 RECORD, POS 3 MUST REFLECT ONE OF FOUR ACTION CODES: A (ADD) D (DELETE) C (CHANGE) OR R (REPLACE. IF ANY OTHER CHARACTER, OR A BLANK, IS TRANSMITTED IN THIS FIELD, THIS ERROR MESSAGE WILL BE GENERATED.");
			aBIErrorCollection["266"] = new MessageError(errorCode: "266", shortDesc: "NUMBER OF UNITS AND UNIT ABBR", narrative: "NUMBER OF CENSUS UNITS AND THE REP. UNIT ABBR FIELD.  FOR QP TRANSACTIONS, THIS ERROR WILL RETURN THE MESSAGE 'INVALID REF # QUALIFIER.' ONLY SPECIFIC QUALIFIER CODES ARE ACCEPTED PER PAGE INB-18 OF THE CATAIR. ANY OTHER CODE TRANSMITTED WILL CAUSE THIS ERROR.");
			aBIErrorCollection["269"] = new MessageError(errorCode: "269", shortDesc: "VALUE EDIT CODE AND UPR LIMIT", narrative: "VALUE EDIT CODE AND VALUE EDIT UPPER BOUND VALUE  FOR QP TRANSACTIONS, THIS ERROR WILL RETURN THE MESSAGE 'BILL ALREADY EXIST FOR INBOND.' THE QP30 RECORD CANNOT REPORT THE SAME BILL NUMBER TWICE.");
			aBIErrorCollection["273"] = new MessageError(errorCode: "273", shortDesc: "1ST QTY EDT CODE/LOWER LIMIT", narrative: "FIRST QUANTITY EDIT CODE AND LOWER BOUND VALUE  IN FDA 'WP' THIS MESSAGE IS 'INVALID PRODUCT CODE'. CHECK THE PRODUCT CODE IN THE FD01 RECORD WITH THE FDPL FILE. IT MUST BE ON FILE. THE SAME EDITS APP LY TO 'WP' AS TO EI/HI/HN.");
			aBIErrorCollection["275"] = new MessageError(errorCode: "275", shortDesc: "2ND QTY EDT CODE AND UPR LMT", narrative: "SECOND QUNATITY EDIT CODE AND UPPER BOUND VALUE  IN FDA 'WP' THIS MESSAGE IS 'INVALID COUNTRY CODE'. THIS REFERS USUALLY TO THE AOC 'CSH'. THIS AOC CANNOT BE 'US'.");
