			aBIErrorCollection["27G"] = new MessageError(errorCode: "27G", shortDesc: "*CENSUS* IMPROBABLE AIR TARIFF 1", narrative: "THIS MESSAGE IS ONE OF A NUMBER OF CENSUS WARNING MESSAGES. IN THIS CASE, THE MESSAGE INDICATES THAT THE TARIFF NUMBER (50 REC, POS 4-13) IS ONE THAT IS NOT USUALLY TRANSPORTED TO THE UNITED STATES BY AIR CARRIER. HEAVY MACHINE, (EARTH MOVING EQUIPMENT), PETROLEUM PRODUCTS, ETC ARE SOME EXAMPLES");
			aBIErrorCollection["276"] = new MessageError(errorCode: "276", shortDesc: "2ND QTY EDT CODE AND LOW LMT", narrative: "THIS MESSAGE IS USED IN ABI IN REPLY TO A WP (FDA PRIOR NOTICE INPUT) TRANSACTION WHEN THE FILER ATTEMPTS TO REPORT NON-BTA FDA DATA ON ONE OR MORE FDA LINES. WP WITH CODE 9 IS STRICTLY LIMITED TO THE REPORTING OF PRIOR NOTICE DATA. ERROR MESSAGE 'INVALID AFFIRMATION OF COMPLIANCE' WILL BE RETURNED AGAINST THE FIRST FDA LINE THAT DOES NOT REFLECT ONE OR MORE OF THE REQUIRED PRIOR NOTICE AFFIRMATIONS.  YOU WILL ALSO SEE THIS MESSAGE COME AFTER THE FD01 RECORD WHEN THE FILER SENDS AN AOC OTHER THAN 'SLN' IN THE FIRST AOC BLOCK THERE.  SOMETIMES YOU WILL SEE FILER ATTEMPT TO ENTER A PNC NUMBER IN THE FIRST AOC BLOCK. YOU OBTAIN A PNC THROUGH WP NOT REPORT IT.");
			aBIErrorCollection["27A"] = new MessageError(errorCode: "27A", shortDesc: "*CENSUS* IMPROBABLE COUNTRY", narrative: "THIS MESSAGE IS AN ABI REPLY TO AN ENTRY SUMMARY (EI) INPUT TRANSACTION. IT INDICATES THAT THE DATA COLLECTED BY CENSUS DOES NOT INDICATE THAT THE TARIFF NUMBER FOR THE LINE IN QUESTION HAS NOT BEEN PREVIOUSLY REPORTED FROM THE TRANSMITTED COUNTRY OF ORIGIN. THE FILER SHOULD VERIFY THE COUNTRY OF ORIGIN AND/OR TARIFF NUMBER AND, IF NECESSARY, MAKE CORRECTIONS. IF THE DATA IS ACCURATE AS TRANSMITTED, NO FURTHER ACTION VIA ABI IS NECESSARY.  NOTE: THIS EDIT DOES NOT APPLY UNLESS THE VALUE OF THE LINE IS OVER $10,000.");
