			aBIErrorCollection["27C"] = new MessageError(errorCode: "27C", shortDesc: "*CENSUS* OR-LO VAL/QTY(1) TARIFF1", narrative: "THE UNIT PRICE (VALUE/PRIMARY QUANTITY) IS NOT WITHIN SPECIFIC LIMITS. NOTE: IF THIS WARNING MESSAGE APPEARS ON AN ENTRY SCHEDULED FOR PERIODIC MONTHLY STATEMENT PROCESSING, THE ENTRY SUMMARY WILL BE REJECTED.  AT THE CURRENT TIME (NOV 2004), CENSUS WARNINGS ARE NOT PERMITTED ON PMS ENTRIES. NOTE: AS OF AUGUST 2005, THE ABOVE CONDITION NO LONGER BLOCKED AN ENTRY FROM APPEARING ON A PERIODIC MONTHLY STATEMENT.");
			aBIErrorCollection["27H"] = new MessageError(errorCode: "27H", shortDesc: "*CENSUS* GROSS WEIGHT â€“ AIR", narrative: "THIS IS AN ABI OUTPUT MESSAGE IN REPLY TO AN ENTRY SUMMARY INPUT TRANSACTION. IT INDICATES THAT THE LINE IN QUESTION HAS REPORTED MORE THAN 102,060 KILOS FOR THE GROSS SHIPPING WEIGHT ON A SHIPMENT ARRIVING IN THE UNITED STATES BY AIR. THE FILER SHOULD REVIEW THE SHIPPING WEIGHT FOR THE LINE IN QUESTION AND MAKE THE NECESSARY CORRECTIONS BEFORE TRANSMITTING THE SUMMARY TO ABI.");
			aBIErrorCollection["27I"] = new MessageError(errorCode: "27I", shortDesc: "*CENSUS* MAXIMUM WEIGHT EXCEEDED", narrative: "GROSS SHIPPING WEIGHT TOO GREAT FOR ENTERED MODE OF TRANSPORTATION (PER CENSUS)");
			aBIErrorCollection["27J"] = new MessageError(errorCode: "27J", shortDesc: "*CENSUS* OR-AGR CHARGES/VALUE", narrative: "THIS MESSAGE IS GENERATED ON ENTRY SUMMARY INPUT TRANSACATIONS WHEN THE LINE ITEM CHARGES (40 REC, POS 48-57) DIVIDED BY THE LINE ITEM VALUE (40 REC, POS 8-17) EXCEED A STATED PERCENTAGE. THE PERCENTAGE CAN BE VIEWED FROM FUNCTION HSBL 1/TARIFF NUMBER.  IF THE RATIO BETWEEN THE CHARGES AND VALUE EXCEEDS THE PERCENTAGE SHOWN ON HSBS BY MORE THAN 300 PERCENT, THIS ERROR MESSAGE WILL BE GENERATED. (EXAMPLE: VALUE IS $400 FOR TARIFF 8541402000 AND THE CHARGES ARE $100. THIS IS A 25% RATIO. THE HSBS RECORD FOR THE TARIFF NUMBER SHOWS 7% AS THE UPPER LIMIT. 7% OF $400 IS $28. 300% OF THIS FIGURE WOULD BE $84. THEREFORE, CHARGES FROM $1 TO $84 WOULD NOT GENERATE THIS WARNING MESSAGES, BUT CHARGES OF $85 OR HIGHER WOULD.)  FOR SHIPMENTS BY AIR, THE CHARGES IS SOMETIMES COMPARED TO THE GROSS WEIGHT (40 REC, POS18-27) AND THIS MESSAGE COULD BE GENERATED EVEN IN A CASE WHERE THE CHARGES/VALUE RATIO WAS BELOW 300% OF THE VALUE.");
