			aBIErrorCollection["2A5"] = new MessageError(errorCode: "2A5", shortDesc: "RELEASE CERTIFIED VIA SUMMARY", narrative: "THIS IS AN ABI OUTPUT MESSAGE THAT MAY BE INCLUDED AS PART OF THE REPLY TO AN ENTRY SUMMARY TRANSACTION (APPLICATION EI). IF THE FILER REQUESTS THE SUMMARY DATA TO BE REVIEW FOR CARGO SELECTIVITY PURPOSES, A '1' WILL BE TRANSMITTED IN POS 38 OF THE 30 RECORD. IF NO ERRORS ARE ENCOUNTERED IN THE INPUT DATA, WHEN THE SUMMARY IS ACCEPTED BY ABI, THIS MESSAGE WILL ACCOMPANY THE SUMMARY RESULTS OUTPUT.");
			aBIErrorCollection["2A7"] = new MessageError(errorCode: "2A7", shortDesc: "CARGO RELEASE DATA NOT ON FILE", narrative: "THIS IS AN ABI OUTPUT MESSAGE THAT MAY BE INCLUDED AS PART OF THE REPLY TO AN ENTRY SUMMARY TRANSACTION (APPLICATION EI). IF THE FILER REQUESTS THE SUMMARY DATA TO BE REVIEW FOR CARGO SELECTIVITY PURPOSES, A '1' WILL BE TRANSMITTED IN POS 38 OF THE 30 RECORD. IF NO ERRORS ARE ENCOUNTERED IN THE INPUT DATA, WHEN THE SUMMARY IS ACCEPTED BY ABI, THIS MESSAGE WILL ACCOMPANY THE SUMMARY RESULTS OUTPUT.");
			aBIErrorCollection["2AI"] = new MessageError(errorCode: "2AI", shortDesc: "INVALID BOND TYPE", narrative: "THE ON-LINE USER'S GUIDE, UAGL, CONTAINS A LIST OF VALID BOND TYPES AND BOND ACTIVITY CODES. TO ACCESS THIS LIST, TYPE 'UAGL 330/115' AND HIT ENTER. MOVE THE CURSOR DOWN TO THE FIRST LINE DISPLAYED AND HIT 'ENTER.' ON THE UAGS SCREE N THAT DISPLAYS, MOVE THE CURSOR HORIZONTALLY TO THE '/05' AND TYPE '10'. HIT ENTER. THE CURRENT BOND TYPES AND THEIR CORRESPONDING ACTIVITY CODES WILL BE DISPLAYED. A SHORTER VERSION OF THIS LIST CAN BE FOUND IN THE CATAIR ON PAGE QIB-8.  NOTE: ABI FILERS WHO DO BOND QUERIES WILL RECEIVE A SINGLE ALPHA CHARACTER CODE DESIGNATING WHICH TYPE OF BOND IS ON FILE, IF ANY, FOR THE IMPORTER BEING QUERIED. THE FILER'S SOFTWARE SHOULD TRANSLATE THE CODE INTO THE APPROPRIATE BOND TYPE AND DESCRIPTION.");
			aBIErrorCollection["2AL"] = new MessageError(errorCode: "2AL", shortDesc: "SURETY CODE INVALID", narrative: "IF THE FILER TRANSMITS BOND CODE 8 (CONTINUOUS BOND) IN THE SUMMARY INPUT (REC 10, POS 49), THE SURETY CODE IN REC 10, POS 73-75 MUST BE LISTED ON THE BDAL FILE AND MUST BE IN ACTIVE STATUS. IN ADDITION, THE SURETY CODE CITED IN THE 10 RECORD MUST MATCH THE SURETY CODE IN THE BNDL FILE FOR THE IMPORTER NUMBER TRANSMITTED IN REC 10, POS 8-19. (THE SURETY CODE FIELD CANNOT BE BLANK FOR EITHER TYPE 8 OR 9 BONDS) IF AD/CVD BONDED DUTIES ARE REPORTED IN THE 35 RECORD, A SURETY CODE MUST BE PRESENT IN POS 49-51. IF BOND TYPE '0' IS SENT, AND NO SURETY CODE IS SENT, AS WELL, THIS MESSAGES RESULTS.  THIS MESSAGE WILL ALSO APPEAR IF THE IMPORTER HAS TWO ACTIVE CONTINUOUS BONDS IN EFFECT AT THE SAME TIME. THE SURETY CODE FOR THE BOND THAT WENT INTO EFFECT FIRST MUST BE USED ON SUMMARY INPUT TRANSACTIONS.  SURETY CODES ARE VALIDATED BASED ON DATE OF RELEASE, SO A SUMMARY TRANSMITTED WITH A SURETY CODE BASED ON ESTIMATED ENTRY DATE WILL ALSO REJECT IF A DIFFERENT SURETY CODE WAS IN EFFECT AT THE TIME OF RELEASE.  FOR RECONCILIATION, THE SURETY CODE GIVEN MUST BE VALID ON CUSTOMS FILE.");
			aBIErrorCollection["2AU"] = new MessageError(errorCode: "2AU", shortDesc: "BILL-OF-LADING REQUIRED WITH I.T.", narrative: "WHEN AN INBOND NUMBER IS PROVIDED, THE BILL OF LADING NUMBER IS REQUIRED.  **NOTE** - SINCE THIS MESSAGE WAS FIRST CREATED, THE LINKAGE BETWEEN INBOND AND BILL NUMBERS HAS BEEN CHANGED. THE CURRENT REQUIREMENTS (6/98) ARE:  IF THE MOT IS OCEAN (10 SERIES) OR AIR (40 SERIES), AN I.T. NUMBER ALWAYS REQUIRES A MASTER BILL OR AIR WAYBILL TO BE TRANSMITTED IN THE SUMMARY INPUT APPLICATION.  IF THE MOT IS RAIL (20 SERIES) OR ROAD (30 SERIES), IF THE I.T. NUMBER IS A PAPERLESS MIB (V NUMBER), THE MASTER BILL FIELD IN THE 22 RECORD MUST BE FILLED IN OR THIS MESSAGE WILL RESULT.  IF THE MOT IS RAIL OR ROAD, BUT THE I.T. NUMBER IS A CONVENTIONAL (9-DIGIT) NUMBER, THEN THE MASTER BILL FIELD MAY BE LEFT BLANK.");
			aBIErrorCollection["2B8"] = new MessageError(errorCode: "2B8", shortDesc: "INVALID STATE CODE", narrative: "THIS MESSAGE IS GENERATED IN RESPONSE TO AN ABI 5106 INPUT TRANSACTION (APPLICATION TI). THE STATE CODE IS TRANSMITTED IN POS 68-69 OF THE T2 RECORD. VALID STATE CODES ARE THOSE LISTED BY THE UNITED STATES POSTAL SERVICE. THE USE OF ANY CODE IN THIS FIELD THAT IS NOT APPROVED BY THE POSTAL SERVICE WILL GENERATE THIS ERROR MESSAGE.  NOTE: THIS ERROR MESSAGE IS NOT ACCOMPANIED BY AN ERROR MESSAGE NUMBER WHEN TRANSACTION TI IS SENT TO ABI. ERROR MESSAGE 2BU WHICH IS IDENTICAL IN WORDING TO THIS MESSAGE, MAY BE THE ONE BEING USED.");
			aBIErrorCollection["2BU"] = new MessageError(errorCode: "2BU", shortDesc: "INVALID STATE CODE", narrative: "ACS REQUIRES THE ABI FILER TO REPORT THE STATE OF ULTIMATE DESTINATION FOR THE IMPORTED CARGO. THIS CODE IS TRANSMITTED IN THE 10 REC, POS 78-79. ONLY THE TWO CHARACTER POSTAL ABBREVIATION FOR ONE OF THE 50 STATES WILL BE ACCEPTED IN THIS ELEMENT. IF ANY OTHER CODE IS TRANSMITTED, OR IF THE FIELD IS LEFT BLANK, THIS ERROR WILL BE GENERATED.  IF THE ADD 5106 APPLICATION (CODE TI) IS USED, THIS ERROR MESSAGE WILL BE GENERATED IF THE STATE CODE IS NOT ONE OF THOSE APPROVED BY THE UNITED STATES POSTAL SERVICE. NOTE THAT ERROR MESSAGE 2B8 IS IDENTICAL TO THIS ERROR MESSAGE, BUT IS NOT BEING USED AS OF AUG 2006.");
			aBIErrorCollection["2C0"] = new MessageError(errorCode: "2C0", shortDesc: "BOND NOT IN EFFECT", narrative: "A VALID BOND IS ON FILE, BUT IS NOT EFFECTIVE ON THE DATE OF THE QUOTA ENTRY. THIS USUALLY MEANS THAT THE BOND DOES NOT BECOME EFFECTIVE UNTIL A FUTURE DATE. IN THIS CASE, CARGO SELECTIVITY WILL NOT BE ISSUED VIA ABI UNTIL THE BOND EFFECTIVE DATE EQUALS THE CALENDAR DATE.  OR, IF NOT ABI:  CHECK BOND TYPE ON 'ENA' MASTER RECORD. IF (9), MUST 'X' 'S.E.B.' ACS WILL NOT CHECK CONTINUOUS (301) BOND FILE.");
			aBIErrorCollection["2C1"] = new MessageError(errorCode: "2C1", shortDesc: "BOND EXPIRED", narrative: "A VALID BOND WAS ON FILE FOR IMPORTER, BUT IT HAS EXPIRED.  NOTE: THIS MESSAGE WILL ALSO OCCUR IF THE FILER USES A VALID BOND WITH A TYPE THAT IS NOT 1 OR 1A (THE ONLY VALID BOND TYPES FOR IMPORTATIONS BY IMPORTERS). CHECK THE BNDL FILE TO DETERMINE WHAT TYPE BOND IS ON FILE FOR THE IMPORTER OF RECORD NUMBER.  NOTE: IF THE PORT PROCESSING THE BOND DOES NOT FOLLOW THE INSTRUCTIONS OUTLINED IN UAGS 330/115/BONDS/06 (RE THE USE OF PF8 TO COMPLETE THE UPDATE ACTION), AN ABI FILER TRANSMITTING AN ENTRY SUMMARY THAT REFERENCES AN 'INCOMPLETE' BOND WILL RECEIVE THIS ERROR MESSAGE AS WELL.");
			aBIErrorCollection["2C3"] = new MessageError(errorCode: "2C3", shortDesc: "INVALID BOND", narrative: "CONVERTED BOND TYPE 2: -MAY BE ON FILE BUT NOT FOR THE PORT OF ENTRY AND NOT ON FILE AT A CROSS DDPP OF THE PORT OF ENTRY FOR THE IMPORTER OR ITS PARENT (IF APPLICABLE), -IS ON THE FILE BUT DOESN'T COVER THE DATE OF THE ENTRY -DOESN'T AGREE WITH THE BOND TYPE THAT IS ON FILE.  CONVERTED BOND TYPE 5: -IS NOT ON FILE FOR THE IMPORTER OR ITS PARENT COMPANY -IS ON THE FILE BUT DOESN'T COVER THE DATE OF THE ENTRY BOND TYPE 8-THE BOND THAT IS ON FILE IS NOT A VALID CONTINUOUS BOND THAT IS APPROPRIATE FOR THE ENTRY TYPE. FOR BOND TYPE 8, IF THE BOND IS NOT ON FILE ON THE DATE USED FOR BOND VALIDATION (CARGO REL DATE, PAY DUE DATE, ETC) IN THE SUMMARY INPUT, THIS ERROR MESSAGE WILL RESULT. THIS WILL ALSO APPLY TO ENTRIES WITH A BOND THAT IS NOT EITHER A 1 OR 1A1 TYPE BOND IN THE BNDL FILE.");
			aBIErrorCollection["2GC"] = new MessageError(errorCode: "2GC", shortDesc: "DATA ADDED AS REQUESTED", narrative: "THIS IS NORMAL RESPONSE MESSAGE TO A CARGO RELEASE DATA INPUT TRANSACTION (APPLICATION HI) WHEN THE FILER USES ACTION CODE 'A' TO ADD DATA. UNLESS THE INPUT CONTAINS A CERTIFICATION CODE OF '1' IN POSITION 41 OF THE H1 RECORD, ABI WILL NOT GENERATE PROVISIONAL SELECTIVITY RESULTS TO THIS INPUT.");
			aBIErrorCollection["2IV"] = new MessageError(errorCode: "2IV", shortDesc: "MAX USERS 400 PER TRANSACTION", narrative: "WHEN ACE SENDS BOND DATA TO ACS, MAXIMUM NBR OF IMPORTERS CANNOT EXCEED 400 PER TRANSACTION. SUBMIT A SECOND TRANSACTION IF NECESSARY.");
			aBIErrorCollection["2KU"] = new MessageError(errorCode: "2KU", shortDesc: "INVALID EXPORT DATE FORMAT", narrative: "D11 EXPORT DATE MUST BE A VALID DATE IN YYMMDD FORMAT.");
			aBIErrorCollection["2KV"] = new MessageError(errorCode: "2KV", shortDesc: "EXPORT DATE } CLAIM DATE", narrative: "DRAWBACK D11 EXPORT DATE CANNOT BE GREATER THAN D10 CLAIM DATE.");
			aBIErrorCollection["2C5"] = new MessageError(errorCode: "2C5", shortDesc: "NON-GOVT IMPORTER - BOND REQD", narrative: "THE IMPORTER OF RECORD IS NOT DESIGATED AS A GOVERNMENT IMPORTER ON THE SRE (IMPORTER 5106) FILE IT MUST HAVE A VALID BOND ON FILE OR A SINGLE ENTRY BOND. BOND TYPES = 0 OR BLANK ARE NOT ACCEPTABLE FOR NON-GOVERNMENT IMPORTERS ON GOVERNMENT ENTRY TYPES 51, 52 OR 53.  5106 CHANGES TO CORRECT THE GOVERNMENT IMPORTER STATUS MUST BE INPUT BY PERSONS WITH REGIONAL LOG-ON AUTHORITY.  IN THE DRAWBACK MODULE THIS ERROR MESSAGE INDICATES THAT A CLAIM WAS MADE FOR EITHER ACCELERATED DRAWBACK OR EXPORTER'S SUMMARY PROCEDURE WITHOUT A VALID BOND, AND WHILE A GOVERNMENT CLAIM WAS MADE, THE CLAIMANT IS NOT A GOVERNMENT AGENCY.");
			aBIErrorCollection["2CI"] = new MessageError(errorCode: "2CI", shortDesc: "INBOND - INVALID CHECK DIGIT", narrative: "ENTRY SUMMARY OR CARGO RELEASE INPUT TRANSACTIONS THAT REPORT PAPERLESS MASTER INBOND NUMBERS (THOSE STARTING WITH 'V') MUST TRANSMIT A VALID MIB NUMBER, INCLUDING THE LAST DIGIT (CHECK DIGIT). IF THE LAST DIGIT IS NOT CORRECT, PRESUMING THAT THE FIRST 10 DIGITS ARE CORRECT, THIS ERROR MESSAGE WILL RESULT. THE FILER SHOULD RECONFIRM THE ENTIRE PAPERLESS MIB NUMBER WITH THE ISSUING CARRIER.  NOTE: ERRORS IN THE CHECK DIGIT FOR AIR WAYBILLS USED AS INBOND NUMBERS OR FOR CONVENTIONAL (9 DIGIT ALL NUMERIC) INBOND NUMBERS WILL GENERATE ERROR MESSAGE 361.");
			aBIErrorCollection["2CN"] = new MessageError(errorCode: "2CN", shortDesc: "SURETY NOT VALID FOR BOND TYPE", narrative: "THIS MESSAGE INDICATES THAT THE SURETY SENT BY THE DRAWBACK CLAIMANT IS NOT AUTHORIZED TO WRITE A TYPE 1A BOND.  THIS MESSAGE WILL ALSO RESULT IF A FILER ATTEMPTS TO TRANSMIT ENTRY TYPE 51 FOR EMERGENCY WAR MATERIALS AND THE IMPORTER IDENTIFIED IN THE ENTRY OR ENTRY SUMMARY HAS A CONTINUOUS BOND, BUT IS NOT A GOVERNMENT IMPORTER.");
			aBIErrorCollection["2DF"] = new MessageError(errorCode: "2DF", shortDesc: "CARR CODE REQ FOR MOT 10,11,40", narrative: "ENTRY SUMMARY TRANSMISSIONS FOR CARGO ARRIVING IN THE UNITED STATES BY AIR OR OCEAN (MOT 10, 11, 40, 41) MUST INCLUDE THE APPROPRIATE CODE REPRESENTING THE IMPORTING AIR OR OCEAN CARRIER. THE CARRIER CODE IS TRANSMITTED IN THE SUMMARY IN THE 30 REC, POS 73-76 (FOR THE FOUR CHARACTER OCEAN CARRIER CODE) AND IN THE 30 REC, POS 73-74 (FOR THE TWO CHARACTER AIR CARRIER CODE). THIS CODE IS REQUIRED WHETHER OR NOT THE ENTRY SUMMARY INPUT CONTAINS A CARGO CERTIFICATION REQUEST FLAG. IF THE FILER DOES NOT TRANSMIT THE CARRIER CODE AS DESCRIBED ABOVE, THIS ERROR MESSAGE WILL BE GENERATED. THIS MESSAGE WILL ALSO RESULT IF THE CARRIER CODE IS OMITTED FROM THE CARGO RELEASE DATA INPUT TRANSACTION (APPLICATION IDENTIFIER HI) FOR AIR OR OCEAN MODES OF TRANSPORTATION.");
			aBIErrorCollection["2G0"] = new MessageError(errorCode: "2G0", shortDesc: "DUPLICATE IT/AWB/BL NUMBER", narrative: "THIS MESSAGE APPLIES TO ENTRY SUMMARY INPUT (TRANSACTION ID = EI). THIS MESSAGE OCCURS WHEN A FILER SENDS MORE THAN ONE IT, AIRWAY BILL OR BILL OF LADING AND TWO OR MORE ARE DUPLICATES AND NOT DIFFERENTIATED BY A DIFFERENT B/L OR HOUSE BILL (IN THE CASE OF AN IT) OR DIFFERENT HOUSE OR SUBHOUSE BILL (IN THE CASE OF A AWB OR B/L). THE MOST COMMON CAUSE IS WHEN A FILER SENDS THE SAME BILL OF LADING/HOUSE BILL AND TRIES TO DIFFERENTIATE BY SENDING DIFFERENT QUANTITIES.");
			aBIErrorCollection["2G2"] = new MessageError(errorCode: "2G2", shortDesc: "DUPLICATE AIRWAY/BILL LADING NO.", narrative: "THIS MESSAGE IS A RESPONSE TO A CARGO RELEASE DATA INPUT TRANSACTION (APPLICATION HI). IF THE HA RECORDS CONTAIN DUPLICATE AIR WAYBILLS OR BILL OF LADING NUMBERS, THIS MESSAGE WILL BE GENERATED. THE DUPLICATION MUST BE EXACT FROM ONE HA RECORD TO THE NEXT. IF THE SECOND RECORD CONTAINS THE SAME MASTER BILL OR AIR WAYBILL RECORD, BUT INCLUDES A HOUSE OR HOUSE/SUBHOUSE BILL, THE PRESENCE OF THE ADDITIONAL BILL DATA WILL BE SUFFICIENT TO MAKE EACH HA RECORD DISTINCT.");
			aBIErrorCollection["2G8"] = new MessageError(errorCode: "2G8", shortDesc: "WATERWAY FEE INVALID FOR RECORD", narrative: "THIS ERROR MESSAGE OCCURS WHEN THE WATERWAY FEE (CLASS CODE 501), WHICH IS A LINE LEVEL FEE (REPORTED IN THE 62 RECORD ON THE SUMMARY INPUT) IS TRANSMITTED IN THE 34 RECORD AS AN ENTRY LEVEL FEE. THERE ARE CURRENTLY ONLY THREE ENTRY LEVEL FEES: THE INFORMAL FEE (CLASS CODE 311), THE DUTIABLE MAIL ENTRY FEE (CLASS CODE 496), AND THE MANUAL SURCHARGE FEE (CLASS CODE 500).");
			aBIErrorCollection["2H9"] = new MessageError(errorCode: "2H9", shortDesc: "BOND TERMINATED", narrative: "THE FILER WILL RECEIVE THIS ERROR MESSAGE IF THE BOND FOR THE IMPORTER OF RECORD THEY ARE SENDING HAS A TERMINATION DATE IN THE BND FILE EQUAL TO OR LATER THAN THE DATE OF ENTRY SENT BY THE FILER AS DETERMINED BY THE ENTRY DATE HIERARCHY. CHECK BNDL 2/IMPORTER NUMBER. THE TERMINATION DATE IS SHOWN ON THE HEADER SCREEN. THE FILER MAY BE GETTING THIS REJECT BECAUSE THEY ARE NOT SENDING AN ESTIMATED DATE OF ENTRY AND THE EDIT IS BEING DONE AGAINST THE STATEMENT DATE. IF THE TRUE DATE OF ENTRY IS BEFORE THE BOND TERMINATION DATE THE FILER MAY RETRANSMIT THE TRANSACTION WITH AN ESTIMATED ENTRY DATE. THE BOND MUST BE RENEWED FOR FUTURE IMPORTATIONS.  NOTE: IF THE EI TRANSACTION IS USED FOR CARGO RELEASE CERTIFICATION, ACS WILL CHECK BOND SUFFICIENCY ON THE EST ARRIVAL DATE AND WILL DISREGARD THE EST ENTRY DATE FIELD IN THE 10 RECORD. THUS IT IS POSSIBLE TO HAVE THE SUMMARY PASS ERROR-FREE WITH A TYPE 8 BOND, BUT STILL BE REJECTED IF THE BOND EXPIRES PRIOR TO THE EST ARRIVAL DATE.");
			aBIErrorCollection["2I5"] = new MessageError(errorCode: "2I5", shortDesc: "ADDR LINE 1 MISSING", narrative: "THIS MESSAGE IS GENERATED IN RESPONSE TO AN AUTOMATED INVOICE TRANSACTION (APPLICATION CI). THE C09 AND C59 RECORDS PROVIDE SPACE FOR THE NAME AND FIRST LINE OF THE ADDRESS OF THE PARTY IDENTIFIED IN THE C08 OR C58 RECORDS. FOR ALL PARTIES OTHER THAN THE IMPORTER (CODE IM) OR ULTIMATE CONSIGNEE (CODE UC), A NAME AND ADDRESS ARE REQUIRED. IF THE FIELD FOR LINE ONE OF THE ADDRESS IS BLANK, THIS ERROR MESSAGE WILL BE GENERATED. ERROR MESSAGE EIK, 'NAME/ADDRESS REQUIRED' WILL FREQUENTLY ACCOMPANY ERROR MESSAGE 2I5, UNLESS THE PARTY TYPE IS 'IM' OR 'UC'.  THIS MESSAGE ALSO APPLIES TO THE 5106 INPUT TRANSACTION (CODE TI).");
			aBIErrorCollection["2J0"] = new MessageError(errorCode: "2J0", shortDesc: "SURETY INVALID OR NOT ON FILE", narrative: "THIS REJECT MESSAGE REFERS TO THE SURETY REPORTED, IF ANY, FOR ANTIDUMPING OR COUNTERVAILING DUTY TRANSACTIONS. (MESSAGE 2AL IS THE EQUIVALENT ERROR MESSAGE FOR INVALID SURETY CODES REPORTED IN THE 10 RECORD). ADA OR CVD SURETY CODES ARE TRANSMITTED IN THE 35 REC, POS 49-51. SURETY CODES ARE REQUIRED ONLY WHEN THE BONDED INDICATOR FOR THE CASE NUMBER BEING REPORTED IS '1' (REPORTED IN POS 14 OF THE 35 REC). FOR ENTRIES WITH MULTIPLE ADD/CVD LINES, IF AT LEAST ONE LINE IS A BONDED CASE, THE SURETY CODE IN THE 35 RECORD IS REQUIRED. '000' IS THE MOST FREQUENTLY REPORTED INCORRECT SURETY CODE AND WILL CAUSE THIS MESSAGE TO BE ISSUED BY ACS. IF BLANKS ARE TRANSMITTED FOR THIS ELEMENT, MESSAGE 2AL WILL BE ISSUED.");
			aBIErrorCollection["2KW"] = new MessageError(errorCode: "2KW", shortDesc: "CLAIM DATE } 3 YEARS FROM EXPORT", narrative: "DRAWBACK D10 CLAIM DATE CANNOT BE } D11 EXPORT DATE + 3 YEARS. E.G. - IF EXPORT DATE = 000201 (YYMMDD), CLAIM DATE CANNOT BE }30201 (YYMMDD)");
			aBIErrorCollection["300"] = new MessageError(errorCode: "300", shortDesc: "REQUIRES OFF-LINE PROCESSING", narrative: "IN FDA 'WP' THIS MESSAGE IS 'INVALID REGISTRATION NUMBER'. THIS REFERS TO THE AOC 'PFR' AND IS ALMOST ALWAYS CAUSED BY THE FILER SENDING TOO FEW OR TOO MANY GIGITS. LENGTH IS 11 NUMERICS.");
			aBIErrorCollection["302"] = new MessageError(errorCode: "302", shortDesc: "RDP CHNG NOT VALID WITH DEBIT VCH", narrative: "A CHANGE TO THE DEPOSIT TICKET IS NOT VALID WHEN THERE IS AN ASSOCIATED DEBIT VOUCHER.  IN FDA 'WP' THIS MESSAGE IS 'INVALID BTA PN MANUF EXEMPTION IND'. THIS IS REFERRING TO AOC FME AND IT CANNOT BE BLANK IN THE QUALIFIER.");
			aBIErrorCollection["592"] = new MessageError(errorCode: "592", shortDesc: "INVALID ENTRY DISTRICT/PORT", narrative: "DISTRICT/PORT NON-NUMERIC OR NON-EXISTENT  FOR DRAWBACK ENTRY TYPES WHERE DATE OF ENTRY IS = OR } 10/01/94 ONLY THE FOLLOWING DISTRICT/PORT/TEAM COMBINATIONS WILL BE VALID:  DDPP / TEAM DDPP / TEAM  0401 1DA 2002 5LB  1001 2DB 5301 6D0  3901 3DR 2704 7D0  5201 4LA 2809 7D7");
			aBIErrorCollection["303"] = new MessageError(errorCode: "303", shortDesc: "DEB VCH RDP CANNOT BE CHANGED", narrative: "THE RDP CODE ON A DEBIT VOUCHER TXN CANNOT BE CHANGED. THE RDP IS STORED ON TH ASSOCIATED DEPOSIT TICKET AND CHANGING THE RDP DT WILL CHANGE THE RDP DV.  IN FDA 'WP' THIS MESSAGE IS 'INVALID SHIPPER REGISTRATION NUMBER'. THIS REFERS TO THE AOC SFR AND IS ALMOST ALWAYS CAUSED BY SENDING TOO FEW OR TOO MANY DIGITS. FIELD LENGTH IS 11 NUMERICS.  CAN ALSO BE CAUSED BY SENDING ALL ZEROES IN THE PFR AOC.  FOR IMPORTER SECURITY FILINGS, THIS ERROR WILL RETURN THE MESSAGE 'CONSIGNEE NUMBER RQUIRED.' A CONSIGNEE NUMBER IS ONE OF THE REQUIRED REPORTING ELEMENTS FOR A SECURITY FILING.");
			aBIErrorCollection["304"] = new MessageError(errorCode: "304", shortDesc: "SHORT REM GREATER THAN ORIG SHORT", narrative: "THE SHORTAGE REMAINDER AMOUNT IS GREATER THAN THE ORIGIONAL SHORTAGE AMOUNT.  FOR IMPORTER SECURITY FILING, THIS ERROR WILL RETURN THE MESSAGE 'MANUFACTURER NAME/ADDRESS REQUIRED.' A MNFTR (CODE MF) IS REQUIRED TO BE REPORTED FOR EVERY SECURITY FILING. IF AN SF30 RECORD IS TRANSMITTED WITHOUT A 'MF' CODE, THIS ERROR WILL RESULT. IF THE SF30 RECORD CONTAINS 'MF', BUT DOES NOT ALSO INCLUDE AN SF36 AND 36 RECORD FOR NAME AND ADDRESS INFORMATION, THIS ERROR WILL RESULT.");
			aBIErrorCollection["305"] = new MessageError(errorCode: "305", shortDesc: "RELEASE NOT ON FILE", narrative: "IN FDA 'WP' THIS MESSAGE IS 'INVALID OWNER FIRM TYPE'. CHECK APPENDIX O. THE VALID TYPES ARE 'M', 'C', 'I' AND 'U'.  FOR IMPORTER SECURITY FILING, THIS ERROR WILL RETURN THE MESSAGE 'SELLER NAME/ADDRESS REQUIRED.' A SELLER (CODE SE) IS REQUIRED TO BE REPORTED FOR EVERY SECURITY FILING. IF AN SF30 RECORD IS TRANSMITTED WITHOUT AN 'SE' CODE, THIS ERROR WILL RESULT. IF THE SF30 RECORD CONTAINS 'SE', BUT DOES NOT ALSO INCLUDE AN SF36 AND 36 RECORD FOR NAME AND ADDRESS INFORMATION, THIS ERROR WILL RESULT.");
			aBIErrorCollection["306"] = new MessageError(errorCode: "306", shortDesc: "OVERIDE WARNING ? (Y)", narrative: "FOR IMPORTER SECURITY FILING, THIS ERROR WILL RETURN THE MESSAGE 'BUYER NAME/ADDRESS REQUIRED.' A BUYER (CODE BY) IS REQUIRED TO BE REPORTED FOR EVERY SECURITY FILING. IF AN SF30 RECORD IS TRANSMITTED WITHOUT A 'BY' CODE, THIS ERROR WILL RESULT. IF THE SF30 RECORD CONTAINS 'BY', BUT DOES NOT ALSO INCLUDE AN SF36 AND 36 RECORD FOR NAME AND ADDRESS INFORMATION, THIS ERROR WILL RESULT.");
			aBIErrorCollection["307"] = new MessageError(errorCode: "307", shortDesc: "DEBIT VOUCH RDP CANNOT BE CHANGED", narrative: "THE DEBIT VOUCHER RDP CANNOT BE CHANGED.  FOR IMPORTER SECURITY FILING, THIS ERROR WILL RETURN THE MESSAGE 'SHIP TO PARTY NAME/ADDRESS REQUIRED. A SHIP-TO PARTY (CODE ST) MUST BE REPORTED FOR EVERY SECURITY FILING. IF AN SF30 RECORD IS TRANSMITTED WITHOUT AN 'ST' CODE, THIS ERROR WILL RESULT. IF THE SF30 RECORD CONTAINS 'ST', BUT DOES NOT ALSO INCLUDE AN SF36 AND 36 RECORD FOR NAME AND ADDRESS INFORMATION, THIS ERROR WILL RESULT.");
			aBIErrorCollection["308"] = new MessageError(errorCode: "308", shortDesc: "DT AMT LESS THAN ALL ORIG DV AMTS", narrative: "WHEN CHANGING THE DEPOSIT TICKET AMOUNT, THE NEW DT AMOUNT MUST BE GREATER THAN THE SUM TOTAL OF ALL ASSOCIATED ORIG DEBIT VOUCHER AMOUNTS.  FOR IMPORTER SECURITY FILING, THIS ERROR WILL RETURN THE MESSAGE 'CONSOLIDATOR NAME/ADDRESS REQUIRED.' A CONSOLIDATOR (CODE CS) IS REQUIREID TO BE REPORTED FOR EVERY SECURITY FILING. IF AN SF30 RECORD IS TRANSMITTED WITHOUT A 'CS' RECORD, THIS ERROR WILL RESULT. IF THE SF30 RECORD CONTAINS 'CS', BUT DOES NOT ALSO INCLUDE AN SF36 AND 36 RECORD FOR NAME AND ADDRESS INFORMATION, THIS ERROR WILL RESULT.  **NOTE** THIS 'ERROR' WILL BE A WARNING ONLY DURING AT LEAST THE FIRST YEAR OF PRODUCTION FOR ISF OR UNTIL CBP DEFINES A TIME FRAME AFTER WHICH THE OMISSION OF THE CONSOLIDATOR INFORMATION WILL BE CONSIDERED UNTIMELY AND WILL THEN BECOME AN ABI REJECT.");
			aBIErrorCollection["309"] = new MessageError(errorCode: "309", shortDesc: "CUSTOMS DT NUMBER ALREADY EXISTS", narrative: "THE CUSTOMS DT NUMBER ENTERED IS ALREADY ON THE DEPOSIT TICKET FILE.  FOR IMPORTER SECURITY FILINGS, THE CONTAINER STUFFING LOCATION IS ONE OF THE REQUIRED ELEMENTS.  **NOTE** THIS 'ERROR' WILL BE A WARNING ONLY DURING AT LEAST THE FIRST YEAR OF PRODUCTION FOR ISFOR UNTIL CBP DEFINES A TIME FRAME AFTER WHICH THE OMISSION OF THE CONSOLIDATOR INFORMATION WILL BE CONSIDERED UNTIMELYAND WILL THEN BECOME AN ABI REJECT.");
			aBIErrorCollection["310"] = new MessageError(errorCode: "310", shortDesc: "DEBIT VOUCHER(S) NOT FOUND FOR DT", narrative: "FOR IMPORTER SECURITY FILING, THIS ERROR WILL RETURN THE MESSAGE 'BOOKING PARTY NAME/ADDRESS REQUIRED.' IF AN ISF-5 IS TRANSMITTED, THE TRANSACTION MUST INCLUDE AN SF30 RECORD WITH ENTITY CODE 'BKP' IN POS 5-7 AND A NAME AND ADDRESS DATA SET IN THE SF30-36 RECORDS.");
			aBIErrorCollection["311"] = new MessageError(errorCode: "311", shortDesc: "DT NOT ON FILE FOR DV DIST/PORT", narrative: "THIS MESSAGE IS GENERATED WHEN DIST/PORT IS NOT THE SAME AS THE DT DIST/PORT  FOR IMPORTER SECURITY FILING, THIS ERROR WILL RETURN THE MESSAGE 'INVALID ENTITY CODE.' THE SF30 RECORD, POS 5-7, REQUIRES AN ENTITY CODE TO DESCRIBE THE TYPE OF COMPANY BEING REPORTED. VALID CODES ARE LISTED IN NOTE 1 TO THIS RECORD. IF A CODE OTHER THAN ONE OF THE ACCEPTABLE CODES IS SENT IN THIS ELEMENT, OR NO CODE IS INCLUDED, THIS ERROR WILL RESULT.");
			aBIErrorCollection["312"] = new MessageError(errorCode: "312", shortDesc: "INTENTIONAL POSTING", narrative: "TRANSPARENT TO USER; POSTED TO BCA AS 'INTENTIONAL POSTING'  FOR IMPORTER SECURITY FILINGS, THIS ERROR WILL RETURN THE MESSAGE 'MISSING ENTITY NAME.' THE SF 30, POSITION 8-42, REQUIRES A NAME FORTHE ENTITY DESCRIBED BY THE ENTITY CODE IN POS 5-7 OF THIS RECORD. IF A NAME IS NOT SUPPLIED AND THERE IS NO ENTITY IDENTITY QUALIFIER/ENTITY IDENTIFIER TRANSMITTED IN POS 43-45/46-65, THIS ERROR WILL RESULT.");
			aBIErrorCollection["313"] = new MessageError(errorCode: "313", shortDesc: "NEW DT NBR NOT IN SAME RDP", narrative: "THE CHANGE TO THE DEBIT VOUCHER UST NBR IS NOT IN THE SAME REGION/DIST/PORT.  FOR IMPORTER SECURITY FILING, THIS ERROR WILL RETURN THE MESSAGE 'MISSING ENTITY IDENTIFIER QUALIFIER.' IF THE ENTITY CODE IN THE SF30 RECORD, POS 5-7, IS CN, THEN ONE OF THE ACCEPTABLE QUALIFIERS FOR A CONSIGNEE IS REQUIRED (IRS NUMBER, SSN, CBP ASSIGNED NUMBER OR CBP ENCRYPTED CONSIGNEE ID NUMBER ARE THE CHOICES FOR A CONSIGNEE). ACCEPTABLE ENTITY IDENTIFIER CODES ARE LISTED IN NOTE 2 FOR THE SF 30 RECORD. IF NO CODE IS TRANSMITTED IN POS 43-45 OF THE SF30 RECORD, THIS ERROR WILL RESULT. VALID ENTITY IDENTIFIER QUALIFIER CODES FOR PARTIES OTHER THAN THE CONSIGNEE ARE ALSO LISTED IN NOTE 2");
			aBIErrorCollection["314"] = new MessageError(errorCode: "314", shortDesc: "DISTRICT/PORT/BROKER NOT UNIQUE", narrative: "CANNOT HAVE DUPLICATE KEY (DIST/PORT/BROKER) ON BROKER ENTRY FILE (ABE.)  FOR IMPORTER SECURITY FILING, THIS ERROR WILL RETURN THE MESSAGE 'INVALID ENTITY IDENTIFIER QUALIFIER.' IF THE SF30 RECORD IDENTIFIES THE CONSIGNEE, POS 5-6, AS THE REPORTED PARTY, THEN AN APPROPRIATE IDENTIFIER QUALIFIER CODE IS REQUIRED IN POSTION 43-35. IF POS 43-45 REPORTS A CODE NOT ALLOWED FOR A CONSIGNEE AS ENTITY CODE, THIS ERROR WILL RESULT. SEE NOTE 2 OF THE SF30 RECORD IN THE CATAIR CHAPTER FOR IMPORTER SECURITY FILING FOR A LIST OF ACCEPTABLE QUALIFIERS AND NUMBERS THAT CAN APPLY TO THE SPECIFIED ENTITY CODES.");
			aBIErrorCollection["329"] = new MessageError(errorCode: "329", shortDesc: "INVALID BROKER REMOTE NUMBER", narrative: "MUST BE NUMERIC; MUST BE ZERO FOR NON-ABI RECORDS.  IN FDA 'WP' THE MESSAGE IS 'ESTIMATED ARRIVAL DATE LESS THAN TODAY'S DATE'. THIS PHRASE IS NOT TRUE ANYMORE. THE EDIT IS THAT THE AOC 'EDA' MUST BE NO MORE THAN 10 DAYS IN THE PAST.");
			aBIErrorCollection["333"] = new MessageError(errorCode: "333", shortDesc: "DV AMT LESS THAN DV REM AMT", narrative: "THE DEBIT VOUCHER AMOUNT IS LESS THAN THE DEBIT VOUCHER REMAINING AMOUNT IN FDA 'WP' THE MESSAGE IS 'DUPLICATE AFFIRMATION ENTERED'. IN ONE SHIPMENT (I.E. ONE WP DATA SET) YOU CANNOT REPEAT AOC'S YOU MUST SEND A NEW DATA SET AND IT CAN BE IN THE SAME B-Y BLOCK.");
			aBIErrorCollection["33C"] = new MessageError(errorCode: "33C", shortDesc: "DATE OVER 90 DAYS INTO FUTURE", narrative: "THE END DATE CANNOT BE OVER 90 DAYS UNLESS IT IS INDEFINITE.  IN ADDITION TO THE ABOVE DEFINITION, IF ABI FILERS TRANSMIT ENTRY SUMMARY DATA WITH A PAYMENT DUE DATE MORE THAN 90 DAYS IN THE FUTURE, AS COMPARED TO THE TRANSMISSION DATE, THIS ERROR MESSAGE WILL BE GENERATED.");
			aBIErrorCollection["315"] = new MessageError(errorCode: "315", shortDesc: "CONTACT HQ CUSTOMER ASSISTANCE", narrative: "HQ CUSTOMER ASSISTANCE PHONE NBR IS 703-921-6000.  FOR IMPORTER SECURITY FILING, THIS ERROR WILL RETURN THE MESSAGE 'INVALID ENTITY IDENTIFIER.' IF THE REPORTED PARTY IS A CONSIGNEE (SF 30 RECORD, POS 5-6), THEN AN ENTITY IDENTIFIER (IRS, DUNS, SSN, ETC) IS REQUIRED. SEE NOTE 2 OF THE CATAIR CHAPTER FOR IMPORTER SECURITY FILING FOR A LIST OF ACCEPTABLE QUALIFIERS AND NUMBERS.");
			aBIErrorCollection["316"] = new MessageError(errorCode: "316", shortDesc: "DEPOSIT TICKET NOT ON FILE", narrative: "THIS MESSAGE IS GENERATED WHEN ENTERED DT NOT FOUND ON FILE  FOR IMPORTER SECURITY FILING, THIS ERROR WILL RETURN THE MESSAGE 'INVALID IRS FORMAT IN ENTITY IDENTIFIER.' THE ENTITY IDENTIFIER IS TRANSMITTED IN THE SF 30 RECORD, POS 46-54. IF AN IRS NUMBER IS USED FOR THIS ELEMENT, THE FORMAT MUST BE NN-NNNNNNNXX. THE 'XX' SUFFIX MUST BE INCLUDED. IF IT IS OMITTED, THIS ERROR WILL RESULT. ALSO, A CUSTOMS-ASSIGNED NUMBER OR A SOCIAL SECURITY NUMBER WILL CAUSE THIS ERROR.");
			aBIErrorCollection["317"] = new MessageError(errorCode: "317", shortDesc: "DEBIT VOUCHER NOT ON FILE", narrative: "THIS MESSAGE IS GENERATED WHEN ENTERED DV NUMBER IS NOT ON FILE  FOR IMPORTER SECURITY FILING, THIS ERROR WILL RETURN THE MESSAGE 'INVALID ANI FORMAT IN ENTITY IDENTIFIER.' THE SF30 RECORD, POS 43-45, IS USED TO TRANSMIT THE ENTITY IDENTIFIER QUALIFIER. IF THE ENTITY IS A CONSIGNEE (CN IN POS 5-7), AND THE ENTITY IDENTIFIER QUALIFIER IS ANI IN POS 43-45, THE ONLY VALID ENTITY IDENTIFIER IN POS 46-65 IS A CBP ASSIGNED NUMBER. ANY OTHER IDENTIFICATION NUMBER WILL CAUSE THIS ERROR.");
			aBIErrorCollection["318"] = new MessageError(errorCode: "318", shortDesc: "INVALID DUTY FREE INDICATOR", narrative: "VALID CODES: 'C' - CARIBBEAN BASIN INITIATIVE  FOR IMPORTER SECURITY FILING, THIS ERROR WILL RETURN THE MESSAGE 'INVALID CIN FORMAT IN ENTITY IDENTIFIER.' IN THE SF30 RECORD, THE ENTITY IDENTIFIER QUALIFIER IS IN POS 43-45. IF CODE CIN IS USED IN THIS FIELD, THE ONLY ACCEPTABLE ENTITY IDENTIFER IN POS 46-65 WILL BE AN ENCRYPTED CONSIGNEE ID NUMBER. ANY OTHER FORMAT FOR POS 46-65 WILL CAUSE THIS ERROR.  NOTE: 'CIN' CAN ONLY BE USED TO IDENTIFY A CONSIGNEE IN THE SF30 RECORD.");
			aBIErrorCollection["319"] = new MessageError(errorCode: "319", shortDesc: "END DATE PRECEDES START DATE", narrative: "DATES INCORRECT - THE END DATE PRECEDES THE START DATE.  FOR IMPORTER SECURITY FILING, THIS ERROR WILL RETURN THE MESSAGE 'INVALID SSN FORMAT IN ENTITY IDENTIFIER.' THE SF30 RECORD, POS 43-45, REPORTS THE ENTITY IDENTIFIER QUALIFIER. IF QUALIFIER '34' IS USED IN THIS FIELD, THE ENTITY IDENTIFIER IN POS 46-65 MUST BE A SOCIAL SECURITY NUMBER IN THE FORMAT NNN-NN-NNNN. ANY OTHER FORMATTED IDENTITY NUMBER WILL CAUSE THIS ERROR.");
			aBIErrorCollection["321"] = new MessageError(errorCode: "321", shortDesc: "MUST BE ZERO (NON-ABI DEFAULT)", narrative: "NON-ABI PORT/BROKER ENTRY RECORDS (ABE) MUST HAVE ZEROS IN MOST FIELDS  FOR IMPORTER SECURITY FILINGS, THIS ERROR WILL RETURN THE MESSAGE 'INVALID DUNS NUMBER IN ENTITY IDENTIFIER.' IF THE DUNS NUMBER REPORTED IN THE SF30 RECORD IS NOT ON FILE IN THE CBP DATABASE, THIS ERROR WILL RESULT. AS OF DEC 2008, THE FILE OF ACCEPTABLE DUNS NUMBERS IS NOT VISIBLE TO CLIENT REPS.");
			aBIErrorCollection["322"] = new MessageError(errorCode: "322", shortDesc: "INVALID BROKER MODE", narrative: "MUST BE NUMERIC; 0, 1, 2, OR 3.  FOR IMPORTER SECURITY FILING, THIS ERROR WILL RETURN THE MESSAGE 'INVALID ENTITY IDENTIFIER QUALIFIER.' IF THE ENTITY CODE IS ST IN THE SF30 RECORD, POS 5-7, THE ONLY ENTITY IDENTIFIER QUALIFIER CODES THAT ARE PERMITTED ARE DUN OR DNS (SEE NOTE 2 FOR THIS RECORD). ANY OTHER CODE TRANSMITTED IN POS 43-45 OF THE SF30 RECORD WILL GENERATE THIS ERROR.");
			aBIErrorCollection["324"] = new MessageError(errorCode: "324", shortDesc: "INVALID LIQUIDATION INDICATOR", narrative: "MUST BE NUMERIC; 0 OR 1.  FOR IMPORTER SECURITY FILING, THIS ERROR WILL RETURN THE MESSAGE 'INVALID ENTITY IDENTIFIER QUALIFIER.' ON A UNIFIED FTZ FILING, IF THE FILER TRANSMITS QUALIFIER CODE 'CIN' IN POS 43-45 OF THE SF30 RECORD, AND THE ENTITY CODE IN POS 4-7 OF THE SF30 RECORD IS 'CN', THIS ERROR WILL RESULT. 'CIN' IS LIMITED TO QUALIFYING A CONSIGNEE, NOT A MANUFACTURER.");
			aBIErrorCollection["325"] = new MessageError(errorCode: "325", shortDesc: "INVALID COLLECTION MODE", narrative: "MUST BE NUMERIC; 0 OR 1. FOR ABI BROKER STATEMENT CHECK YES OR NO  FOR IMPORTER SECURITY FILING, THIS ERROR WILL RETURN THE MESSAGE 'INVALID ENTITY IDENTIFIER QUALIFIER'. THE SF30 RECORD IDENTITY QUALIFIER CODE IS TRANSMITTED IN POS 43-45. FOR ENTITY CODE 'MF', QUALIFIER CODE 'CM' IS NOT ALLOWED UNLESS THE SECURITY FILING IS A UNIFIED FILING VIA 3461 OR 7501 INPUT. IF 'CM' IS USED ON A STAND ALONE ISF TRANSACTION, THIS ERROR WILL RESULT.");
			aBIErrorCollection["327"] = new MessageError(errorCode: "327", shortDesc: "INVALID DP-SITE DISTRICT/PORT", narrative: "THIS MESSAGE RESULTS WHEN A FILER SENDS AN 'A' RECORD DISTRICT/PORT/FILER SITE THAT DOES NOT EXIST IN THE ABE FILE. AN ABE RECORD MUST EXIST FOR THE TRANSMITTED DP-SITE DISTRICT/PORT. THIS WILL ALSO OCCUR IF ANY OTHER PORT CODE APPEARS IN THE 'B' RECORD AND NO PREEXISTING ABE RECORD IS ON FILE FOR THAT PORT. J0 4/28/98 (UPDATE 5-11-01) IN ADDITION TO THE ABOVE, FOR FILERS WHO HAVE OFFICE CODES IN THEIR ABE RECORDS, THIS MESSAGE WILL BE GENERATED IF THE PORT CODE IN THE 10 RECORD OF THE EI APPLICATION DOES NOT AGREE EXACTLY WITH THE PORT CODE IN THE 'B' RECORD. (NOTE 1 ON PAGE APL-6 OF THE CATAIR INDICATES THAT AGREEMENT BETWEEN APPLICATION DETAIL RECORDS AND THE 'B' RECORD MUST BE AT THE DISTRICT CODE LEVEL. THIS IS TRUE EXCEPT FOR OFFICE CODE SITUATIONS, WHICH REQUIRES AGREEMENT AT THE FOUR-DIGIT DDPP LEVEL).  THIS MESSAGE IN FDA 'WP' IS 'INVALID IMPORTER NUMBER OR FORMAT'. CHECK FOR MISSING DASHES. MUST CONFORM TO STANDARD IN EI/HI/HN.");
			aBIErrorCollection["332"] = new MessageError(errorCode: "332", shortDesc: "WAREHOUSE SUMMARY NOT ON FILE", narrative: "A WAREHOUSE SUMMARY MUST BE ON FILE BEFORE A WAREHOUSE WITHDRAWAL CAN BE MADE. ACDA WILL NOT CREATE A COLL SHELL RECORD IF CLASS CODE 002 OR 092 IS } $0.00. IF CLASS CODE 002 OR 092 IS } $0.00, THEN A PF 8 KEY TO OVERRIDE WILL BE DISPLAYED. IF PF8 IS DEPRESSED, THEN THE WITHDRAWAL WILL BE POSTED TO THE BCA. THE WAREHOUSE SUMMARY MUST BE INPUT FIRST USING THE FUNCTION CODE 'ENAA' TO PREVENT THE WITHDRAWAL FROM BEING POSTED TO THE BCA.  FOR ABI INBOND (QP) TRANSMISSIONS, THIS ERROR CODE WILL RETURN THE MESSAGE: 'CARRIER CODE IN DELETED STATUS.' THE CARRIER CODE REPORTED IN THE QP10, QP20, AND/OR QP40 RECORD IS IN DELETED STATUS ON CARL.");
			aBIErrorCollection["343"] = new MessageError(errorCode: "343", shortDesc: "LAST ENTRY NBR IN RANGE OVERLAPS", narrative: "ENTRY NUMBER ASSIGNMENT  -THE LAST ENTRY NUMBER EITHER MATCHES OR OVERLAPS AN EXISTING ASSIGNMENT RANGE ON THE FILE FOR THE SAME PORT AND BROKER.  FOR ABI INBOND (QP) TRANSMISSIONS, THIS ERROR CODE WILL RETURN THE MESSAGE: 'INVALID BILL TYPE.' INBONDS VIA QP CAN BE TRANSMITTED FOR MASTER BILLS OR REGULAR BILLS ONLY. IF THE FILER SENDS A QP AGAINST ANY OTHER TYPE OF BILL, INCLUDING NVO BILLS (HOUSE BILLS) OR F.R.O.B. BILLS, THIS ERROR WILL RESULT. THIS ERROR WILL ALSO OCCUR IF THE SCAC OF THE IMPORTING CARRIER IS CODED AS NVOCC ON CARL. CARL MUST SHOW THE SCAC AS A CARRIER.");
			aBIErrorCollection["344"] = new MessageError(errorCode: "344", shortDesc: "ENTRY RANGE EXISTS ON FILE", narrative: "ENTRY NUMBER ASSIGNMENT  -NEITHER THE HIGH OR THE LOW IS WITHIN EXISTING RANGE BUT IT STILL OVERLAPS EXISTING RANGE.  FOR ABI INBOND (QP) TRANSMISSIONS, THIS ERROR CODE WILL RETURN THE MESSAGE: 'INVALID ENTRY TYPE FOR FDA/BTA.' IF THE QP INPUT IS FOR AN I.E., TYPE 63 INBOND, THE BTA INDICATOR IN THE QP 10 RECORD MUST BE 'N'.");
			aBIErrorCollection["349"] = new MessageError(errorCode: "349", shortDesc: "NO RECORD FOUND FOR DELETION", narrative: "THE RECORD IDENTIFIED IN THE REQUEST FOR DELETION (UPDATE ACTION CODE = D) DOES NOT EXIST.");
			aBIErrorCollection["385"] = new MessageError(errorCode: "385", shortDesc: "COUNTRY ON GSP EXCLUSION (TSUSA)", narrative: "PROPERLY ENTERED GSP-INDICATOR ('A'), AND OTHERWISE VALID GSP-COUNTRY RESULT IN AN INVALID GSP CLAIM BECAUSE GSP-COUNTRY IS ON THE 'EXCLUSION LIST' FOR THE DUTIABLE TSUSA NUMBER.  SEE PAGES 4 AND 5 OF THE TSUSA (GENERAL HEADNOTES) FOR A COMPLETE LIST OF ELIGIBLE COUNTRIES.");
			aBIErrorCollection["34D"] = new MessageError(errorCode: "34D", shortDesc: "CANT DELETE WHILE ENTRIES PRESENT", narrative: "THIS MESSAGE MAY APPLY TO SEVERAL APPLICATIONS IN ABI. FOR PROTESTS, THIS MESSAGE ADVISES THE FILER THAT A PROTEST MAY NOT BE DELETED WHILE ONE OR MORE ENTRIES ARE STILL ON FILE FOR THE PROTEST NUMBER IN QUESTION. FOR AUTOMATED INVOICE TRANSMISSIONS, THIS MESSAGE INDICATES THAT INDIVIDUAL INVOICES MAY NOT BE DELETED ONCE AN ENTRY IS ON FILE IN ACS FOR THAT INVOICE NUMBER.");
			aBIErrorCollection["351"] = new MessageError(errorCode: "351", shortDesc: "NO ENTRY NUMBER ENTERED", narrative: "ENTRY NUMBER ASSIGNMENT -NO ENTRY NUMBER ASSIGNMENT RANGE ON FILE.  FOR ABI INBOND (QP) TRANSMISSIONS, THIS ERROR CODE WILL RETURN THE MESSAGE: 'INBOND QTY GREATER THAN BILL QTY.' THE QP30 RECORD REQUIRES A QUANTITY TO BE REPORTED IN POS 69-78. IF THE REPORTED QUANTITY IS GREATER THAN THE MANIFESTED QUANTITY FOR THE BILL IN THE QP30 RECORD, THIS ERROR MESSAGE WILL BE GENERATED.");
			aBIErrorCollection["352"] = new MessageError(errorCode: "352", shortDesc: "TOTAL DUTIES DO NOT MATCH", narrative: "FOR ABI INBOND (QP) TRANSMISSIONS, THIS ERROR CODE WILL RETURN THE MESSAGE: 'INBOND OR BILL DELETE DENIED.' IF THE QP DELETE TRANSACTION REFERENCES A BILL NUMBER THAT HAS AN INBOND POSTED BY A METHOD OTHER THAN QP, QP CANNOT BE USED TO DELETE THE INBOND CREATED BY THE OTHER METHOD. EXAMPLES WOULD BE INBONDS FROM CAFES, THOSE POSTED MANUALLY BY CBP OFFICERS, OR INBONDS INVOLVING FTZ WITHDRAWALS.  NOTE: IF THE INBOND WAS CREATED BY AN ABI QP TRANSACTION, BUT THE ARRIVAL WAS DONE BY A CBP OFFICER, QP WILL NOT ALLOW THE FILER TO DELETE THE INBOND.  FOR SECURITY FILING, THIS ERROR WILL RETURN THE MESSAGE 'INVALID ADDRESS COMPONENT QUALIFIER.' THE SF35 RECORD REQUIRES A TWO CHARACTER ADDRESS QUALIFIER CODE IN POS 5-6 AND 42-43. IF THESE FIELDS ARE BLANK, OR REPORT A CODE NOT LISTED IN NOTE 1 TO THIS RECORD, THIS ERROR WILL RESULT.");
			aBIErrorCollection["353"] = new MessageError(errorCode: "353", shortDesc: "ENTRY ALREADY LIQUIDATED", narrative: "THIS MESSAGE OCCURS IN THE 'REVISED FILER DATE' (DN) TRANSACTION WHEN A FILER TRANSMITS A REVISED ENTRY DATE FOR AN ENTRY THAT IS LIQUIDATED.  FOR IMPORTER SECURITY FILING, THIS ERROR WILL RETURN THE MESSAGE 'MISSING ADDRESS COMPONENT.' THE SF35 RECORD, POS 7-41 AND 44-78 ALLOW THE FILER TO REPORT VARIOUS COMPONENTS OF THE ADDRESS OF THE PARTY REPORTED IN THE SF30 RECORD. IF BOTH FIELDS, OR THE FIRST FIELD (POS 7-41) IS BLANK, THIS ERROR WILL RESULT.");
			aBIErrorCollection["355"] = new MessageError(errorCode: "355", shortDesc: "ENTRY NOT FOUND", narrative: "THIS MESSAGE OCCURS WHEN A FILER ATTEMPTS TO USE THE 'HP' STATEMENT ADD/DELETE TRANSACTION FOR AN ENTRY THAT IS NOT FOUND ELIGIBLE FOR AN 'HP'. AN EXAMPLE WOULD BE AN ENTRY THAT HAS BEEN ARCHIVED (ENX).  FOR ABI INBOND (QP) TRANSMISSIONS, THIS ERROR CODE WILL RETURN THE MESSAGE: 'MISSING INBOND QUANTITY.' FOR QP INPUT TRANSACTIONS, THE QUANTITY OF BILL NUMBER MUST BE TRANSMITTED IN THE QP30 RECORD (AMS BILLS) OR THE QP40 RECORD (NON-AMS BILLS). THE QUANTITY MUST BE A WHOLE NUMBER GREATER THAN ZERO.");
			aBIErrorCollection["35C"] = new MessageError(errorCode: "35C", shortDesc: "INVALID IMPORTER NUMBER FORMAT", narrative: "ENTERED IMPORTER NUMBER DOES NOT CONFORM TO THE IRS, SSN OR CUSTOMS ASSIGNED NUMBER.  NOTE: ALPHA CHARACTERS 'O' (OH) 'I' (EYE) AND 'Z' (ZEE) ARE NOT PERMITTED");
			aBIErrorCollection["35P"] = new MessageError(errorCode: "35P", shortDesc: "LN TRANS NOT PERMITTED", narrative: "LN TRANSACTION NOT PERMITTED WHILE DOCUMENT DISCREPANCY HOLD IS ON.");
			aBIErrorCollection["360"] = new MessageError(errorCode: "360", shortDesc: "REJ NOT ALL'D-ENTRY IS ABI STATUS", narrative: "ENTRY IS IN ABI STATUS. PERFORM ENAX TO PLACE SUMMARY IN CUSTOMS' STATUS AND THEN REJECT.  FOR ABI INBOND (QP) TRANSMISSIONS, THIS ERROR CODE WILL RETURN THE MESSAGE: 'INVALID PEDIMENTO NUMBER.' IF THE QP FILER REPORTS A Q33 RECORD WITH QUALIFIER 'FEN', THE NEXT FIELD (POS 6-35) MUST CONTAIN A 15 NUMERIC PEDIMENTO NUMBER. IF THE FIELD IS LONGER OR SHORTER THAN 15 CHARACTERS OR CONTAINS ALPHA CHARACTERS, THIS ERROR WILL RESULT.  THE FORMAT FOR THE PEDIMENTO NUMBER IS:  YY (CALENDAR YEAR LAST TWO DIGITS) PP (MEXICAN CUSTOMS PORT CODE BBBB (MX BROKER CODE) DDDDDDD (DOCUMENT NUMBER)");
			aBIErrorCollection["361"] = new MessageError(errorCode: "361", shortDesc: "IT CHECK DIGIT ERROR", narrative: "THIS ERROR MESSAGE WILL RESULT IF AN AIR WAYBILL NUMBER OR A CONVENTIONAL INBOND NUMBER (9 NUMERIC) IS TRANSMITTED WITH AN INCORRECT CHECK DIGIT. NOTE: IF THE CHECK DIGIT ERROR OCCURS ON A PAPERLESS MASTER INBOND NUMBER THOSE STARTING WITH 'V'), ERROR MESSAGE 2CI WILL BE GENERATED. THE AMS SYSTEM WILL ACCEPT A TRANSMISSION WITH AN INCORRECT CHECK DIGIT. CHECK AMS FOR THE BILL OF LADING OR IN-BOND NUMBER. IF IT IS IN AMS, RUN THE NUMBER THROUGH THE ROSCOE CHECK DIGIT CALCULATOR. IF AMS HAS THE INCORRECT CHECK DIGIT, ADVISE THE ABI FILER THAT THE AMS CARRIER NEEDS TO CORRECT AND RE-TRANSMIT WITH THE PROPER CHECK DIGIT.  FOR ABI INBOND (QP) TRANSMISSIONS, THIS ERROR CODE WILL RETURN THE MESSAGE: 'INVALID DEPARTURE PORT.' QP20 REC,POS 46-49, PORT OF IMPORT ARRIVAL IS THE SAME AS THE PORT OF DEPARTURE FOR INBONDS. IF THIS PORT CODE IS NOT LISTED ON GODL AS 'YES' FOR THE DEPARTURE COLUMN, THIS ERROR WILL RESULT..  FOR ISF, A CITY NAME IS REQUIRED IN THE SF36 RECORD.");
			aBIErrorCollection["362"] = new MessageError(errorCode: "362", shortDesc: "DWBK CHECK ALREADY ISSUED", narrative: "FOR SECURITY FILING, THIS ERROR WILL RETURN THE MESSAGE 'INVALID COUNTRY CODE' THE SF36 RECORD REQUIRES A COUNTRY CODE IN POSITION 64-65. IF AN INVALID ISO CODE OR A BLANK IS TRANSMITTED, THIS ERROR WILL RESULT.  FOR ABI INBOND (QP) TRANSMISSIONS, THIS ERROR CODE WILL RETURN THE MESSAGE: 'PEDIMENTO REQUIRED.' IF THE QP TRANSACTION IS A TYPE 62 OR 63 WITH A DESTINATION IN MEXICO, A PEDIMENTO NUMBER MUST BE REPORTED.");
			aBIErrorCollection["365"] = new MessageError(errorCode: "365", shortDesc: "IR TAX NOT APPLICABLE", narrative: "IF THE TSUSA TAX CODE = '0', THE LINE ITEM INTERNAL REVENUE FIELD MUST BE BLANK ('ENC' RECORD -- LINE ITEM EDIT, SPX453B).  IF THE HSAS FILE FOR THE REJECTED TARIFF NUMBER DOES NOT INDICATE THAT IRS EXCISE TAXES ARE APPLICABLE, THIS MESSAGE WILL RESULT IF AN ABI FILER TRANS- MITS IR TAX DATA IN REC 60, POS 59-68.");
			aBIErrorCollection["366"] = new MessageError(errorCode: "366", shortDesc: "ENTRY ALREADY CANCELED", narrative: "THIS MESSAGE OCCURS WHEN A FILER ATTEMPTS TO SEND A DELETE 'D' ACTION CODE IN AN ENTRY SUMMARY SEND FOR AN ENTRY SUMMARY THAT HAS BEEN CANCELED BY CUSTOMS. (042498) OR IF THE FILER ATTEMPTS TO RETRANSMIT THE SUMMARY WITH A CODE OF 'A' OR 'R'.");
			aBIErrorCollection["370"] = new MessageError(errorCode: "370", shortDesc: "ENTRY BELONGS TO ANOTHER DD/PP", narrative: "THIS ERROR MESSAGE OCCURS WHEN A FILER SENDS AN ENTRY SUMMARY TRANSACTION FOR AN ENTRY THAT WAS RELEASED (OR AT LEAST ACCEPTED) AT ANOTHER PORT. THE SSAI RECORD WILL SHOW THE PORT CODE ESTABLISHED BY THE FILER'S FIRST SUCCESSFUL ABI TRANSMISSION. IF THE FILER'S SUMMARY INPUT PORT CODE (10 REC, POS 4-7) DOES NOT MATCH THE PORT CODE ON THE SSAI RECORD, THIS ERROR MESSAGE WILL RESULT. THIS ERROR WILL ALSO RESULT IF THE FILER TRANSMITS A CARGO RELEASE TRANSACTION THAT DOES NOT MATCH THE PORT CODE IN THE H1 REC, POS 4-7, TO THE PORT CODE SHOWN ON THE ENAI RECORD FROM THE FILER'S PRIOR TRANSMISSION. IF THE SSAI RECORD PORT CODE IS INCORRECT, THE FILER SHOULD FOLLOW LOCAL PROCEDURES IN ORDER TO BE ABLE TO RETRANSMIT THE SUMMARY WITH THE CORRECT PORT CODE ONCE THE SSAI RECORD HAS BEEN CHANGED. IF THERE IS AN ENTRY SUMMARY ON FILE, AND STILL IN ABI STATUS, THE FILER MAY DELETE THE SUMMARY AND RETRANSMIT IT WITH THE CORRECT PORT CODE.");
			aBIErrorCollection["381"] = new MessageError(errorCode: "381", shortDesc: "ORIGIN COUNTRY INVALID - UNKNOWN", narrative: "INVALID COUNTRY OF ORIGIN - NOT ON FILE. FOR THE EI APPLICATION, REC 40, POS 6-7 IS BLANK OR CONTAINS A TWO CHARACTER ISO CODE THAT IS NOT PRESENT IN THE RFJ FILE, THIS MESSAGE WILL RESULT.");
			aBIErrorCollection["382"] = new MessageError(errorCode: "382", shortDesc: "ORIGIN COUNTRY: IMPRTS RESTRICTED", narrative: "THIS MESSAGE IS GENERATED IN THE HI/HN TRANSACTION WHEN A COUNTRY OF ORIGIN IS TRANSMITTED THAT IS IN THE RFJ (COUNTRY CODE) FILE AS A RESTRICTED COUNTRY. NO IMPORTS ARE ALLOWED. THE MESSAGE IN THE EI TRANSACTION IS '38N'.");
			aBIErrorCollection["371"] = new MessageError(errorCode: "371", shortDesc: "IR TAX REQUIRED", narrative: "IF TSUSA FLAG= '1', AN INTERNAL REVENUE TAX APPLIES AND MUST BE INPUT ON THE LINE ITEM ENTRY ('ENC' RECORD -- LINE ITEM EDIT, SPX453B).  IF THE HSAS FILE INDICATES THAT THE TARIFF NUMBER IS SUBJECT TO IRS EXCISE TAXES, THIS MESSAGE WILL BE GENERATED IF NO TAX AMOUNT IS TRANSMITTED IN THE 60 RECORD, POS 59-68. NOTE THAT IN THOSE INSTANCES WHERE THE FILER IS AUTHORIZED TO PAY LESS TAX (OR INADVENTENTLY TRANSMITS INCORRECT TAX), THAN THE STATUATORY TAX RATE WOULD INDICATE, ERROR MESSAGE 42N - 'WARNING - EST TAX { COMPUTED TAX' WILL RESULT. NOTE - THIS MESSAGE WILL RESULT IF THE PRIMARY IR TAX RATE IS ZERO AND THE FILER SENDS ZERO TAX. THE TAX FLAG = 1 IS WHAT DETERMINES THAT SOME AMOUNT OF IRS TAX IS DUE.");
			aBIErrorCollection["383"] = new MessageError(errorCode: "383", shortDesc: "COUNTRY OF EXPORT INVALID", narrative: "THIS MESSAGE WILL RESULT IF THE ABI FILER TRANSMITS AN ENTRY SUMMARY OR CARGO RELEASE TRANSACTION WITH A TWO-CHARACTER COUNTRY CODE (ISO CODE) THAT DOES NOT APPEAR ON THE RFJL DATABASE. FOR SHIPMENTS FROM CANADA, THE TWO-CHARACTER CODE IS CA, NOT THE PROVINCE-OF-ORIGIN CODE (X-) THAT MUST BE USED FOR COUNTRY OF ORIGIN REPORTING. A BLANK COUNTRY OF EXPORT FIELD WILL ALSO GENERATE THIS ERROR MESSAGE, AS WILL 'US' IN THIS FIELD.");
			aBIErrorCollection["384"] = new MessageError(errorCode: "384", shortDesc: "EXPORT DATE INVALID/CONFLICTING", narrative: "THE EXPORT DATE TRANSMITTED BY THE ABI FILER IS NOT CHRONOLOGICALLY CONSISTENT WITH THE IMPORT DATE OR WITH ANOTHER DATE IN THE SUMMARY INPUT TRANSACTION. THUS, IF THE IMPORT DATE IS REPORTED TO ABI AS JULY 12, 1997, THE EXPORT DATE MUST BE A DATE EQUAL TO JULY 12 OR EARLIER. THIS ERROR WILL ALSO RESULT IF THE EXPORT DATE FIELD IS BLANK (50 REC, POS 71-76).  IF A FILER HAS SENT AN ENTRY DATE UPDATE (DN APPLICATION) AND THAT DATE IS REFLECTED IN THE 'FLR ENT DATE' FIELD OF THE ENAM SCREEN FOR THE ENTRY, ANY EXPORT DATE WHICH IS LATER THAN THE UPDATED ENTRY DATE ESTABLISHED BY THE DN INPUT WILL ALSO CAUSE THIS MESSAGE TO BE ISSUED.");
			aBIErrorCollection["386"] = new MessageError(errorCode: "386", shortDesc: "GSP COUNTRY EXP/ORIG CONFLICT", narrative: "THE COUNTRY OF ORIGIN (40 RECORD, POS 6-7) AND THE EXPORT COUNTRY (50 REC, POS 69-70) MUST BE THE SAME AND MUST BOTH BE GSP ELIGIBLE TO CLAIM A DUTY EXEMPTION UNDER SPI 'A' (REC 50, POS 3). IF THE COUNTRY OF EXPORT IS A MEMBER OF AN ASSOCIATION OF COUNTRIES (ASEAN, FOR EXAMPLE), THE COUNTRY OF EXPORT MAY DIFFER FROM THE COUNTRY OF ORIGIN WITHOUT VIOLATING THE GSP PROVISIONS.");
			aBIErrorCollection["388"] = new MessageError(errorCode: "388", shortDesc: "WARNING-CAR.BASIN INIT. MAY APPLY", narrative: "THE CARIBBEAN BASIN INITIATIVE (CBI) MAY APPLY. SEE PAGE 7 OF THE TSUSA (GENERAL HEADNOTES).  NOTE: THIS ERROR USUALLY OCCURS IN CONJUNCTION WITH ERROR MESSAGE 391 ('CLAIM INVALID FOR EXPORT COUNTRY) WHEN SPI 'W' IS TRANSMITTED ON AN ENTRY SUMMARY WITH AN EXPORT COUNTRY THAT IS NOT A CBI COUNTRY. REMOVING THE 'W' WILL USUALLY ELIMINATE THIS WARNING MESSAGE, AS WELL.");
			aBIErrorCollection["38N"] = new MessageError(errorCode: "38N", shortDesc: "RESTRICTED COUNTRY", narrative: "THE IMPORT RESTRICTION INDICATOR FOR THIS COUNTRY IS '1' ON THE RFJ FILE. THIS INDICATES THAT THIS COUNTRY IS RESTRICTED FROM IMPORTING TO THE U.S. OR THAT THE COUNTRY'S CODE HAS BEEN RENDERED INACTIVE OR INVALID. SINCE THERE IS NO INACTIVE/INVALID CODE IN THE RFJ FILE THE ONLY WAY TO PREVENT USE IS BY MAKING THE COUNTRY 'RESTRICTED'. AN EXAMPLE OF THIS IS THE COUNTRY CODE 'SQ' FOR SLOVAKIA. EFFECTIVE 03/01/93, THIS COUNTRY CODE WAS NO LONGER VALID. IT CHANGED TO 'SK'. A FILER MIGHT BE MISLED BY THE 'RESTRICTED' INDICATOR THEY RECEIVE BACK ON A QUERY OR BY THIS MESSAGE WHEN TRANSMITTING AN ENTRY AND RECEIVING A REJECT. THIS LATTER TYPE OF COUNTRY CODE IS 'INVALID' RATHER THAN RESTRICTED. RFJL 7/COUNTRY NAME WILL HELP IN FINDING THE CORRECT COUNTRY CODE.  NOTE: AS OF JUNE 2008, THE ABOVE INFORMATION APPLIES ONLY TO THE COUNTRY OF ORIGIN FIELD. A RESTRICTED COUNTRY CODE WILL NOT BE EDITED IF IT IS USED IN THE COUNTRY OF EXPORT FIELD.  THE IMPORT RESTRICTION INDICATOR FOR THIS COUNTRY IS '1' ON THE RFJ FILE. THIS INDICATES THAT THIS COUNTRY IS RESTRICTED FROM IMPORTING TO THE U.S. OR THAT THE COUNTRY'S CODE HAS BEEN RENDERED INACTIVE OR INVALID. SINCE THERE IS NO INACTIVE/INVALID CODE IN THE RFJ FILE THE ONLY WAY TO PREVENT USE IS BY MAKING THE COUNTRY 'RESTRICTED'. AN EXAMPLE OF THIS IS THE COUNTRY CODE 'SQ' FOR SLOVAKIA. EFFECTIVE 03/01/93, THIS COUNTRY CODE WAS NO LONGER VALID. IT CHANGED TO 'SK'. A FILER MIGHT BE MISLED BY THE 'RESTRICTED' INDICATOR THEY RECEIVE BACK ON A QUERY OR BY THIS MESSAGE WHEN TRANSMITTING AN ENTRY AND RECEIVING A REJECT. THIS LATTER TYPE OF COUNTRY CODE IS 'INVALID' RATHER THAN RESTRICTED. RFJL 7/COUNTRY NAME WILL HELP IN FINDING THE CORRECT COUNTRY CODE.  NOTE: AS OF JUNE 2008, THE ABOVE INFORMATION APPLIES ONLY TO THE COUNTRY OF ORIGIN FIELD. A RESTRICTED COUNTRY CODE WILL NOT BE EDITED IF IT IS USED IN THE COUNTRY OF EXPORT FIELD.");
			aBIErrorCollection["38P"] = new MessageError(errorCode: "38P", shortDesc: "WARNING-EXP DATE}FILER ENT DATE", narrative: "THE EXPORT DATE WAS FOUND TO BE GREATER THAN REVISED FILER ENTRY DATE.");
			aBIErrorCollection["391"] = new MessageError(errorCode: "391", shortDesc: "CLAIM INVALID FOR EXPORT COUNTRY", narrative: "CERTAIN SPECIAL PROGRAMS (GSP, FOR ONE) REQUIRE THAT THE EXPORT COUNTRY BE ELIGIBLE FOR THE PROGRAM AS WELL AS THE ORIGIN COUNTRY. IF THE EXPORT COUNTRY IS NOT ELIGIBLE FOR THE SPECIAL PROGRAM, THIS ERROR MESSAGE WILL BE GENERATED.");
			aBIErrorCollection["392"] = new MessageError(errorCode: "392", shortDesc: "CLAIM INVALID FOR ORIGIN COUNTRY", narrative: "THIS MESSAGE IS GENERATED WHEN A FILER ATTEMPTS TO CLAIM A SPECIAL PROGRAM (SPI) THAT DOES NOT PERTAIN TO THE COUNTRY OR PROVINCE OF ORIGIN THAT IS TRANSMITTED BY THE FILER. THE VARIOUS SPI'S ARE LISTED IN THE CATAIR ON PAGES ENS-46 AND 47. SOME OF THE SPI'S LISTED ARE NOT COUNTRY SPECIFIC, SUCH AS 'K', 'L', AND 'F'. FOR THOSE THAT ARE COUNTRY-SPECIFIC, ONLY THE APPROPRIATE COUNTRY OF ORIGIN WILL BE PERMITTED FOR THE PARTICULAR SPI.  NOTE: IF THE TARIFF NUMBER CLAIMED AS GSP IS CODED WITH AN 'A+' ON THE HSA DATABASE, BUT THE FILER'S COUNTRY OF ORIGIN IS NOT COLUMN 3, THIS ERROR MESSAGE WILL BE GENERATED.");
			aBIErrorCollection["395"] = new MessageError(errorCode: "395", shortDesc: "GROSS WEIGHT MISSING/INVALID", narrative: "GROSS WEIGHT NOT NUMERIC, OR MISSING WHEN REQUIRED (MODE-OF-TRANS '10' '11' '40') LINE-ITEM NET WEIGHT (IN POUNDS) EXCEEDS ENTERED GROSS WEIGHT.");
			aBIErrorCollection["39B"] = new MessageError(errorCode: "39B", shortDesc: "INVALID DUTY FREE CLAIM", narrative: "THIS MESSAGE WILL OCCUR IF THE FILER ATTEMPTS TO MAKE A DUTY-FREE CLAIM THAT IS NOT APPROPRIATE TO THE COUNTRY OF ORIGIN/COUNTRY EXPORT COMBINATION. FOR EXAMPLE, INSULAR POSSESSIONS (SPI 'Y') ARE ENTITLED TO SHIP CARGO DUTY FREE TO THE UNITED STATES, BUT ONLY IF THE SHIPMENT COMES DIRECTLY FROM THE POSSESSION. THEREFORE, IF THE COUNTRY OF EXPORT (50 REC, POS 69-70) IS NOT IDENTICAL TO THE COUNTRY OF ORIGIN (40 REC, POS 6-7), AND THE FILER TRANSMITS 'Y' IN POS 3 OF THE 50 RECORD, THIS ERROR WILL RESULT.  THIS MESSAGE WILL BE GENERATED IF SPI 'Y' IS USED FOR AMERICAN GOODS RETURNED PRODUCTS (CHAPT 98010010NN), AS THESE ARTICLES ARE UNCONDITIONALLY FREE OF DUTY AND THEREFORE DO NOT REQUIRE A SPECIAL PROGRAM IN ORDER TO CLAIM DUTY-FREE STATUS.");
			aBIErrorCollection["3A0"] = new MessageError(errorCode: "3A0", shortDesc: "INVALID PASSWORD", narrative: "THIS MESSAGE INDICATES THAT THE FILER'S SIX CHARACTER PASSWORD, TRANSMITTED IN THE 'A' RECORD, POS 9-14, IS EITHER MISSING OR DOES NOT EXACTLY MATCH THE PASSWORD ON THE ABE RECORD.");
			aBIErrorCollection["4F8"] = new MessageError(errorCode: "4F8", shortDesc: "COUNTRY CODE INVALID", narrative: "COUNTRY CODE MUST BE VALID, ALPHABETIC ISO CODE (RFD), OR 99 FOR A GLOBAL QUOTA. 99 MAY ONLY BE USED BY HEADQUARTERS QUOTA.  IF THE FIELD CONTAINS NUMBERS OTHER THAN 99, IS LEFT BLANK, OR IS NOT A VALID ISO CODE, THIS MESSAGE WILL BE PROVIDED.");
			aBIErrorCollection["590"] = new MessageError(errorCode: "590", shortDesc: "TOTAL EST. AD DUTY EXCEEDS LIMIT", narrative: "TOTAL ESTIMATED ANTI-DUMPING DUTY EXCEEDS THE LIMIT");
			aBIErrorCollection["3A5"] = new MessageError(errorCode: "3A5", shortDesc: "SELECTIVITY ALREADY PERFORMED", narrative: "THIS MESSAGE OCCURS WHEN A FILER ATTEMPTS TO SEND SELECTIVITY DATA FOR AN ENTRY NUMBER WHERE SELECTIVITY HAS ALREADY BEEN PERFORMED, EITHER ELECTRONICALLY OR BY MANUAL PROCESSING. THIS MESSAGE DOES NOT OCCUR IF THE FILER SENDS SELECTIVITY DATA FOR AN ENTRY THAT RECEIVED AN INITIAL SELECTIVITY RESPONSE OF 'PAPERLESS'. IN THIS CASE THE FILER WILL RECEIVE MESSAGE 681 'CUSTOMS REL VIA EREL ON FILE'.  NOTE: IN SOME CASES, THIS MESSAGE WILL ACCOMPANY THE MESSAGE 'OGA DATA IGNORED' AND IF THE INPUT APPLICATION WAS FROM AN ENTRY SUMMARY, THESE TWO MESSAGES WILL NOT CAUSE A REJECTION.  IF THE TARIFF NUMBER INVOLVED IN AN 'OGA DATA IGNORED' MESSAGE IS A FD3 YOU WILL SEE 'PN' IN POSITIONS 3-4 OF THE OA RECORD. THIS IS NORMAL.");
			aBIErrorCollection["400"] = new MessageError(errorCode: "400", shortDesc: "GSP CLAIM INVALID FOR THIS TARIFF", narrative: "IF THE FILER TRANSMITS A GSP INDICATOR 'A' (50 REC, POS 3, OR 70/80/81 REC, POS 79), FOR A TARIFF NUMBER THAT IS NOT ELIGIBLE FOR GSP, THIS ERROR MESSAGE WILL BE GENERATED.");
			aBIErrorCollection["401"] = new MessageError(errorCode: "401", shortDesc: "CBI CLAIM INVALID FOR THIS TARIFF", narrative: "THIS MESSAGE ADVISES THE FILER THAT THE TARIFF NUMBER ON THE REJECTED LINE HAS A CBI CLAIM (SPI = 'E'), BUT THE HSA FILE RECORD FOR THE TARIFF NUMBER IS NOT CODED FOR THIS SPECIAL PROGRAM.");
			aBIErrorCollection["402"] = new MessageError(errorCode: "402", shortDesc: "SELECT 1 REPORT ONLY", narrative: "FOR IMPORTER SECURITY FILING, THIS ERROR WILL RETURN THE MESSAGE 'MIN. ONE COMMODITY RECORD REQUIRED.' EACH SECURITY FILING MUST CONTAIN AT LEAST ONE HARMONIZED TARIFF NUMBER IN THE SF40 RECORD. IF NO SF40 RECORDS ARE TRANSMITTED, THIS ERROR WILL RESULT.");
			aBIErrorCollection["403"] = new MessageError(errorCode: "403", shortDesc: "FROM-DATE GREATER THAN TO-DATE", narrative: "FOR IMORTER SECURITY FILINGS, THIS ERROR WILL RETURN THE MESSAGE 'MISSING HARMONIZED NUMBER.' THE SF40 RECORD, POS 5-14, REQUIRES A 6 OR 10 DIGIT HARMONIZED TARIFF NUMBER. IF THIS FIELD IS LEFT BLANK, THIS ERROR WILL RESULT.");
			aBIErrorCollection["40J"] = new MessageError(errorCode: "40J", shortDesc: "SPI CLAIM INVALID FOR TARIFF", narrative: "MOST TARIFF NUMBERS ARE ELIGIBLE FOR ONE OR MORE SPECIAL PROGRAMS THAT REDUCE OR ELIMINATE THE DUTY REQUIRED. THESE ARE CODED AS 'SPI' FOR THOSE PROGRAMS THAT THE INDIVIDUAL TARIFF NUMBER HAS BEEN FLAGGED FOR. IF AN ABI FILERS TRANSMITS AN SPI (SUMMARY TRANSACTION 50 REC, POS 3, OR POS 78-79; 70/80/81 REC, POS 13 OR POS 79-80) THAT IS NOT LISTED ON THE HSA FILE FOR THE TARIFF NUMBER, THIS ERROR MESSAGE WILL RESULT. FILERS SHOULD VERIFY THE SPI FROM THEIR HARMONIZED QUERY OUTPUT (V3 REC, POS 53-72) TO ASCERTAIN THAT THE SELECTED SPI APPLIES TO THE TARIFF NUMBER.  NOTE: AS STATED IN ERROR MESSAGE 40L, IF THE TRANSMITTED SPI (50 RECORD OR 70 RECORD) IS ON THE HSA FILE FOR THE TARIFF NUMBER, IT MUST NONETHELESS AGREE WITH THE C/O CODE (EITHER 'MX' OR 'CA'). IF THE C/O IS 'CA', AN SPI OF 'MX' WILL GENERATE THIS ERROR MESSAGE.  NOTE: FILERS WHO CLAIM TWO SPI'S ON THE SAME LINE WILL ALSO RECEIVE THIS ERROR.");
			aBIErrorCollection["40K"] = new MessageError(errorCode: "40K", shortDesc: "SPI INVALID FOR EXP COUNTRY", narrative: "SPECIAL PROGRAM INDICATORS, LISTED IN THE CATAIR ON PAGES ENS-46 AND 47 MAY NOT BE VALID FOR ALL PROGRAMS FOR ALL COUNTRIES. FOR EXAMPLE, ECUADOR IS ELIGIBLE FOR THE ANDEAN PREFERENCE PROGRAM (SPI 'J'), BUT IS NOT ELIGIBLE FOR THE CARRIBEAN PREFERENCE PROGRAM (SPI 'E'). THEREFORE, AN ENTRY SUMMARY INPUT TRANSACTION THAT USED CODE 'E' WITH ISO CODE 'EC' AS THE COUNTRY OF EXPORT WOULD RECEIVE THIS ERROR MESSAGE.  DEC 2001 UPDATE: ANDEAN PREFERENCE TRADE ACT WAS TERMINATED ON DEC, 4, 2001. GSP WAS ALSO SUSPENDED EFFECTIVE OCT 1, 2001. ANDEAN PREFERENCE ENTRIES WITH SPI 'J' RECEIVE THE REJECT MESSAGE NOTED HERE. GSP ENTRIES RECEIVE A DUTY MISMATCH REJECT, PENDING RENEWAL OF THE PROGRAM.");
			aBIErrorCollection["40L"] = new MessageError(errorCode: "40L", shortDesc: "SPI INVALID FOR COUNTRY OF ORIGIN", narrative: "SPECIAL PROGRAMS THAT REDUCE OR ELIMINATE DUTY ARE NOT APPLICABLE TO EVERY COUNTRY OF ORIGIN THAT MAY APPEAR ON AN IMPORT TRANSACTION. GSP (SPI 'A') APPLIES ONLY TO THOSE COUNTRIES LISTED AS BENEFICIARY DEVELOPING COUNTRIES; ANDEAN PREFERENCE (SPI 'J') APPLIES ONLY TO THOSE COUNTRIES CODED AS ELIGIBLE FOR THAT PROGRAM. THE RFJL DATABASE LISTS WHICH COUNTRIES ARE ELIGIBLE FOR VARIOUS SPECIAL PROGRAMS. IF A SUMMARY INPUT CONTAINS A SPECIAL PROGRAM INDICATOR WHICH IS NOT APPLICABLE TO THE TRANSMITTED COUNTRY OF ORIGIN, THIS ERROR MESSAGE WILL BE GENERATED.  NOTE: IF THE LINE HAS TWO TARIFF NUMBERS, BOTH OF WHICH ARE NAFTA ELIGIBLE, THE SPI'S USED MUST AGREE WITH THE COUNTRY OF ORIGIN. IF THE FILER USES 'CA' FOR THE SPI IN EITHER THE 50 OR 70 RECORD, WITH 'MX' IN THE 40 RECORD AS C/O, THIS MESSAGE WILL ALSO BE GENERATED. SEE ERROR MSG 40J, AS WELL");
			aBIErrorCollection["40O"] = new MessageError(errorCode: "40O", shortDesc: "FAS SPI ORIG CTRY NOT = EXP CNTRY", narrative: "IF AN ENTRY CLAIMS A FREELY ASSOCIATED STATES SPI (Z), THE COUNTRY OF ORIGIN AND THE COUNTRY OF EXPORT MUST BE THE SAME.");
			aBIErrorCollection["40T"] = new MessageError(errorCode: "40T", shortDesc: "MX SPI REQUIRED", narrative: "AN SPI OF 'MX' MUST BE ENTERED FOR TARIFF NUMBER 9802008055");
			aBIErrorCollection["40V"] = new MessageError(errorCode: "40V", shortDesc: "INVALID EXPORT COUNTRY â€“ 99990084", narrative: "TARIFF NUMBER 99990084 (ISI CLAIM UNDER THE SINGAPORE FTA) REQUIRES THAT THE COUNTRY OF EXPORT FOR TARIFF NUMBER 99990084 MUST BE SINGAPORE 'SG'. REFER TO ADMIN MESSAGE 04-0859.");
			aBIErrorCollection["417"] = new MessageError(errorCode: "417", shortDesc: "PORT CODE & AGR DOC # REQUIRED", narrative: "PORT CODE AND AGRICULTURE DOCUMENT NUMBER REQUIRED MATCHES  -FOR A CASH RECEIPT WHOSE CLASS CODE IS 050 THE FIRST FOUR DIGITS OF THE AGRICULTURE DOCUMENT NUMBER MUST BE THE DISTRICT/PORT CODE AND MATCH THE TELLER SIGNED ON THE ACS.  FOR IMPORTER SECURITY FILING THROUGH SEA AMS FOR X.12 USERS, THIS ERROR WILL RETURN THE MESSAGE 'N9 MISSING BILL NO.' THE N9 RECORD, ELEMENT 02, MUST CONTAIN EITHER A HOUSE BILL OR A REGULAR BILL NUMBER. IF NEITHER IS TRANSMITTED, THIS ERROR WILL RESULT.");
			aBIErrorCollection["419"] = new MessageError(errorCode: "419", shortDesc: "SHORTAGE NOT ON FILE", narrative: "THE SHORTAGE OR SHORTAGE NEGATE TRANSACTION MUST BE INPUT BEFORE THE RECONCILIATION OR DEPOSIT TICKET IS INPUT.  THIS MESSAGE IS ALSO FURNISHED FOR 'INSD' WHEN THE CASHIER LOG ON (CLGC) IS NOT THE SAME AS THE DISTRICT/PORT INPUT ON THE 'INSD' SCREEN. WHEN THIS OCCURS,DO A 'CLGC' TO THE SAME DISTRICT/PORT OF THE 'INSD' AND THEN REINPUT THE 'INSD'.  FOR IMPORTER SECURITY FILING THROUGH SEA AMS FOR X.12 USERS, THIS ERROR WILL RETURN THE MESSAGE 'N 9 INVALID QUALIFIER.' THE N9 RECORD, ELEMENT 01, PROVIDES FOUR QUALIFIERS FOR THE ISF IMPORTER IN THE NM1 RECORD. IF THE QUALIFIER IS OMITTED, OR ONE THAT IS NOT LISTED IN ELEMENT 01 IS USED, THIS ERROR WILL RESULT.");
			aBIErrorCollection["41E"] = new MessageError(errorCode: "41E", shortDesc: "TARIFF EXPIRES WITHIN 21 DAYS", narrative: "THIS IS AN OUTDATED CARGO SELECTIVITY RESPONSE MESSAGE THAT PERIODICALLY IS DISPLAYED WHEN THE FILER USES A TARIFF NUMBER THAT IS SCHEDULED TO EXPIRE WITHIN THE NEXT THREE WEEKS. THERE IS NO CONSEQUENCE TO THE CREATION OF THIS MESSAGE.");
			aBIErrorCollection["42A"] = new MessageError(errorCode: "42A", shortDesc: "SPI INVALID FOR CATEGORY", narrative: "IF SPI FOR THIS ENTRY IS'G' THEN CATEGORY MUST BE '443', '444', '643', '644', '843', OR '844'.");
			aBIErrorCollection["42B"] = new MessageError(errorCode: "42B", shortDesc: "LINE RELEASE ENTRY ON FILE", narrative: "THIS ERROR MESSAGE OCCURS IN THE 'REVISED FILER DATE' (DN) TRANSACTION WHEN A FILER TRANSMITS A REVISED ENTRY DATE IN THE DN01 RECORD, POSITIONS 19-24, WHEN THE ENTRY HAS BEEN RELEASED VIA LINE RELEASE. LINE RELEASE SETS THE ENTRY DATE AND CANNOT BE REVISED.");
			aBIErrorCollection["42D"] = new MessageError(errorCode: "42D", shortDesc: "EST TAX NO MATCH TO COMPUTED TAX", narrative: "IR TAX ENTERED IS NOT WITHIN $3.00 OF COMPUTED IR TAX.");
			aBIErrorCollection["42J"] = new MessageError(errorCode: "42J", shortDesc: "INVALID IT/AWB/BL QUANTITY", narrative: "THE MANIFESTED QUANTITY (ENTRY HEADER LEVEL) IS REPORTED IN THE SUMMARY INPUT IN REC 22, POS 51-58. THIS QUANTITY MUST BE GREATER THAN ZERO. IF ZERO IS TRANSMITTED, OR IF THE QUANTITY CONTAINS ANY CHARACTERS OTHER THAN NUMERICS, THIS MESSAGE WILL BE GENERATED.");
			aBIErrorCollection["41D"] = new MessageError(errorCode: "41D", shortDesc: "WARNING TSUSA EFFECT. W/IN 3 WKS.", narrative: "THIS MESSAGE IS A WARNING MESSAGE, NOT A REJECTION. IT USUALLY REFERS TO THE FACT THAT THE ENTRY SUMMARY CONTAINS A NEWLY CREATED TARIFF NUMBER THAT HAS GONE INTO EFFECT WITHIN THE LAST THREE CALENDAR WEEKS. IT HAS NO BEARING ON THE PROCESSING OF THE CARGO RELEASE TRANSACTION. THERE IS A DIFFERENCE IN THE 'CP' CORRECTION OF THE FDA INTERFACE. IT IS A FATAL ERROR IN THE INTERFACE. (JO 070703). AS OF 070805 THIS PROBLEM HAS NOT BEEN FIXED. THE ENTRY WILL HAVE TO BE DELETED/CANCELLED AND RESENT UNDER A DIFFERENT NUMBER WITH CURRENT DATES.");
			aBIErrorCollection["420"] = new MessageError(errorCode: "420", shortDesc: "DRWBK ENTRY - COLL NOT ACCEPTED", narrative: "THIS MESSAGE IS GENERATED ON ENTRY TYPES: 41, 42, AND 43  FOR IMPORTER SECURITY FILING THROUGH SEA AMS FOR X.12 USERS, THIS ERROR WILL RETURN THE MESSAGE 'N 9 MISSING REFERENCE QUALIFIER.' THE N9 RECORD, ELEMENT 02, MUST CONTAIN A VALUE WHICH CORRESPONDS TO THE QUALIFIER TRANS- MITTED IN ELEMENT 01. IF ELEMENT 02 IS BLANK, THIS ERROR WILL RESULT.");
			aBIErrorCollection["42E"] = new MessageError(errorCode: "42E", shortDesc: "DATA REPLACED WITH WARNINGS", narrative: "THIS IS AN ABI OUTPUT MESSAGE THAT IS GENERATED IN RESPONSE TO A CARGO RELEASE INPUT TRANSMISSION (APPLICATION HI). IT WILL ALWAYS BE ACCOMPANIED BY ANOTHER SPECIFIC MESSAGE THAT DESCRIBES THE ELEMENT THAT GENERATED THE WARNING MESSAGE ('CONSIGNEE IS FOREIGN BASED' IS AN EXAMPLE). THIS MESSAGE WILL OCCUR WHEN THE FILER TRANSMITS ACTION CODE 'R' IN THE H1 RECORD, POSITION 3.");
			aBIErrorCollection["42F"] = new MessageError(errorCode: "42F", shortDesc: "DATA ADDED WITH WARNINGS", narrative: "THIS IS AN ABI OUTPUT MESSAGE IN REPLY TO A CARGO RELEASE DATA INPUT TRANSACTION (APPLICATION HI). THIS MESSAGE WILL BE ACCOMPANIED BY ONE OR MORE MESSAGES THAT INDICATE THAT SOME OF THE INPUT DATA IS NOT IN STRICT COMPLIANCE WITH ACS REQUIREMENTS, BUT WHICH, NONETHELESS, IS ACCEPTABLE. ('ULTIMATE CONSIGNEE NOT ON FILE' IS AN EXAMPLE). THIS MESSAGE OCCURS WHEN THE FILER'S INPUT CONTAINS AN 'ADD' INDICATOR (LETTER 'A') IN THE H1 RECORD, POS 3.");
			aBIErrorCollection["42N"] = new MessageError(errorCode: "42N", shortDesc: "WARNING - EST TAX { COMPUTED TAX", narrative: "FOR LIQUOR TYPE TARIFF NUMBERS THAT HAVE A TAX CLASS CODE OF '16' ABI DOES NOT PERFORM AN EXACT EDIT ON THE IR TAX BUT IT DOES ISSUE THIS WARNING MESSAGE. THIS ALERTS THE ENTRY TEAM THAT A MANUAL CALCULATION SHOULD BE MADE. THIS MAY BE DUE TO THE FACT THAT THE IMPORTATION IS GOING TO A BULK FACILITY FOR BLENDING.");
			aBIErrorCollection["42Q"] = new MessageError(errorCode: "42Q", shortDesc: "SEC SPI 'M' REQUIRES HSA CATEGORY", narrative: "THE SECONDARY SPI OF 'M' REQUIRES A CATEGORY TO BE ASSOCIATED WITH A TARIFF.");
			aBIErrorCollection["440"] = new MessageError(errorCode: "440", shortDesc: "TARIFF NBR INVALID FOR ENTRY TYPE", narrative: "THIS MESSAGE WILL BE GENERATED WHEN A TARIFF NUMBER IS TRANSMITTED THAT DOES NOT PERTAIN TO THE ENTRY TYPE. MOST OFTEN, THE CAUSE OF THIS ERROR MESSAGE IS THE USE OF A NON-TIB TARIFF NUMBER WITH ENTRY TYPE 23. TIB ENTRIES REQUIRE EACH LINE TO USE A TARIFF NUMBER FROM CHAPTER 9813. NO OTHER TARIFF NUMBER CAN OCCUPY THE 50 RECORD ON A TIB ENTRY SUMMARY TRANSACTION OR THIS ERROR MESSAGE WILL BE GENERATED.  IF THE TARIFF NBR STARTS WITH 981800, THEN THE ENTRY TYPE MUST BE '05' (VESSEL REPAIR).");
			aBIErrorCollection["44E"] = new MessageError(errorCode: "44E", shortDesc: "SAMPLE IND.N/ALLOWED FOR ENT TYP", narrative: "THE SAMPLE INDICATOR ('X') IS SENT IN RECORD 30, POSITION 39. IT IS ALLOWED ONLY FOR INFORMAL ENTRY TYPES 11 OR 12.");
			aBIErrorCollection["452"] = new MessageError(errorCode: "452", shortDesc: "CHARGES AMOUNT INVALID", narrative: "IF THERE ARE NO CHARGES, OR CHARGES ARE LESS THAN $ 1 AN 'X' WILL BE LISTED AS VALUE OF CHARGES. IN CASE OF OVERLAND SHIPMENTS ARRIVING FROM MEXICO OR CANADA 'X' IS ALWAYS SHOWN.  IF AGGREGIATE CHARGES COVER MERCHANDISE ENTERED UNDER SEVERAL ITEM NUMBERS, AND EXACT BREAKDOWN IS UNKNOWN, CHARGES SHALL BE PRORATED BY VALUE. SEE PAGE 40 OF DOCUMENT H.B. 3500-01, CUSTOM IMPORT SPECIALIST HANDBOOK.  THE ABOVE DOES NOT APPLY TO ABI TRANSMISSIONS. CHARGES ARE TRANSMITTED IN THE ENTRY SUMMARY INPUT (EI) IN THE 40 REC, POS 48-57. CHARGES ARE REQUIRED FOR ALL MOT'S EXCEPT 60 (HAND-CARRIED) AND FOR ALL ENTRIES EXCEPT INFORMAL ENTRIES. AN AMOUNT OF AT LEAST ONE DOLLAR IS REQUIRED FOR THIS FIELD. ABI WILL NOT ACCEPT 'X' FOR CHARGES FOR SHIPMENTS FROM EITHER MEXICO OR CANADA. LINE VALUES LESS THAN $1250 ($250 FOR SOME TEXTILE PRODUCTS) DO NOT REQUIRE CHARGES TO BE TRANSMITTED.");
			aBIErrorCollection["457"] = new MessageError(errorCode: "457", shortDesc: "IT DATE INVALID/CONFLICTING", narrative: "THIS MESSAGE IS A RESPONSE TO A SUMMARY INPUT TRANSACTION (APPLICATION EI). THE I.T. DATE IS TRANSMITTED IN THE 22 RECORD, POS 64-69. THE DATE MUST BE A VALID DATE IN MMDDYY FORMAT. IF NOT IN THIS FORMAT, THIS ERROR MESSAGE WILL BE GENERATED  ALSO, CHECK THE OTHER DATES (ESTIMATED DATE OF ARRIVAL, IMPORT DATE, ESTIMATED ENTRY DATE FOR A CONFLICT. MOST COMMON CONFLICT IS THAT THE IT DATE IS BEFORE THE ESTIMATED DATE OF ARRIVAL.");
			aBIErrorCollection["458"] = new MessageError(errorCode: "458", shortDesc: "IMPORT DATE INVALID/CONFLICTING", narrative: "THE IMPORT DATE MUST BE IN THE MMDDYY FORMAT, 20 REC, POS 34-39. IF THE DATE TRANSMITTED IS NOT A VALID DATE ON THE CALENDAR (I.E., 013298), THIS ERROR MESSAGE WILL BE GENERATED. THE IMPORT DATE MUST ALSO BE PROPER CHRONOLOGICAL SEQUENCE WITH THE REPORTED DATE OF EXPORT (50 REC, POS 71-76) AND THE I.T. DATE (IF AN I.T. IS REPORTED) IN THE 22 REC, POS 64-69. HOWEVER, IF THE DATE SEQUENCE IS INCORRECT, EITHER ERROR MESSAGE NUMBER 915 (IT DATE/DATE OF IMP INCONSISTENT) OR ERROR MESSAGE NUMBER 384 (EXPORT DATE INVALID/CONFLICTING) WILL BE GENERATED. ALSO, IF THE IMPORT DATE IS CORRECT, BUT THE ESTIMATED DATE OF ARRIVAL IN THE 20 REC, POS 66-71, IS BLANK, THIS MESSAGE WILL ALSO RESULT. **NOTE** - IF ALL THE DATES ON THE EI TRANSACTION APPEAR TO BE CORRECT, CHECK ENAI TO SEE IF THE SUMMARY HAS HAD AN ENTRY DATE ASSIGNED THAT IS PRIOR TO THE FILER'S IMPORT DATE. IF SO, THE ENAI RECORD WILL NEED TO BE CORRECTED.");
			aBIErrorCollection["460"] = new MessageError(errorCode: "460", shortDesc: "EST ARRIVAL DATE INVALID", narrative: "IF THE ARRIVAL DATE (HI APPLICATION, REC H1, POS 34-39 OR THE EI APPLICATION, REC 20, POS 66-71) IS OLDER THAN 90 DAYS AS MEASURED FROM THE DATE OF TRANS- MISSION, CARGO CERTIFICATION IS NOT PERMITTED. THIS MESSAGE WILL BE PART OF THE ABI REJECTION MESSAGE IN SUCH A CASE. IF THE ARRIVAL DATE IS MORE THAN 60 DAYS IN THE FUTURE, AS COMPARED TO THE SYSTEM TRANSMISSION DATE, THIS ERROR WILL ALSO RESULT.");
			aBIErrorCollection["461"] = new MessageError(errorCode: "461", shortDesc: "PAY DUE DATE INVALID/CONFLICTING", narrative: "THIS MESSAGE WILL RESULT IF THE FILER TRANSMITS A PAYMENT DUE DATE THAT IS NOT AT LEAST ONE WORKING DAY IN THE FUTURE WHEN COMPARED TO THE ABI TRANSMISSION DATE. THE PAYMENT DUE DATE IS TRANSMITTED IN THE 30 RECORD, POS 54-59.");
			aBIErrorCollection["4BP"] = new MessageError(errorCode: "4BP", shortDesc: "MUST BE ACE ACCT FOR NATL STMT", narrative: "NO NARRATIVE GIVEN");
			aBIErrorCollection["4BQ"] = new MessageError(errorCode: "4BQ", shortDesc: "DATE MUST BE '01' THRU '11'", narrative: "NO NARRATIVE GIVEN");
			aBIErrorCollection["4BR"] = new MessageError(errorCode: "4BR", shortDesc: "DATE MUST BE } SYSTEM DATE", narrative: "NO NARRATIVE GIVEN");
			aBIErrorCollection["4BU"] = new MessageError(errorCode: "4BU", shortDesc: "IRS TAXES INVALID FOR PERDC STMT", narrative: "AS OF MARCH 2007, ENTRIES THAT CONTAIN IRS EXCISE TAXES ON VARIOUS PRODUCTS CANNOT BE PLACED ON A PERIODIC DAILY STATEMENT.");
			aBIErrorCollection["4BX"] = new MessageError(errorCode: "4BX", shortDesc: "NATL STMT FILER/DDPP REQUIRED", narrative: "NO NARRATIVE GIVEN");
			aBIErrorCollection["4CQ"] = new MessageError(errorCode: "4CQ", shortDesc: "FORMAL QUOTA ENTRY REQUIRED", narrative: "IN VISA EDIT, THE ENTRY TYPE IS OTHER THAN 02, 07, 21 OR 22; A QUOTA ENTRY IS REQUIRED.");
			aBIErrorCollection["4CS"] = new MessageError(errorCode: "4CS", shortDesc: "ABSOLUTE/TPL QTA MIX NOT ALLOWED", narrative: "NO NARRATIVE GIVEN");
			aBIErrorCollection["4DA"] = new MessageError(errorCode: "4DA", shortDesc: "IMPORTER NOT ON FILE", narrative: "THE IMPORTER NUMBER IS IN CORRECT FORMAT, BUT THE NUMBER IS NOT IN THE IMPORTER (SRE) FILE.");
			aBIErrorCollection["4F7"] = new MessageError(errorCode: "4F7", shortDesc: "TARIFF NUMBER INVALID", narrative: "TARIFF NUMBER MUST BE IN THE FOLLOWING FORMAT:  ABI - 10 DIGITS, CHECK DIGIT IS UNNECESSARY  NON- ABI - 10 DIGITS, AND NUMERIC CHECK DIGIT  FROM THE ABOVE, OR IF THE FIELD CONTAINS ALPHABETIC CHARACTERS, THIS MESSAGE WILL BE PROVIDED.");
			aBIErrorCollection["46D"] = new MessageError(errorCode: "46D", shortDesc: "SCH PAY DATE INVALID FOR QUOTA", narrative: "THIS MESSAGE IS GENERATED IN RESPONSE TO A STATEMENT ADD/DELETE TRANSACTION (APPLICATION HP). ENTRIES WITH QUOTA MERCHANDISE THAT HAVE BEEN ACCEPTED BY THE QUOTA MODULE (THROUGH QSUP PROCESSING) MUST BE PAID WITHIN 10 WORKING DAYS FROM THE DATE OF PRESENTATION IN ACCEPTABLE FORMAT OF THE QUOTA ENTRY SUMMARY PACKAGE. THIS DATE IS NOT AN ABI MEASUREABLE EVENT; HOWEVER, SO ABI WILL USE THE RELEASE DATE OF THE ENTRY TO DETERMINE IF THE PROPOSED PAYMENT DUE DATE IS WITHIN 10 WORKING DAYS OF THE RELEASE DATE. NOTE: CHECK KALS FOR THE ENTRY PORT TO INSURE THAT ALL HOLIDAYS ARE INDICATED.");
