			aBIErrorCollection["46F"] = new MessageError(errorCode: "46F", shortDesc: "PAYMENT TYPE/DUE DATE CONFLICT", narrative: "WHEN CHANGING PAY BASIS INDICATOR FROM 2, 3, OR 5 TO 1 (SINGLE PAYMENT) THE SCHEDULE PAY DATE MUST BE SPACES. NO OTHER DATES, ALPHA OR SPECIAL CHARACTERS CAN BE TRANSMITTED IN THIS FIELD WHEN THE PAYMENT TYPE IS 1.");
