			aBIErrorCollection["484"] = new MessageError(errorCode: "484", shortDesc: "ULTIMATE CONSIGNEE NOT ON FILE", narrative: "THE CONSIGNEE NUMBER, TRANSMITTED IN THE SUMMARY INPUT IN REC 10, POS 20-31, MUST BE LISTED ON THE SRE DATABASE. IF THE CARGO RELEASE APPLICATION (HI) IS USED, THE CONSIGNEE NUMBER TRANSMITTED IN THE H2 REC, POS 11-22, MUST BE LISTED ON THE SRE DATABASE. IF THE CONSIGNEE NUMBER IS NOT ON FILE, THIS WARNING MESSAGE WILL RESULT (THIS IS NOT A REJECTION MSG). OTHER APPLICATIONS THAT WILL RECEIVE THIS ERROR MESSAGE INCLUDE THE AUTOMATED INVOICE INTERFACE (CI).  THIS MESSAGE CAN BE A REJECT IF THE ENTRY INVOLVES FDA REGULATED MECHANDISE BEING SENT THROUGH THE FDA INTERFACE. THE ULTIMATE CONSIGNEE MUST BE ON FILE BEFORE SELECTIVITY RUNS BECAUSE FDA REQUIRES AN ULTIMATE CONSIGNEE. FILER MUST DO A 5106 UPDATE AND RE-TRASMIT THE ENTRY.");
			aBIErrorCollection["485"] = new MessageError(errorCode: "485", shortDesc: "REFERENCE # CF4811 NOT ON FILE", narrative: "THIS IS A WARNING MESSAGE AND WILL NOT CAUSE, BY ITSELF, A REJECTION OF THE SUMMARY INPUT. THE CF4811 IS SPECIAL ADDRESS NOTIFICATION FORM THAT IS SUBMITTED IN HARDCOPY TO LOCAL CUSTOMS. (IT IS NOT AN AUTOMATED PROCESS FOR ABI AT THIS TIME). THE CF4811 AUTHORIZES REFUNDS, DRAWBACK PAYMENTS AND LIQUIDATION NOTIFICATIONS TO BE SENT TO AN AGENT OF THE IMPORTER OF RECORD. THE SRFL DATABASE SHOWS THE RELATIONSHIPS BETWEEN IMPORTERS AND THEIR AGENTS CREATED BY CF4811 PROCESSING. IF AN ABI FILER TRANSMITS HIS IDENTIFICATION NUMBER IN THE 10 REC, POS 32-43, (IN ONE OF THE THREE ACCEPTABLE FORMATS - SEE ERROR MESSAGE 486) AND THERE IS NO PRE-EXISTING CF4811 ON FILE IN THE SRF DATABASE, THIS WARNING MESSAGE WILL BE GENERATED. CHECK SRFL FILE FOR DRAWBACK REJECT  **NOTE** - FOR RECONCILIATION ENTRIES, THE ABSENCE OF A CF4811 IS A REJECT CONDITION.");
			aBIErrorCollection["486"] = new MessageError(errorCode: "486", shortDesc: "INVALID CONSIGNEE NUMBER FORMAT", narrative: "CONSIGNEE NUMBERS TRANSMITTED TO ABI MUST BE IN ONE OF THE FOLLOWING FORMATS:  IRS OR EIN NUMBER: NN-NNNNNNNXX SSN: NNN-NN-NNNN CUSTOMS ASSIGNED NUMBER: YYDDPP-NNNNN  N = NUMERIC CHARACTER X = ALPHANUMERIC CHARACTER (EXCEPT FOR THE LETTERS 'O', 'I', 'Z') YY= LAST TWO DIGITS OF THE CALENDAR YEAR IN WHICH THE NUMBER WAS ASSIGNED  ANY OTHER FORMAT THAT ONE OF THE ABOVE WILL BE REJECTED WITH THIS MESSAGE.  USING 00-000000000 OR 000-00-0000 IN A FORMAL ENTRY WILL ALSO CAUSE THIS REJECT");
			aBIErrorCollection["487"] = new MessageError(errorCode: "487", shortDesc: "INVALID REFERENCE NUMBER FORMAT", narrative: "THE REFERENCE NUMBER IS TRANSMITTED BY THE FILER AND USUALLY REPRESENTS THE FILER'S IRS, OR SSN NUMBER. WHEN A CUSTOMS FORM 4811 HAS BEEN PROCESSED BY LOCAL CUSTOMS, THE AGENT (OWNER OF THE REFERENCE NUMBER) WILL RECEIVE CERTAIN NOTIFICATIONS, LIQUIDATION NOTICES, ETC FOR THE IMPORTER OF RECORD ON THE ENTRY. THE REFERENCE NUMBER MUST BE TRANSMITTED IN ACCEPTABLE IRS (NN-NNNNNNNNN) OR SSN (NNN-NN-NNNN) FORMAT IN THE 10 REC, POS 32-43. IF THE FORMAT IS NOT CORRECT, THIS ERROR MESSAGE WILL BE GENERATED.");
			aBIErrorCollection["48A"] = new MessageError(errorCode: "48A", shortDesc: "CONSIGNEE IS FOREIGN BASED", narrative: "THIS IS A WARNING MESSAGE THAT OCCURS WHEN A FILER SENDS A FOREIGN BASED CONSIGNEE IN A SELECTIVITY TRANSACTION. IT WARNS THE FILER THAT THE ADDRESS FOR THE CONSIGNEE NUMBER IS NOT A U.S. ADDRESS. IN THE FDA INTERFACE THE FDA'S SYSTEM WILL AUTOMATICALLY REJECT THIS TYPE OF CONSIGNEE AND SEND A 'DT' REJECT BACK TO THE FILER. THE FILER MUST THEN OBTAIN A FDA ESTABLISHMENT IDENTIFIER NUMBER (FEI) FROM FDA THROUGH ABI AND SEND THAT NUMBER IN AN OTHER GOVERNMENT AGENCY CORRECTION TRANSACTION (CP). THIS MESSAGE IS FOLLOWED BY THE INFORMATIONAL MESSAGE 42F 'DATA ADDED WITH WARNINGS'.");
			aBIErrorCollection["4A0"] = new MessageError(errorCode: "4A0", shortDesc: "INVALID ACTION CODE", narrative: "THIS MESSAGE IS GENERATED IN RESPONSE TO A CARGO RELEASE DATA INPUT TRANSACTION (APPLICATION HI). THE H1 RECORD, POS 3 MUST REFLECT ONE OF THREE ACTION CODES: A (ADD) D (DELETE) OR R (REPLACE). IF ANY OTHER CHARACTER, OR A BLANK, IS TRANSMITTED IN THIS FIELD, THIS ERROR MESSAGE WILL BE GENERATED.");
			aBIErrorCollection["4A3"] = new MessageError(errorCode: "4A3", shortDesc: "INVALID IN-BOND NUMBER", narrative: "PAPERLESS MASTER IN-BOND NUMBERS (FORMAT VNN-NNNNNNNN) ARE TRANSMITTED TO ABI IN EITHER AN ENTRY SUMMARY TRANSACTION (EI 22 REC, POS 3-14) OR THE CARGO RELEASE DATA TRANSACTION (HI HA REC, POS 3-14). IF THE IN BOND NUMBER DOES NOT CONTAIN EIGHT DIGITS FOLLOWING THE CARRIER IDENTIFIER (VNN), THIS ERROR MESSAGE WILL RESULT. NOTE: IF THE EIGHTH DIGIT (CHECK DIGIT) IS INCORRECT, ERROR MESSAGE NUMBER 2CI (INBOND - INVALID CHECK DIGIT) WILL BE GENERATED INSTEAD OF THIS MESSAGE.");
			aBIErrorCollection["4AC"] = new MessageError(errorCode: "4AC", shortDesc: "IN-BOND NUMBER NOT FOUND", narrative: "THIS MESSAGE INDICATES THAT THE FILER PROVIDED AN INBOND NUMBER IN HIS EI (ENTRY SUMMARY) TRANSACTION, BUT DID NOT INCLUDE A MASTER BILL NUMBER (OR AIR WAYBILL) IN THE 22 RECORD. AS OF SEP 28, 1998, THE REVISED INBOND PROGRAM REQUIRES INBOND NUMBERS TO BE ACCOMPANIED BY BILL NUMBERS. THIS ERROR SHOULD NOT OCCUR FOR TRUCK SHIPMENTS (MOT 30 OR 31), BUT, AS OF SEP 30, 1998, IF THE BILL OF LADING FIELD DOES NOT CONTAIN A MINIMUM OF 5 CHARACTERS, THIS MESSAGE WILL BE GENERATED.");
			aBIErrorCollection["4BA"] = new MessageError(errorCode: "4BA", shortDesc: "REL PROCESSING NOT TEST/OPER", narrative: "THIS MESSAGE IS USUALLY FOUND WHEN FILERS ARE FIRST TESTING ABI. NORMAL PROCEDURES ARE TO TEST ENTRY SUMMARY INPUT FIRST. DURING SUMMARY TESTING, FILERS MAY NOT SIMULTANEOUSLY BE SET UP FOR CARGO RELEASE TESTING. IF THE FILER TRANSMITS A CARGO RELEASE INPUT WHILE IN SUMMARY TEST STATUS, THIS MESSAGE WILL BE GENERATED.  THIS MESSAGE WILL ALSO OCCUR WHEN THE PORT (AND FILER) ARE NOT SET UP FOR BORDER CARGO SELECTIVITY BUT THE FILER IS OPERATIONAL FOR ENTRY SUMMARY AND REGULAR CARGO SELECTIVITY.");
			aBIErrorCollection["4BB"] = new MessageError(errorCode: "4BB", shortDesc: "SELECTIVITY ALREADY PERFORMED", narrative: "SELECTIVITY IS PROCESSED IN ABI PRIOR TO ONLINE PROCESSING IF THE ARRIVAL DATE OF THE ENTRY IS LESS THAN 6 DAYS IN THE FUTURE. ONCE SELECTIVITY HAS BEEN PERFORMED, EVEN THOUGH THE ENTRY MAY BE IN ABI STATUS, A REPLACEMENT OF THE ENTRY BY THE BROKER THROUGH ABI IS NOT ALLOWED.");
			aBIErrorCollection["4BL"] = new MessageError(errorCode: "4BL", shortDesc: "ENTRY WAS NOT ORIGINALLY ABI", narrative: "ALTHOUGH THE DISKETTE PROGRAM IS NOT ABI AND THE CLAIMS ARE NOT ABI, WE USE SIMILIAR PROGRAMMING AS THE SOURCE OF CLAIM CREATION. IF THE CLAIM HAS BEEN COMPLETELY INPUT MANUALLY AND RECORDS EXIST AT THE TIME THE ABI OR DISKETTE JOBS ARE RUN, THE DISKETTE AND ABI WILL NOT PERMIT THE OVERLAY OF DATA.");
			aBIErrorCollection["4BO"] = new MessageError(errorCode: "4BO", shortDesc: "REMOTE ENTRY-CANNOT DEL FROM STMT", narrative: "A REMOTE-FILE ENTRY CANNOT BE REMOVED FROM ABI STATEMENT  THIS IS TRUE. A FILER WILL GET A REJECT IF THEY TRY TO JUST REMOVE AN ENTRY FROM A REMOTE STATEMENT EVEN IF THE B RECORD IS CONFIGURED PROPERLY. THERE MUST BE A DATE IN POSITIONS 19-24 OF THE H RECORD THAT MOVES THE STATEMENT DATE TO A FUTURE DATE.");
			aBIErrorCollection["4BH"] = new MessageError(errorCode: "4BH", shortDesc: "ENTRY TYPE CHANGE INVALID", narrative: "THIS MESSAGE INDICATES THAT THE ABI FILER IS ATTEMPTING TO TRANSMIT AN ENTRY SUMMARY WITH A DIFFERENT ENTRY TYPE THAN EXISTS ON THE ENAI FILE FOR THE ENTRY NUMBER. IF THE ENTRY IS IN CUSTOMS STATUS, SUCH A CHANGE IS NOT PERMITTED. IF THE ENTRY IS STILL IN ABI STATUS, THIS CHANGE CAN USUALLY BE ACCOMPLISHED. THE MOST COMMON CHANGE IS FROM TYPE 11 TO TYPE 01 (OR VICE VERSA IN SOME CASES) OR FROM 02 TO 21.  FOR RECONCILIATION ON-LINE PROCESSING, THIS ERROR MEANS THAT YOU CANNOT CHANGE ANY PRE-EXISTING ENTRY THAT IS NOT RECONCILIATION TO A TYPE '09' RECONCILIATION ENTRY SUMMARY.");
			aBIErrorCollection["4BI"] = new MessageError(errorCode: "4BI", shortDesc: "QUOTA ENTRY CANNOT BE CHANGED", narrative: "THIS MESSAGE IS GENERATED IN RESPONSE TO A STATEMENT ADD/DELETE TRANSACTION (APPLICATION HI). FILERS WHO HAVE ENTRY SUMMARIES IN QUOTA ACCEPTED STATUS AND SIMULTANEOUSLY SCHEDULED FOR PAYMENT VIA ACH ARE NOT PERMITTED TO REMOVE THOSE ENTRIES FROM STATEMENT/ACH STATUS. IF THE STATEMENT ADD/DELETE TRANSACTION IS ATTEMPTED WITH PAY TYPE CODE 1 (NON-STATEMENT), THIS ERROR MESSAGE WILL BE GENERATED.");
			aBIErrorCollection["4BS"] = new MessageError(errorCode: "4BS", shortDesc: "PERIODIC STMT MONTH INVALID", narrative: "THE PERIODIC STATEMENT MONTH, TRANSMITTED IN POS 51-52 OF THE 30 RECORD, CAN BE THE CURRENT MONTH OR GREATER. IT CAN ONLY BE THE CURRENT MONTH IF THE PERIODIC DAILY STATEMENT PRINT DATE IS LESS THAN THE PERIODIC MONTHLY STATEMENT PRINT DATE. EXAMPLE IS: PER MONTH DATE = 06 (30 RECORD, POS 51-52) PER DAILY DATE = 06/16/YY (30 RECORD, POS 54-59).  THIS WILL BE REJECTED BY ABI, BECAUSE THE DEFAULT 11TH WORKING DAY OF JUNE IS USUALLY JUNE 15. A PERIODIC DAILY STATEMENT TRANSMITTED WITH JUNE 15 OR LATER AND WITH A PERIODIC MONTHLY STATEMENT DATE OF JUNE VIOLATES THE CONDITION STATED ABOVE.  ALSO, CHECK THE SRE RECORD FOR THE IMPORTER ON THE ENTRY. SOME IMPORTERS CHANGE THE PMS DATE TO A DATE EARLIER THAN THE 11TH WORKING DAY; THIS ERROR WILL RESULT IF THE TRANSMITTING FILER USES A PMS PRINT DATE THAT IS LATER THAN THE IMPORTER'S SRES PRINT DATE.");
			aBIErrorCollection["4BT"] = new MessageError(errorCode: "4BT", shortDesc: "IMPRTR IS NOT AN ACE PARTICIPANT", narrative: "IF AN IMPORTER'S SRE RECORD SHOWS 'N' IN THE 'ACE ACCT' FIELD, THE IMPORTER HAS BEEN REMOVED FROM PMS BY THE NFC, EVEN IF THERE ARE DATES SHOWN UNDER THE MONTHS IN THE PMS PRT DTE FIELD. THE FILER/IMPORTER MUST CALL THE NFC AT 317-614-4545.  IF THE ABI FILER USES PAYMENT TYPE 8 FOR AN ENTRY SUMMARY TRANSMISSIONS, BUT THE IMPORTER'S IRS NUMBER HAS A SUFFIX OTHER THAN '00' OR 'BLANK' AND ONLY THE IRS NUMBER WITH '00' HAS BEEN SET UP FOR PMS, THIS ERROR WILL RESULT. EVERY IMPORTER NUMBER MUST HAVE THE ACE ACCT FLAG SET TO 'Y' IN THE SRES RECORD FOR PMS PARTICIPATION. ADDITIONALLY, IF THE IMPORTER IS AN ACE PARTICIPANT BUT THE FILING BROKER HAS NOT BEEN SET UP AS AN ACE ACCOUNT ON THE ABE RECORD, THIS ERROR WILL RESULT. OFFICE CODES IN THE TRANSMISSION (REMOTE OR NON-REMOTE OFFICE CODES) WILL ALSO CAUSE THIS ERROR.");
			aBIErrorCollection["4BV"] = new MessageError(errorCode: "4BV", shortDesc: "IMPORTER IS NOT ACE PARTICIPANT", narrative: "IF AN IMPORTER'S SRE RECORD SHOWS 'N' IN THE 'ACE ACCT' FIELD, THE IMPORTER HAS BEEN REMOVED FROM PMS BY THE NFC, EVEN IF THERE ARE DATES SHOWN UNDER THE MONTHS IN THE PMS PRT DTE FIELD. THE FILER/IMPORTER MUST CALL THE NFC AT 317-614-4545.  IF THE ABI FILER USES PAYMENT TYPE 8 FOR AN ENTRY SUMMARY TRANSMISSIONS, BUT THE IMPORTER'S IRS NUMBER HAS A SUFFIX OTHER THAN '00' OR 'BLANK' AND ONLY THE IRS NUMBER WITH '00' HAS BEEN SET UP FOR PMS, THIS ERROR WILL RESULT. EVERY IMPORTER NUMBER MUST HAVE THE ACE ACCT FLAG SET TO 'Y IN THE SRE RECORD FOR PMS PARTICIPATION.  ADDITIONALLY, IF THE IMPORTER IS AN ACE PARTICIPANT BUT THE FILING BROKER HAS NOT BEEN SET UP AS AN ACE ACCOUNT ON THE ABE RECORD, THIS ERROR WILL RESULT. OFFICE CODES IN THE TRANSMISSION (REMOTE OR NON-REMOTE OFFICE CODES) WILL ALSO CAUSE THIS ERROR.");
			aBIErrorCollection["4BW"] = new MessageError(errorCode: "4BW", shortDesc: "CENSUS ERR INVALID FOR PERDC STMT", narrative: "THIS MESSAGE IS, AS OF MAY 27, 2005, BEING ERRONEOUSLY GENERATED ON RETRANSMISSIONS OF PREVIOUSLY FILED AND PAID ENTRY SUMMARIES THAT WERE FILED UNDER PERIODIC STATEMENT PROCEDURES. AFTER ON-LINE REJECTION OF THESE ENTRIES (FOR VARIETY OF REASONS BY LOCAL CBP IMPORT SPECIALISTS), ANY RETRANSMISSION WILL GENERATE THIS MESSAGE. THE CORRECTION THAT CBP DESIRES WILL HAVE TO BE DONE BY CBP IN THESE CASES UNTIL PROGRAMMING IS INSTALLED TO REMOVE THIS REJECTION MESSAGE");
			aBIErrorCollection["4CC"] = new MessageError(errorCode: "4CC", shortDesc: "ENTRY TYPE MUST BE QUOT", narrative: "COMMODITIES LISTED ON THE HSA FILE THAT ARE SUBJECT TO QUOTA REPORTING FROM SELECTED COUNTRIES MUST BE ENTERED USING AN APPROPRIATE QUOTA ENTRY TYPE CODE. CURRENTLY, '02' (CONSUMPTION QUOTA ENTRY) OR '07' (COMBINATION QUOTA/ADD OR CVD ENTRY TYPE) ARE THE TWO QUOTA ENTRY TYPES. A QUICK WAY TO DETERMINE IF THE TARIFF NUMBER/COUNTRY OF ORIGIN ARE SUBJECT TO BEING ENTERED UNDER A QUOTA ENTRY IS TO USE FUNCTION 'QSIQ'. FILL IN THE DATA AS REQUESTED AND HIT ENTER. IF A QUOTA RECORD IS DISPLAYED FOR THE TARIFF NUMBER AND ORIGIN COUNTRY, ENTRIES FOR THAT COMMODITY MUST USE ENTRY TYPE '02' OR '07'.");
			aBIErrorCollection["4CU"] = new MessageError(errorCode: "4CU", shortDesc: "VISA # INVALID FOR FASHION SAMPLE", narrative: "SPI 'M' IS USED TO REPORT IMPORTATIONS OF FASHION SAMPLES OR CERTAIN CARPETS FROM CHINA. (SEE ADMIN MSG 97-0482, 97-0952, AND 97-0990). ONE OF THE REQUIREMENTS OF THIS PROGRAM IS THAT IF 'M' IS USED, THE VISA NUMBER FOR THE ITEM IN QUESTION MAY NOT BE TRANSMITTED TO ABI. IF THE VISA NUMBER IS SENT, THIS ERROR MESSAGE WILL BE GENERATED.");
			aBIErrorCollection["4D8"] = new MessageError(errorCode: "4D8", shortDesc: "BANNED IMPORT FROM COUNTRY", narrative: "THIS MERCHANDISE FROM THE COUNTRY IN QUESTION MAY NOT BE ENTERED. THIS MESSAGE ALSO APPEARS WHEN THERE IS A 'BANNED' STATUS IN THE QUOTA FILE. THE TARIFF NUMBER FROM THE COUNTRY IN QUESTION MAY POSSIBLY BE ENTERED UNDER A CHAPTER 99 PROVISION. CHECK THE ADMINISTRATIVE MESSAGES FOR THE PRODUCT IN QUESTION. CHECK THE QUOTA QUERY FOR 'BANNED' IN STATUS COLUMN.  ALSO: THIS MESSAGE MAY APPEAR AGAINST LINES WITH CHAP 99 NUMBERS IF THE QSEL FILE DOES NOT LIST BOTH THE CHAPTER 99 AND CHAPTER 1-97 NUMBER AT THE TIME OF THE SUMMARY TRANSMISSION. (PENDING CONFIRMATION FROM HQ AS OF JAN 18, 2002).  PER HQ JAN 9, 2003, QUESTIONS FROM THE TRADE ON THIS ERROR MESSAGE SHOULD BE DIRECTED TO HQ QUOTA.");
			aBIErrorCollection["4DK"] = new MessageError(errorCode: "4DK", shortDesc: "NO MATCHING LINE ITEM FOUND", narrative: "THIS MESSAGE WILL BE PRESENTED WHEN THE ENTRY INFORMATION AS GIVEN TO HEADQUARTERS QUOTA TO CORRECT A RECORD IS INCORRECT. THUS THE COMPUTER CANNOT LOCATE THE LINE TO BE CORRECTED.  IN THE FDA INTERFACE, THIS ERROR MESSAGE IS GENERATED WHEN THE FILER ATTEMPTS TO SEND A FDA LINE NUMBER (FDLN) IN A 'CP' APPLICATION (OTHER GOVERNMENT AGENCY CORECTION) THAT DOES NOT EXIST IN THE SSB RECORD. THIS DOES NOT MEAN THAT THE LINES DO NOT MATCH, RATHER THE FILER IS SENDING MORE LINES THAN EXIST IN THE SSB (SELECTIVITY LINE ITEM) RECORD.  IF THIS IS A NON-ABI ENTRY, DO NOT FILL IN THE LINE NUMBER WHEN PERFORMING QSUP.");
