			aBIErrorCollection["618"] = new MessageError(errorCode: "618", shortDesc: "SURETY REVOKED", narrative: "THE SURETY CODE REPORTED BY AN ABI FILER IN THE SUMMARY INPUT (10 REC, POS 73-75 OR THE CARGO RELEASE INPUT (H1 REC, POS 71-73) IS IN REVOKED STATUS ON THE BDAL.");
			aBIErrorCollection["628"] = new MessageError(errorCode: "628", shortDesc: "MISSING/INVALID IMPORTER NUMBER", narrative: "THIS MESSAGE OCCURS DURING THE CREATION OF LINE RELEASE OUTPUT RECORDS. THE IMPORTER OF RECORD MUST BE IN ONE OF THREE VALID FORMATS, WHICH ARE OUTLINED ON PAGE LRL-5 OF THE CATAIR. IF ONE OF THE VALID FORMATS IS NOT USED, THIS ERROR MESSAGE WILL RESULT.");
			aBIErrorCollection["4FF"] = new MessageError(errorCode: "4FF", shortDesc: "VISA NUMBER REQUIRED", narrative: "AN ENTRY-LINE WAS ENTERED OR AN ABI LINE WAS TRANSMITTED WITH A TARIFF NBR FROM A COUNTRY THAT REQUIRES A VISA, HOWEVER, NO VISA NUMBER WAS ENTERED OR TRANSMITTED. THIS COMMODITY FROM THIS COUNTRY REQUIRES A VISA FOR ENTRY. USE VISL FOR DETAILS.  THE ABOVE IS THE GENERIC MESSAGE. THIS MESSAGE WAS STILL BEING GENERATED, IN OCTOBER 1999, WHEN A LINE ITEM THAT DID NOT REQUIRE A VISA WAS SENT IN A TYPE 02 ENTRY SUMMARY WHERE AT LEAST ONE OTHER LINE IS QUOTA/VISA. THE ONLY SOLUTION IS TO SEND A 'DUMMY' VISA NUMBER ALONG WITH THE CATEGORY NUMBER IN THE 51 RECORD.  THE SYSTEM WILL DETERMINE WHETHER A VISA NUMBER IS REQUIRED BY COMPARING THE COUNTRY OF ORIGIN/TARIFF/EXPORT DATE AGAINST THE VIP FILE (VIPL). A COMMON ERROR OCCURS WHEN THE FILER ENTERS AN INCORRECT EXPORT DATE IN THE 50 RECORD (POSITIONS 71-76)");
			aBIErrorCollection["4FN"] = new MessageError(errorCode: "4FN", shortDesc: "NO DECIMALS IN QTY FIELDS ALLOWED", narrative: "QUANTITY FIELDS IN ABI ARE WHOLE NUMBER FIELDS. DECIMAL QUANTITIES ARE NOT PERMITTED IN QUANTITY FIELDS.  NOTE: AS OF DECEMBER 2008, THIS ERROR IS NOT BEING USED AND DECIMALS ARE BEING ALLOWED IN QUANTITY FIELDS FOR TARIFF NUMBERS.");
			aBIErrorCollection["4FO"] = new MessageError(errorCode: "4FO", shortDesc: "VISA NUMBER NOT REQUIRED", narrative: "A VISA NUMBER WAS ENTERED ON A LINE BUT IS NOT REQUIRED FOR THIS TARIFF FROM THIS COUNTRY OF ORIGIN -- OR AN ABI LINE WAS TRANSMITTED WITH A RECORD 51 INCLUDING A VISA NUMBER BUT A VISA NUMBER IS NOT REQUIRED FOR THE LINE'S TARIFF FROM THE LINE'S COUNTRY OF ORIGIN");
			aBIErrorCollection["4FR"] = new MessageError(errorCode: "4FR", shortDesc: "NO VISA RECORDS FOR COUNTRY/CAT", narrative: "THIS MESSAGE IS GENERATED IN RESPONSE TO AN ABI QUOTA QUERY INPUT. IF THE CATEGORY AND COUNTRY IDENTIFIED BY THE TRANSMITTING FILER DO NOT RESULT IN A MATCH OF VISA FILES IN ACS, THIS MESSAGE WILL BE SENT TO THE FILER AS A RESPONSE.");
