			aBIErrorCollection["4JB"] = new MessageError(errorCode: "4JB", shortDesc: "QUANTITY MUST BE NUMERIC", narrative: "MUST BE EITHER NUMERIC OR BLANK  QSUP WILL RETURN A WARNING MESSAGE IF LINE ITEM QTY IS = OR } QTY VERIFY IN ORRESPONDING QUOTA EQUIVALENCE RECORD UNLESS QTY VERIFY IS 0");
			aBIErrorCollection["4JD"] = new MessageError(errorCode: "4JD", shortDesc: "TARIFF 1 / TARIFF 2 DISCREPANCY", narrative: "A SECOND TARIFF NUMBER WITHIN CHAPTERS '50' THRU '63' WAS ENTERED WITH A PRIMARY TARIFF NUMBER OF 9802005010 OR 9802008040.  SEE US NOTE 2B WHICH EXCLUDES TEXTILE ARTICLES. SINCE THE ABOVE WAS WRITTEN CHANGE REQUESTS ADDED THE FOLLOWING EDITS TO 9802008040: A HTS NUMBER WITH A TEXTILE CATEGORY NUMBER MAY NOT BE USED AS THE ADDITIONAL TARIFF NUMBER UNLESS IT IS CHAPTER 64.");
			aBIErrorCollection["4JW"] = new MessageError(errorCode: "4JW", shortDesc: "MID REQUIRED FOR ELVIS", narrative: "THIS ERROR WILL OCCUR IF NO MID NUMBER WAS PROVIDED BY THE ABI FILER IN THE EI (ENTRY SUMMARY) APPLICATION 60 RECORD. IT IS MANDATORY FOR THE ABI FILER TO REPORT AN MID NUMBER FOR LINE ITEMS THAT REQUIRE A VISA NUMBER, AND THE COUNTRY OF ORIGIN REPRESENTS AN 'ELVIS' PARTICIPANT.");
			aBIErrorCollection["4K7"] = new MessageError(errorCode: "4K7", shortDesc: "CERTIFICATE NUMBER INVALID", narrative: "THIS MESSAGE OCCURS WHEN A COTTON CERTIFICATE NUMBER IS SENT IN POSITIONS 48-56 OF THE 51 RECORD AND THERE IS NO COTTON FEE CODE (056) INDICATOR IN THE HARMONIZED RECORD. IT WILL ALSO OCCUR WHEN THERE IS A DUAL TARIFF NUMBER (E.G. CHAPTER 99) AND THE TARIFF NUMBER IN THE 70 RECORD DOES NOT HAVE A COTTON FEE CODE. SENDING A COTTON CERTIFICATE NUMBER WITH A NON-NUMERIC OR ONE THAT IS LESS THAN NINE NUMERICS ALSO GENERATES THIS MESSAGE.  THIS MESSAGE WILL ALSO BE GENERATED FOR INVALID ORGANIC CERTIFICATE NUMBERS. USDA WILL ISSUE ORGANIC CERTIFICATE NUMBERS IN THE FOLLOWING FORMAT: POSITIONS 48-54 OF THE 51 RECORD WILL INDICATE 'ORGANIC', POSITIONS 54-56 MAY BE AN ALPHA OR NUMERIC CHARACTER. REFER TO ADMIN MSG 04-2257.");
			aBIErrorCollection["4KI"] = new MessageError(errorCode: "4KI", shortDesc: "GUAM VISA: ENTRY MUST BE NON-ABI", narrative: "IF COUNTRY OF ORIGIN IS GUAM AND VISA NUMBER INDICATES GUAM, THE ENTRY MUST BE NON-ABI.");
			aBIErrorCollection["4KM"] = new MessageError(errorCode: "4KM", shortDesc: "SPI F - NON-QUOTA", narrative: "THE 'F' SPECIAL PROGRAM INDICATOR WITH A TEXTILE TARIFF NUMBER AND AN ELIGIBLE COUNTRY OF ORIGIN EXEMPTS THE LINE FROM QUOTA. A FOLKLORE EXEMPTION CERTIFICATE SHOULD BE PRESENTED WITH THE ENTRY.  FOR ABI PURPOSES, THIS INDICATOR CAN ONLY BE TRANSMITTED ON A TYPE 02 ENTRY. IF ANY OTHER ENTRY TYPE (EXCEPT 07) IS USED, THIS ERROR MESSAGE WILL RESULT.  NOTE: PER HQ QUOTA, THE USE OF 'F' ALSO REMOVES THE 'VISA REQUIRED' CONDITION FOR THE INSTANT TARIFF NUMBER.");
