			aBIErrorCollection["4PP"] = new MessageError(errorCode: "4PP", shortDesc: "INVALID TRFF NBR OR CATEGORY", narrative: "THE ABI VISA QUERY REQUESTED INFORMATION ON AN INVALID TARIFF NBR OR TARIFF NBR SET OR CATEGORY OR CATEGORY/SUFFIX 4PP IS USED WITH THE ABI VISA QUERY");
			aBIErrorCollection["4KQ"] = new MessageError(errorCode: "4KQ", shortDesc: "CERTIFICATE NUMBER NOT REQUIRED", narrative: "THE COTTON EXEMPTION NUMBER IS SENT IN POSITIONS 48-56 OF THE 51 RECORD. THIS MESSAGE OCCURS WHEN AN EXEMPTION CERTIFICATE NUMBER IS SENT FOR A TARIFF NUMBER ON A LINE WHEN IT DOES NOT REQUIRE IT.  SEE ADMINISTRATIVE MESSAGES 01-0389 AND 01-0390 WHICH LIST TARIFF NUMBERS THAT ARE EXEMPTED FROM COTTON FEE REPORTING AND, THEREFORE, DO NOT REQUIRE THE TRANSMISSION OF THE EXEMPTION CERTIFICATE (9 NINES).");
			aBIErrorCollection["4L6"] = new MessageError(errorCode: "4L6", shortDesc: "INVALID SEC SPI FOR TARIFF", narrative: "THIS MESSAGE IS GENERATED IN RESPONSE TO AN ENTRY SUMMARY TRANSACTION (APPLICATION EI). IF A FILER TRANSMITS A QUOTA ENTRY TYPE (02, 07) AND CLAIMS A FOLKLORE EXEMPTION FROM QUOTA/VISA REQUIREMENTS (SPI = F), THE INDIVIDUAL LINES CLAIMED UNDER 'F' MUST HAVE CATEGORY NUMBERS ASSOCIATED WITH THEM. IF THE FILER SHOWS AN 'F' AGAINST A TARIFF NUMBER THAT DOES NOT HAVE A CATEGORY NUMBER, THIS ERROR MESSAGE WILL RESULT.");
