			aBIErrorCollection["4LV"] = new MessageError(errorCode: "4LV", shortDesc: "CN SILK - VISA NBR NOT ALLOWED", narrative: "SILK ARTICLES EXPORTED FROM CHINA (CN) DO NOT REQUIRE A VISAED DOCUMENT SINCE 1993. IF AN ABI TRANSACTION W/ HSA TRFF NBRS FOR SILK ARTICLES IN CATEGORY 733 - 759 IS TRANSMITTED, THE ENTRY WILL BE REJECTED WITH ERROR MSG NBR 4LV. *SILK FROM CHINA HAS NOT REQUIRED A VISAED DOCUMENT (VISA) SINCE 1993. **THIS EDITING WILL PREVENT THE USE OF DUMMY VISA NBRS ABOVE DATA ADDED BY HQ QUOTA. ENTRIES USING THESE CATEGORIES MAY BE FILED USING ENTRY TYPE 01, AS WELL AS 02.");
			aBIErrorCollection["4M6"] = new MessageError(errorCode: "4M6", shortDesc: "QSUP REQD-DAIRY PRODUCT LICENSE", narrative: "THE TARIFF NUMBERS QUERIED, EITHER IN THE QSIQ FUNCTION OR THE ABI QUOTA QUERY, ARE SUBJECT TO AN AGRICULTURE LICENSE REQUIREMENT. IMPORTS OF ITEMS IN THESE TARIFF NUMBERS REQUIRE AN AGRICULTURE LICENSE ISSUED TO THE IMPORTER BY THE U.S. DEPARTMENT OF AGRICULTURE. TO FIND OUT WHAT QUANTITY IS AVAILABLE FOR A GIVEN LICENSE, CONTACT THE U.S.D.A. CHEESE AND DAIRY IMPORT GROUP AT 202- 720-1342 OR 1344. LICENSE REQUIREMENT APPLIES TO CERTAIN CHEESE AND DAIRY PRODUCTS.");
			aBIErrorCollection["4NN"] = new MessageError(errorCode: "4NN", shortDesc: "LINE ITEM VALUE ERROR", narrative: "IF A FILER TRANSMITS A CARGO RELEASE DATA TRANSACTION (APPLICATION HI), AND ALSO ELECTS TO REPORT VALUES AT THE LINE ITEM LEVEL (H5 REC, POS 45-54), THE TOTAL OF ALL VALUES IN THE H5 RECORD MUST EQUAL THE AMOUNT SHOWN AS THE TOTAL ENTRY VALUE (H2 REC, POS 29-38). THE TOTAL DOES NOT AGREE, THIS ERROR MESSAGE WILL BE GENERATED.  NOTE: FOR BORDER CARGO RELEASE, APPLICATION HN, THIS MESSAGE MAY RESULT IF THE FILER OMITS THE VALUE FIELD ON THE 02 RECORD. THERE IS NO TOTAL VALUE IN BORDER CARGO RELEASE, SO THERE IS NO COMPARISON AS THERE IS IN HI  ANOTHER SCENARIO IS WHERE THERE IS A DUAL TARIFF LINE (CH 98 OR 99).ZEROES MUST BE SENT IN THE VALUE FIELD OF THE CH 98 OR 99 NUMBER.");
			aBIErrorCollection["501"] = new MessageError(errorCode: "501", shortDesc: "WARNING! POSSIBLE QUOTA", narrative: "ONE OR MORE COMMODITIES IN THE ENTRY MAY BE A QUOTA ITEM.  FOR IMPORT SECURITY FILING, THIS ERROR WILL RETURN THE MESSAGE 'MIN. ONE SF50 RECORD REQUIRED.' IF THE FILER CODES THE TRANSACTION AS SF SUBMISSION TYPE 2 (ISF-5), AT LEAST ONE SF50 RECORD (FOREIGN PORT OF UNLADING AND PLACE OF DELIVERY) MUST BE INCLUDED. IF NO SF50 RECORD IS TRANSMITTED, THIS ERROR MESSAGE WILL RESULT.");
			aBIErrorCollection["502"] = new MessageError(errorCode: "502", shortDesc: "WARNING! POSSIBLE I.R. TAX", narrative: "ONE OR MORE COMMODITIES ON THE ENTRY MAY BE TAXABLE.  FOR IMPORTER SECURITY FILING, THIS ERROR WILL RETURN THE MESSAGE â€œINVALID LOCATION CODE QUALIFIER.' FOR ISF-5 FILINGS, THE SF50 RECORD PROVIDES TWO FIELDS FOR CODE QUALIFIERS (ONE EACH FOR FOREIGN PORT OF UNLADING AND FOR PLACE OF DELIVERY). IF EITHER FIELD CONTAINS A CODE NOTE DESCRIBED IN NOTE 1 FOR THIS RECORD, THIS ERROR WILL RESULT.");
			aBIErrorCollection["503"] = new MessageError(errorCode: "503", shortDesc: "GSP PREFERENCE CLAIMED", narrative: "ONE OR MORE ENTRY LINES LISTS FREE DUTY UNDER THE GENERALIZED SYSTEM OF PREFERENCES.  FOR IMPORTER SECURITY FILING, THIS ERROR WILL RETURN THE MESSAGE 'INVALID FOREIGN PORT OF UNLADING.' FILINGS FOR ISF-5 REQUIRE AN SF50 RECORD WITH A DESIGNATED FOREIGN PORT OF UNLADING, IN POS 8-22. IF THE REPORTED FOREIGN PORT OF UNLADING IS NOT ON FILE, THIS ERROR WILL RESULT.");
			aBIErrorCollection["504"] = new MessageError(errorCode: "504", shortDesc: "CARIB. BASIN INITIATIVE CLAIMED", narrative: "ONE OR MORE ENTRY LINES LISTS FREE DUTY UNDER THE CARIBBEAN BASIN INITIATIVE.  FOR IMPORTER SECURITY FILING, THIS ERROR WILL RETURN THE MESSAGE 'INVALID PLACE OF DELIVERY.' FILINGS FOR ISF-5 REQUIRE AN SF50 RECORD WITH A DESIGNATED PLACE OF DELIVERY, IN POS 26-40. IF THE REPORTED PLACE OF DELIVERY IS NOT ON FILE, THIS ERROR WILL RESULT.");
			aBIErrorCollection["506"] = new MessageError(errorCode: "506", shortDesc: "CALC. DUTY DOES NOT MATCH EST.", narrative: "THE TOTAL DUTY CALULATED FROM THE ENTRY LINE ITEMS DOES NOT MATCH THE ESTIMATED DUTY FOR THE ENTRY. EACH LINE ON A MULTI-LINE SUMMARY SHOULD REFLECT THE EXACT DUTY AMOUNT DUE, BASED ON THE DUTY RATES APPLICABLE TO THE TARIFF NUMBER. HOWEVER, ABI WILL ALLOW A DIFFERENCE, PER LINE, OF UP TO $2.99 (PLUS OR MINUS) BETWEEN THE ACTUAL CALCULATED DUTY AMOUNT AND THE AMOUNT TRANSMITTED BY THE ABI FILER. THIS $2.99 DIFFERENCE ALSO APPLIES TO THE ENTRY, AS A WHOLE. THUS, WHILE INDIVIDUAL LINES MAY BE ALLOWED WITH THE DUTY DISCREPANCY CITED ABOVE, THE ENTRY MAY STILL BE REJECTED IF THE TOTAL DUTY AMOUNT TRANSMITTED (90 REC, POS 3-13) IS MORE THAN $2.99 ABOVE OR BELOW THE AMOUNT CALCULATED BY ABI AS BEING THE ACTUAL DUTY FOR ALL LINES ON THE SUMMARY.");
			aBIErrorCollection["508"] = new MessageError(errorCode: "508", shortDesc: "TOTAL TAX DOES NOT MATCH EST.", narrative: "THE TOTAL INTERNAL REVENUE TAX (REC 90, POS 14-24) DOES NOT EQUAL THE TOTAL OF THE LINE ITEM INTERNAL REVENUE TAXES IN RECS 60, POS 59-68.");
