			aBIErrorCollection["585"] = new MessageError(errorCode: "585", shortDesc: "ENT-SUM ACCEPTED WITH ERRORS", narrative: "THIS IS AN OUTDATED SUMMARY RESPONSE MESSAGE. AT ONE TIME SUMMARY INPUT WOULD BE ACCEPTED WITH CERTAIN CLASSES OF OTHERWISE REJECTABLE ERRORS. THAT IS NO LONGER THE CASE.");
			aBIErrorCollection["58D"] = new MessageError(errorCode: "58D", shortDesc: "QUOTA ENTRY-SUM IN CUSTOMS STATUS", narrative: "THIS MESSAGE OCCURS WHEN A FILER ATTEMPTS TO SEND AN ENTRY SUMMARY TRANSACTION FOR A QUOTA ENTRY SUMMARY WHERE THE QUOTA PROCESSING HAS BEEN DONE BY CUSTOMS. THE QUOTA STATUS WOULD NEED TO BE REMOVED IN ORDER FOR THE FILER TO RE-TRANSMIT.");
			aBIErrorCollection["58F"] = new MessageError(errorCode: "58F", shortDesc: "BROKER REFERENCE NUMBER REQUIRED", narrative: "ABI ENTRY SUMMARIES PROVIDE A FIELD FOR THE USER'S REFERENCE NUMBER (CALLED THE 'BROKER REFERENCE NUMBER), WHICH IS TRANSMITTED IN THE 20 RECORD, POS 40-48. IF THE FILER USES THE 'A' ACTION CODE, THIS FIELD IS OPTIONAL. IF ACTION CODE 'R' IS USED ON THE INITIAL INPUT OF THE ENTRY NUMBER, THE BROKER REF NUMBER IS REQUIRED.");
			aBIErrorCollection["58L"] = new MessageError(errorCode: "58L", shortDesc: "ENT-SUM ACCPTD W/WARNINGS;PAP REQ", narrative: "ENTRY SUMMARIES ARE CONSIDERED 'CERTIFIED FOR PAPERLESS' AND WILL RECEIVE A PAPERLESS DESIGNATION UNLESS PAPERLESS IS DEFEATED. ONE REASON IS BECAUSE OF WARNINGS SUCH AS CENSUS WARNINGS. THIS MESSAGE WILL RESULT TELLING FILER THEY MUST FILE PAPER DOCUMENTS WITH CUSTOMS.");
			aBIErrorCollection["510"] = new MessageError(errorCode: "510", shortDesc: "TOTAL ADD DOES NOT MATCH EST.", narrative: "IF THE TOTAL ANTI-DUMPING DUTY REPORTED ON EACH LINE OF THE SUMMARY IN THE 60 RECORD IS WITHIN $2.99 (PLUS OR MINUS) OF THE CORRECT CALCULATED AMOUNT FOR THE LINE, ABI WILL ACCEPT THE LINE AMOUNT. HOWEVER, IF THE SUMMARY HAS MORE THAN ONE LINE WITH ANTI-DUMPING DUTY DUE, THE GRAND TOTAL OF ALL ANTI-DUMPING DUTY AMOUNTS MUST ALSO BE WITHIN $2.99 (PLUS OR MINUS) OF THE SYSTEM-CALCULATED AMOUNT. EVEN IF THE TOTAL AMOUNT OF ANTI-DUMPING DUTY (90 REC, POS 38-48) IS EQUAL TO THE VARIOUS LINE AMOUNT TOTALS, ABI WILL REJECT THE ENTRY SUMMARY IF THE TOTAL AMOUNT TRANSMITTED IS NOT WITHIN THE STATED TOLERANCE AS COMPARED TO THE CALCULATED TOTAL ANTI-DUMPING DUTY AMOUNT.  OTE: IF THE BONDED INDICATOR IN POS 80 OF THE 60 RECORD IS LEFT BLAN, THIS ERROR WILL OCCUR, EVEN IF THE MONETARY VALUES ALL AGREE.");
			aBIErrorCollection["512"] = new MessageError(errorCode: "512", shortDesc: "TOTAL CVD DOES NOT MATCH EST.", narrative: "IF THE TOTAL COUNTERVAILING DUTY REPORTED ON EACH LINE OF THE SUMMARY IN THE 60 RECORD IS WITHIN $2.99 (PLUS OR MINUS) OF THE CORRECT CALCULATED AMOUNT FOR THE LINE, ABI WILL ACCEPT THE LINE AMOUNT. HOWEVER, IF THE SUMMARY HAS MORE THAN ONE LINE WITH COUNTERVAILING DUTY DUE, THE GRAND TOTAL OF ALL COUNTERVAILING DUTY AMOUNTS MUST ALSO BE WITHIN $2.99 (PLUS OR MINUS) OF THE SYSTEM- CALCULATED AMOUNT. EVEN IF THE TOTAL AMOUNT OF COUNTERVAILING DUTY (90 REC, POS 27-37) IS EQUAL TO THE VARIOUS LINE AMOUNT TOTALS, ABI WILL REJECT THE SUMMARY IF THE TOTAL AMOUNT TRANSMITTED IS NOT WITHIN THE STATED TOLERANCE AS COMPARED TO THE CALCULATED TOTAL COUNTERVAILING DUTY AMOUNT.  NOTE: IF THE CVD BONDED INDICATOR IN POS 79 OF THE 60 RECORD IS LEFT BLANK, THIS ERROR WILL RESULT, EVEN IF THE MONETARY AMOUNTS ALL AGREE.");
			aBIErrorCollection["51A"] = new MessageError(errorCode: "51A", shortDesc: "INFORMAL ENTRY HAS TOO HIGH VALUE", narrative: "VALUE LIMIT FOR ALL INFORMAL ENTRIES IS $2000, EXCEPT FOR 'AMERICAN GOODS RETURNED' IN CHAPTER 98 AND 'PERSONAL' SHIPMENTS (INDICATOR 'P' IS SENT BY THE FILER IN THE 30 REC, POS 39). SELECTED TARIFF NUMBERS ARE ALSO SUBJECT TO DOLLAR LIMITATIONS FOR INFORMAL ENTRIES AS LISTED IN APPENDIX K OF THE CATAIR, PAGE K-3. SEE ALSO ERROR MESSAGE 51D.  FOR AMERICAN GOODS RETURNED ENTRIES, USING TARIFF 98010010NN ONLY, THE VALUE LIMIT IS $10,000. FOR INFORMAL ENTRIES USING 'P', THERE IS NO VALUE LIMIT EXCEPT AS MENTIONED ABOVE IN APPENDIX K FOR CERTAIN TEXTILE PRODUCTS.");
			aBIErrorCollection["51D"] = new MessageError(errorCode: "51D", shortDesc: "INFORMAL ENTRY IS NOT PERMITTED", narrative: "SINCE MARCH OF 1994 THE REQUIREMENT FOR MAKING FORMAL ENTRY ON A GIVEN TARIFF NUMBER HAS BEEN INDICATED IN THE ON-LINE 'HSA' RECORD. THE FIELD CONTAINING THIS INFORMATION IS CALLED 'MIS-REQ'. THERE ARE (3) VALID VALUES FOR THIS FIELD:  '0' = FORMAL ENTRY REQUIRED, REGARDLESS OF VALUE  '2' = FORMAL ENTRY REQUIRED FOR VALUE GREATER THAN $250  'Z' = TARIFF NOT ELIGIBLE FOR DUTY-FREE TREATMENT UNDER  'FREELY ASSOCIATED STATES' (FAS) PROGRAM.  IF A RECORD CONTAINS A '0' AND '2' THE '0' CONDITION APPLIES. THIS ERROR MESSAGE WILL BE GENERATED IF A TARIFF NUMBER ON THE ENTRY IS CODED '0' AND THE ENTRY TYPE IS INFORMAL. IF THE TARIFF NUMBER IS CODED '2', ERROR MESSAGE Z29 WILL APPLY.");
			aBIErrorCollection["523"] = new MessageError(errorCode: "523", shortDesc: "ENTRY NBR MUST BE NUMERIC", narrative: "IF FY PRIOR TO 1981, MUST BE LAST 2 DIGITS OF THE FY + 6 NUMBERS  IF FY '81 THROUGH FY '86, MUST BE LAST 2 DIGITS OF THE FY, 6 NUMBERS, AND NUMERIC CHECK DIGIT.  IF NEW ENTRY NUMBER MUST BE 3 CHARACTER ALPHA-NUMERIC FILER CODE, 7 NUMBER SEQUENCE NUMBER, AND 1 NUMERIC CHECK DIGIT.  NO SPECIAL CHARACTERS OR IMBEDDED BLANKS.");
			aBIErrorCollection["524"] = new MessageError(errorCode: "524", shortDesc: "TRANSACTION DATA REJECTED", narrative: "USED BY ABI BATCH PROCESSING WHEN REJECTING A USER TRANSACTION. THIS MESSAGE MUST BE ASSOCIATED WITH ALL CONDITIONS WHICH CONSTITUTE REJECTION OF THE TRANSACTION.");
