			aBIErrorCollection["52Y"] = new MessageError(errorCode: "52Y", shortDesc: "MAXIMUM I7 RECORDS EXCEEDED", narrative: "REFER TO ADMINISTRATIVE MESSAGE 98-0236, DATED 032098. IN SOME CASES THE ULTIMATE CONSIGNEE NAME AND ADDRESS APPLICATION (IJ) WAS CAUSING DATA BASE ERRORS WHEN THE NUMBER OF I7 ENTRY NUMBER/LINE ITEM SEQUENCE RECORDS EXCEEDED THE LIMIT SET BY THE PROGRAM FOR A PARTICULAR NAME AND ADDRESS I3 AND I4 RECORD SET. ALSO, IN SOME REJECT SITUATIONS THE ERROR MESSAGE '524 TRANSACTION DATA REJECTED' WAS DISPLAYING ERRONEOUSLY IN THE IB OUTPUT MESSAGES WHEN THE ENTIRE IJ APPLICATION WAS NOT REJECTED. TO ELIMINATE THE ABOVE SITUATIONS AND TO PROVIDE MORE ACCURATE INFORMATION WHEN ERRORS ARE DETECTED IN THE ULTIMATE CONSIGNEE NAME AND ADDRESS APPLICATION (IJ) TRANSMISSIONS, THIS ERROR MESSAGE AND 52Z 'ENTRY/LINE SEQUENCE REJECTED' ARE GENERATED. BOTH THE 52Y AND 52Z MESSAGES WILL APPEAR AS IB OUTPUT RECORDS WHEN CUSTOMS DETERMINES THAT THE INFORMATION TRANSMITTED CANNOT BE ADDED TO THE DATABASE AS REQUESTED BY AN ABI FILER.");
			aBIErrorCollection["52Z"] = new MessageError(errorCode: "52Z", shortDesc: "ENTRY/LINE SEQUENCE REJECTED", narrative: "REFER TO ADMINISTRATIVE MESSAGE 98-0236, DATED 032098. IN SOME CASES THE ULTIMATE CONSIGNEE NAME AND ADDRESS APPLICATION (IJ) WAS CAUSING DATA BASE ERRORS WHEN THE NUMBER OF I7 ENTRY NUMBER/LINE ITEM SEQUENCE RECORDS EXCEEDED THE LIMIT SET BY THE PROGRAM FOR A PARTICULAR NAME & ADDRESS I3 AND I4 RECORD SET. ALSO, IN SOME REJECT SITUATIONS THE ERROR MESSAGE '524 TRANSACTION DATA REJECTED' WAS DISPLAYING ERRONEOUSLY IN THE IB OUTPUT MESSAGES WHEN THE ENTIRE IJ APPLICATION WAS NOT REJECTED. TO ELIMINATE THE ABOVE SITUATIONS AND TO PROVIDE MORE ACCURATE INFORMATION WHEN ERRORS ARE DETECTED IN THE ULTIMATE CONSIGNEE NAME AND ADDRESS APPLICATION (IJ) TRANSMISSIONS, THIS ERROR MESSAGE AND 52Y 'MAXIMUM I7 RECORDS EXCEEDED' ARE GENERATED. BOTH THE 52Y AND 52Z MESSAGES WILL APPEAR AS IB OUTPUT RECORDS WHEN CUSTOMS DETERMINES THAT THE INFORMATION TRANSMITTED CANNOT BE ADDED TO THE DATABASE AS REQUESTED BY AN ABI FILER.");
			aBIErrorCollection["531"] = new MessageError(errorCode: "531", shortDesc: "NON-NUMERIC IN NUMERIC FIELD", narrative: "IN ACS, ALL MONEY FIELDS AND CERTAIN FIELDS USED AS SWITCHES OR COUNTERS ARE DEFINED AS NUMERIC. DURING ABI PROCESSING OF BROKER DATA, IF A FIELD CONTAINS ALPHA CHARACTERS AND IT SHOULD BE NUMERIC, THE USER WILL RECEIVE THIS MESSAGE. AFTER SYSTEM TESTING WITH BROKERS, THIS MESSAGE SHOULD NOT OCCUR. THIS MESSAGE WILL ALSO BE GENERATED IF THE NUMERIC FIELD IS FILLED WITH BLANK DATA (AT LEAST IN THE CI-AUTOMATED INVOICE-TRANSACTION).");
