			aBIErrorCollection["57B"] = new MessageError(errorCode: "57B", shortDesc: "ENTRY SUMMARY REPLACED, DOCS REQD", narrative: "MESSAGE ISSUED TO BROKERS WHEN REPLACEMENT ENTRY SUMMARY IS ERROR FREE AND ENTRY IS PAPERLESS");
