			aBIErrorCollection["BRG"] = new MessageError(errorCode: "BRG", shortDesc: "INVALID OTHER ISSUE", narrative: "FILER HAS ATTEMPTED TO FILE A RECON FOR AN 'OTHER' ISSUE AGAINST AN IMPORT ENTRY THAT IS NOT FLAGGED FOR AN 'OTHER' NAFTA ISSUE, OR THE FILER HAS ATTEMPTED TO FILE A RECON FOR AN 'OTHER' ISSUE FOR AN IMPORT THAT HAS BEEN FLAGGED FOR A DIFFERENT 'OTHER' ISSUE.  EG - FILER ATTEMPTS RECON FOR 'CL' ISSUE AND IMPORT FLAGGED FOR 'VL'  ALSO, IF AN IMPORT ENTRY WAS FLAGGED AT SOME POINT IN THE PAST, BUT IS NOT FLAGGED AT THE TIME THAT THE RECON ENTRY IS RANSMITTED TO ABI, THIS MESSAGE WILL BE GENERATED, INSTEADOF 'ENTRY NOT SUBJECT TO RECON'.");
