			aBIErrorCollection["BRW"] = new MessageError(errorCode: "BRW", shortDesc: "EARLIEST SUMM DATE MUST = SPACES", narrative: "RECONCILIATION: WHEN THE R10 ISSUE CODE = 'NF', THE R10 EARLIEST SUMMARY DATE MUST = SPACES.");
			aBIErrorCollection["BRX"] = new MessageError(errorCode: "BRX", shortDesc: "EARLIEST IMPRT DATE MUST = SPACES", narrative: "RECONCILIATION: WHEN THE R10 ISSUE CODE IS NOT = 'NF', THE R10 EARLIEST IMPORT DATE MUST = SPACES.");
			aBIErrorCollection["BRY"] = new MessageError(errorCode: "BRY", shortDesc: "POSSIBLE DUTY MISMATCH", narrative: "R20 ORIGINAL DUTY DOES NOT MATCH PAID / LIQ DUTY  THIS MESSAGE IS RETURNED IF THE R20 REC, POS 23-33, AMOUNT DOES NOT EXACTLY AGREE WITH THE PAID DUTY ON THE ENAI RECORD FOR THE IMPORT ENTRY LISTED IN THE R20 RECORD, POS 8-18. THERE CAN BE SEVERAL CAUSES FOR THIS ERROR, BUT THE MOST COMMON ONE IS THAT THE FILER WILL SEND ALL ZEROS IN THE R20 FOR AN IMPORT ENTRY THAT HAD DUTY PAID. ANOTHER POSSIBLE REASON IS WHEN TWO OR MORE COLLECTIONS WERE DEPOSITED ON THE SAME IMPORT ENTRY AND THE FILER HAS NOT KEPT ACCURATE RECORDS REFLECTING THE TOTAL AMOUNT OF DUTY PAID.");
