			aBIErrorCollection["CBB"] = new MessageError(errorCode: "CBB", shortDesc: "STATE/ZIP MISMATCH", narrative: "THE STATE CODE AND ZIP CODE CAN BE SENT IN MANY APPLICATIONS IN ABI. A ZIP CODE FILE (SEE FUNCTION CODE ZIPL) EXISTS TO CHECK THE FIRST THREE DIGITS OF THE ZIP CODE AGAINST THE STATE CODE GIVEN. IF IT DOES NOT MATCH,THIS ERROR MESSAGE RESULTS");
			aBIErrorCollection["CF1"] = new MessageError(errorCode: "CF1", shortDesc: "FEI NOT FOUND ON ACS", narrative: "THE FEI NUMBER (FDA ESTABLISHMENT IDENTIFIER) QUERIED IS NOT ON FILE IN THE FDF FILE RESIDENT IN ACS. THIS IS A FROM A 'Q' INDICATOR AS OPPOSED TO AN 'A' (ADD) INDICATOR.");
