			aBIErrorCollection["DDB"] = new MessageError(errorCode: "DDB", shortDesc: "OTHER RECONCILIATION NOT FILED", narrative: "A DRAWBACK CLAIM CANNOT BE FILED AGAINST AN IMPORT ENTRY THAT HAS BEEN FLAGGED FOR RECONCILIATION UNTIL SUCH TIME AS THE RECONCILIATION SUMMARY HAS BEEN FILED AND PAID.  AT THE TIME OF LIQUIDATION, THIS MESSAGE IS ALSO USED TO ALERT THE USER THAT AN 'OTHER' RECONCILIATION IS DUE ON A TYPE '01', '02', OR '06' ENTRY, BUT HAS NOT YET BEEN FILED. THIS MESSAGE IS OVERRIDEABLE AT LIQUIDATION.");
