			aBIErrorCollection["J03"] = new MessageError(errorCode: "J03", shortDesc: "MASTER BILL NOT COMPLETE", narrative: "THIS MESSAGE APPEARS TO RELATE TO THE BILL OF LADING UPDATE TRANSACTION (APPLICATION LN) WHEN AN AIR SHIPMENT IS BEING CORRECTED. THE L3 RECORD, POS 20-31, PROVIDES FOR THE AIR WAYBILL DATA. IF THIS FIELD IS COMPLETED PROPERLY WITH A VALID AIR WAYBILL OF 11 DIGITS (WITH NO INCLUDED SPACES, DASHES OR OTHER CHARACTERS) THE 12TH POSITION OF THE FIELD MUST BE A SPACE. THIS FIELD MUST BE LEFT JUSTIFIED.  THIS MESSAGE WILL ALSO BE GENERATED IN THE HI APPLICATION IF THE AIR WAYBILL NUMBER DOES NOT CONTAIN 11 CHARACTERS. AFTER SEPTEMBER 1998 (TIN MAN REVISION) ENTRIES FOR ALL MODES OF TRANSPORTATION THAT INVOLVE INBOND NUMBERS WILL REJECT IF THE MASTER BILL FIELD IS NOT COMPLETED. (SEE ADMIN MSG 98-0640)");
			aBIErrorCollection["J04"] = new MessageError(errorCode: "J04", shortDesc: "LAST 8 CHARACTERS MUST BE NUMERIC", narrative: "THIS MESSAGE PERTAINS TO AIR WAYBILL NUMBERS. MASTER AIR WAYBILL NUMBERS ARE ALL NUMERIC IN FORMAT. HOUSE AIR WAYBILL NUMBERS ARE PERMITTED TO REFLECT ALPHA CHARACTERS. IF THE FILER TRANSMITS A MASTER AIR WAYBILL NUMBER THAT INCLUDES ALPHA CHARACTERS, THIS ERROR MESSAGE WILL RESULT.  ALSO RETURNED IN ENHANCED 'IN' CARGO/MANIFEST QUERY WHEN THE LAST EIGHT CHARACTERS IN THE AWB USED AS AN IN-BOND ARE NOT NUMERIC.");
			aBIErrorCollection["J05"] = new MessageError(errorCode: "J05", shortDesc: "AWB MUST BE 8 CHARACTERS", narrative: "HOUSE AIR WAYBILLS MUST CONTAIN AT LEAST 8 CHARACTERS. IF FEWER THAN 8 CHARACTERS ARE TRANSMITTED IN THE INPUT RECORDS (EI, 22 REC, POS 27-38, HI, HA REC, POS 27-38), THIS ERROR MESSAGE WILL RESULT.  THE '8-CHARACTER' AWB NUMBER REFERS TO THE DIGITS FOLLOWING THE AIR CARRIER'S PREFIX (THREE CHARACTER NUMERIC IN POS 15-17 OF THE 22 REC IN EI OR POS 15-17 OF THE HA REC IN HI). IF THE PORT OF UNLADING IS AN AMS AIRPORT, ONLY 11- CHARACTERS (PREFIX + 8 DIGIT AWB) IS PERMITTED. SOME CARRIERS PERIODICALLY USE A 9-CHARACTER AWB FOLLOWING THE PREFIX FOR INTERNAL USES. THIS TYPE OF AWB WILL NOT BE ACCEPTED AT AIR AMS PORTS, BUT WILL BE ACCEPTED AT A NON-AMS PORT (SUCH AS 2895, THE FEDEX COURIER FACILITY IN OAKLAND, CA).");
			aBIErrorCollection["J11"] = new MessageError(errorCode: "J11", shortDesc: "I.T. AWB PREFIX NOT ON FILE", narrative: "THE FIRST THREE DIGITS OF THE IT NUMBER SENT IN AN AIR ENVIRONMENT (MOT = 40) ENTRY, EI RECORD, POSITIONS 3-5; HI RECORD HA, POSITIONS 3-5 MUST BE A VALID AWB PREFIX IN THE CAR FILE (QUERY CARL 3/).  ALSO: IF A FILER SENDS AN IN-BOND NUMBER WITH 10 DIGITS (EVEN THOUGH ALL OTHER INDICATORS REFLECT THAT THE MOT IS NOT AN AIR SHIPMENT) ABI INTERPRETS THE I.T. AS AN INCOMPLETE AIR WAYBILL AND GENERATES THIS MESSAGE.");
			aBIErrorCollection["J12"] = new MessageError(errorCode: "J12", shortDesc: "I.T. MASTER BILL NOT COMPLETE", narrative: "THIS MESSAGE APPLIES TO THE CARGO RELEASE INPUT TRANSACTION, APPLICATION HI. IF THE FILER REPORTS AN AIR WAYBILL AS THE I.T. NUMBER, THE NUMBER MUST CONTAIN 11 DIGITS (3 FOR THE CARRIERS PREFIX AND 8 FOR THE MASTER BILL NUMBER). IF ANY OF THE DIGITS ARE OMITTED, THIS MESSAGE WILL RESULT.  NOTE: IF DIGITS ARE OMITTED FROM AN OCEAN MASTER IN BOND NUMBER, ERROR MESSAGE 4A3, INVALID IN-BOND NUMBER, WILL BE GENERATED.  ALSO RETURNED IN THE ENHANC'IN' CARGO/MANIFEST QUERY WHEN THERE IS INSUFFICIENT INFORMATION TO COMPLETE THE MASTER AWB.");
			aBIErrorCollection["LU1"] = new MessageError(errorCode: "LU1", shortDesc: "LUMBER PERMIT/ORIG CNTRY INVALID", narrative: "LUMBER PERMIT CANNOT BE ENTERED FOR COUNTRY OF ORIGIN OF 'CA'");
			aBIErrorCollection["LU2"] = new MessageError(errorCode: "LU2", shortDesc: "INVALID LUMBER PERMIT TYPE", narrative: "THE SOFTWOOD LUMBER PERMIT TYPE IS TRANSMITTED IN THE 40 REC, POS 70-72. IT IS MANDATORY FOR MERCHANDISE ENTERED UNDER ONE OF THE FOLLOWING TARIFF NUMBER SUBHEADINGS OF 44071000, 44091020, OR 44091090 WITH PROVINCE OF ORIGIN CODES: XA, XC, XO, OR XQ. POS 70 OF THE 40 REC MUST CONTAIN EITHER 'A', 'B', 'C', OR 'D.' IF POS 70 CONTAINS 'A', 'B', OR 'C', THEN POS 71-72 MUST CONTAIN ZEROES OR SPACES. IF POS 70 CONTAINS 'D', THEN POS 71-72 MUST CONTAIN A TWO-CHARACTER NUMERIC CODE THAT FALLS WITHIN THE RANGE OF 01 THROUGH 20, DEPENDING ON THE CALENDAR QUARTER DURING WHICH THE PERMIT IS ISSUED. SEE ADMIN MESSAGE 97-0579 FOR MORE INFORMATION ON LUMBER PERMITS.  AS OF APRIL 2001, THE SLA PROGRAM EXPIRED. PERMIT TYPES ARE NO LONGER PERMITTED IN THE 40 RECORD.");
			aBIErrorCollection["LU3"] = new MessageError(errorCode: "LU3", shortDesc: "LUMBER PERMIT NOT ALLOWED", narrative: "THE SOFTWOOD LUMBER AGREEMENT BETWEEN CANADA AND THE UNITED STATES REQUIRES A SOFTWOOD LUMBER PERMIT NUMBER FOR LUMBER MILL PRODUCTS CLASSIFIED IN SUBHEADINGS 4407.10.00, 4409.10.10, 4409.10.20 AND 4409.10.90 THAT WERE 'FIRST MANUFACTURED' INTO A PRODUCT IN THE CANADIAN PROVINCES OF XO, XQ, XC OR XA. THE LUMBER PRODUCT MUST MEET BOTH CRITERIA - TARIFF NUMBER AND PROVINCE. THE LUMBER PERMIT NUMBER IS SENT IN POSITIONS 57-65 OF THE 51 RECORD. THIS MESSAGE OCCURS WHEN A LUMBER PERMIT NUMBER IS SENT FOR A TARIFF NUMBER THAT IS NOT IN THE ABOVE NAMED SUBHEADINGS OR FOR A TARIFF NUMBER IN THE SUBHEADINGS BUT NOT FROM ONE OF THE FOUR NAMED PROVINCES. THE ERROR MESSAGE IS SENT WITH THE 50 RECORD NOT THE 51 RECORD.");
			aBIErrorCollection["LU4"] = new MessageError(errorCode: "LU4", shortDesc: "INVALID LUMBER PERMIT NUMBER", narrative: "IF THE ABI FILER REPORTS A LUMBER PERMIT TYPE (40 REC, POS 70-72), A NINE-POSITION NUMERIC LUMBER PERMIT NUMBER IS REQUIRED IN THE 51 REC, POS 57-65. IF THE PERMIT NUMBER IS OMITTED, THIS ERROR MESSAGE WILL BE GENERATED.  AS OF APRIL 2001, THE PERMIT NUMBER IS NO LONGER REQUIRED.");
			aBIErrorCollection["OP1"] = new MessageError(errorCode: "OP1", shortDesc: "SPI S & 9802008016 INVALID", narrative: "THE USE OF SPI S AND TARIFF NBR 9802.00.8016 ARE PROHIBITED TARIFF NBR 9802.00.8016 = FABRIC MADE AND CUT IN US/SEWN IN RO OR MK SPI 'S' = FABRIC MADE IN US/CUTAND SEWN IN RO OR MK SPI 'S' AND TARIFF NBR 9802.00.8016 ARE RESTRICTED FOR RO AND MK FOR ABI PURPOSES, IF THE FILER TRANSMITS A 'S' IN POS 80 OF THE 50 RECORD, AND THE COUNTRY OF ORIGIN IS EITHER RO OR MK, HTS 9802008016 CANNOT BE SHOWN ON THE 40 RECORD. SPI 'S' AND THIS HTS ARE MUTUALLY EXCLUSIVE AS THEY BOTH MEAN THE SAME THING.  THIS MESSAGE WILL ALSO RESULT IF THE FILER TRANSMITS 9802008016 WITH ANY COUNTRY OF ORIGIN OTHER THAN RO OR MK.");
			aBIErrorCollection["OP3"] = new MessageError(errorCode: "OP3", shortDesc: "OPP CERTIFICATE REQUIRED", narrative: "THE DOCUMENT NUMBER IN THE 51 RECORD HAS A '1' IN THE FOURTH POSITION THIS IS A VISA DOCUMENT NUMBER IN THE 51 RECORD REQUIRES A '2' FOR THE OUTWARD PROCESSING PROGRAM CERTIFICATE NUMBER TO BE VALID");
			aBIErrorCollection["OP6"] = new MessageError(errorCode: "OP6", shortDesc: "INVALID CATEGORY FOR OPP CERT", narrative: "THE CATEGORY IS NOT ALLOWED WITH SPI = 'S' OR TARIFF 1 = 9802.00.8016 THESE CRITERIA REQUIRE AN OUTWARD PROCESSING PROGRAM (OPP) CERTIFICATE.");
