			aBIErrorCollection["OP9"] = new MessageError(errorCode: "OP9", shortDesc: "INVALID COUNTRY-CATEGORY FOR OPP", narrative: "THE COUNTRY OF ORIGIN IS AN OPP COUNTRY. HOWEVER, THE CATEGORY IS NOT VALID FOR THE OUTWARD PROCESSING PROGRAM (OPP) AND THEREFORE, THIS ERROR IS ISSUED.");
			aBIErrorCollection["OY1"] = new MessageError(errorCode: "OY1", shortDesc: "OTHER IND 1 MUST BE NUMERIC & } 0", narrative: "IF DATA IS ENTERED IN THE OTHER INDICATOR 1 FIELD, THE DATA ENTERED MUST BE A 2 DIGIT NUMBER THAT RANGES FROM '01' TO '99'");
			aBIErrorCollection["OY2"] = new MessageError(errorCode: "OY2", shortDesc: "OTHER DATA ELEMENT 1 REQUIRED", narrative: "IF DATA IS ENTERED IN THE OTHER INDICATOR 1 FIELD, THEN DATA MUST BE ENTERED IN THE OTHER DATA ELEMENT 1 FIELD.");
			aBIErrorCollection["OY3"] = new MessageError(errorCode: "OY3", shortDesc: "OTHER INDICATOR 1 FIELD REQUIRED", narrative: "IF DATA IS ENTERED IN THE OTHER DATA ELEMENT 1 FIELD, THEN THERE MUST BE A VALID NUMERIC DATA ENTERED IN THE OTHER INDICATOR 1 FIELD.");
			aBIErrorCollection["OY4"] = new MessageError(errorCode: "OY4", shortDesc: "OTHER IND 2 MUST BE NUMERIC & } 0", narrative: "IF DATA IS ENTERED IN THE OTHER INDICATOR 2 FIELD, THEN THE OTHER INDICATOR 2 FIELD MUST BE ENTERED WITH A 2 DIGIT NUMERIC THAT RANGES FROM '01' TO '099'.");
			aBIErrorCollection["PN0"] = new MessageError(errorCode: "PN0", shortDesc: "PN WAS PREVIOUSLY ACCEPTED", narrative: "FILER CANNOT RESCHEDULE AN ENTRY FOR STATEMENTS IF 3 CONDITIONS OCCURRED PREVIOUSLY: 1. ENTRY WAS PART OF A PERIODIC STATEMENT 2. PN TRANSACTION WAS ACCEPTED FOR THE PERIODIC DAILY STATEMENT 3. ENTRY WAS REMOVED FROM THE PERIODIC STATEMENT IN OTHER WORDS, ONCE A 'PN' TRANSACTION IS ACCEPTED, AN ENTRY CAN BE PAID VIA PERIODIC STATEMENTS OR CHANGED TO A SINGLE PAY, THE ENTRY CANNOT BE RESCHEDULED FOR STATEMENTS.");
			aBIErrorCollection["PN4"] = new MessageError(errorCode: "PN4", shortDesc: "PN SUBMITTED LATE", narrative: "THE PN TRANSACTION IS SUBMITTED AFTER THE PERIODIC MONTHLY STATEMENT IS SCHEDULED TO BE PRINTED. WHEN A PN IS LATE, PARTICIPANT CAN CHANGE ALL ENTRY SUMMARIES TO SINGLE PAYMENT OR TO A REGULAR DAILY STATEMENT (PAY BASIS 2, 3, 5).  NOTE: IF THE STATEMENT IN QUESTION IS AN IMPORTER STATEMENT, CHECK SRES FOR THE IMPORTER NUMBER. IF THE PMS PRINT DATE IS EARLIER THAN THE DATE THAT PN WAS TRANSMITTED, THIS ERROR WILL RESULT. IMPORTERS HAVE THE OPTION OF DESIGNATING A PRINT DATE THAT DIFFERS FROM THE DATE THAT IS REFLECTED IN THEIR BROKER'S ABE RECORD.  CHECK THE DP-SITE ABE RECORD FOR THE FILER. THE DATES ON PAGE 2 MAY HAVE CHANGED FROM THE DEFAULT DATES. IF THEY HAVE, THIS ERROR WILL RESULT IF THE PN IS BEING TRANSMITTED AFTER THE DATE SHOWN ON THE ABE RECORD FOR THE BROKER (OR SRES RECORD FOR AN ABI/ACE IMPORTER).");
			aBIErrorCollection["PN6"] = new MessageError(errorCode: "PN6", shortDesc: "INVALID PAY BASIS", narrative: "PN TRANSACTION EXPECTS DSA PAY BASIS TO = '6', '7', OR '8'. THIS MEANS THAT THE ENTRY(S) ON THE STATEMENT FOR WHICH A PN IS BEING TRANSMITTED WERE NOT ORIGINALLY ACCEPTED BY ABI WITH PAY BASIS 6, 7 OR 8. THEREFORE, THE PN TRANSACTION IS NOT APPROPRIATE FOR THE AFFECTED STATEMENT.");
			aBIErrorCollection["PN7"] = new MessageError(errorCode: "PN7", shortDesc: "STMT NOT SCHEDULED FOR PERIODIC", narrative: "THE DSA-PERDC-IND IS NOT = '2' (PERDC-DETAIL). PN TRANSACTION IS REJECTED.");
			aBIErrorCollection["PN8"] = new MessageError(errorCode: "PN8", shortDesc: "DUPLICATE PT", narrative: "THE STATEMENT NUMBER ON THE PN ALREADY EXISTS ON COD FILE.");
			aBIErrorCollection["PNS"] = new MessageError(errorCode: "PNS", shortDesc: "PROTESTANT NOT ON SRE FILE", narrative: "PROTESTANT NUMBERS (EXCEPT WHEN THE PROTESTANT TYPE IS 'F' (FOREIGN) 'O' (OTHER) OR 'S' (SURETY), MUST BE IN IRS, EIN, SOCIAL SECURITY OR CUSTOMS ASSIGNED (NEW) FORMAT. A MATCH FOR THE NUMBER USED MUST BE FOUND ON THE USCS IMPORTER (CF5106) FILE DATABASE.");
			aBIErrorCollection["PRV"] = new MessageError(errorCode: "PRV", shortDesc: "REV REQST MAY BE UNTIMELY", narrative: "THE PN TRANSACTION IS SUBMITTED AFTER THE PERIODIC MONTHLY STATEMENT IS SCHEDULED TO BE PRINTED. WHEN A PN IS LATE, PARTICIPANT CAN CHANGE ALL ENTRY SUMMARIES TO SINGLE PAYMENT OR TO A REGULAR DAILY STATEMENT (PAY BASIS 2,3,5).NOTE:  IF THE STATEMENT IN QUESTION IS AN IMPORTER STATEMENT, CHECK SRES FOR THE IMPORTER NUMBER.  IF THE PMS PRINT DATE IS EARLIER THAN THE DATE THAT PN WAS TRANSMITTED, THIS ERROR WILL RESULT.  IMPORTERS HAVE THE OPTION OF DESIGNATING A PRINT DATE THAT DIFFERS FROM THE DATE THAT IS REFLECTED IN THEIR BROKER''S ABE RECORD. CHECK THE DP-SITE ABE RECORD FOR THE FILER.  THE DATES ON PAGE 2 MAY HAVE CHANGED FROM THE DEFAULT DATES.  IF THEY HAVE, THIS ERROR WILL RESULT IF THE PN IS BEING TRANSMITTED AFTER THE DATE SHOWN ON THE ABE RECORD FOR THE BROKER (OR SRES RECORD FOR AN ABI/ACE IMPORTER).");
			aBIErrorCollection["Q01"] = new MessageError(errorCode: "Q01", shortDesc: "INPUT RECORD TYPE MUST BE 'QT'", narrative: "POSITIONS 1&2 ON EACH INPUT RECORD WITHIN THE 'QN' APPLICATION MUST BE 'QT'");
			aBIErrorCollection["Q02"] = new MessageError(errorCode: "Q02", shortDesc: "'QT' PAYORS UNIT # INVALID", narrative: "INPUT RECORD HAS EITHER SPACES, ALL ZEROS OR NON NUMERIC DATA IN POSITIONS '3' THROUGH '8'.");
			aBIErrorCollection["Q03"] = new MessageError(errorCode: "Q03", shortDesc: "'QT' FILER INVALID", narrative: "QT INPUT RECORD HAS SPACES OR ALL ZEROS IN POS 11-13.  FOR PERIODIC DAILY STMT ACH DEBIT/SUMMARY PRESENTATION TRANSMISSIONS (PN), ON STATEMENT TYPES 6, 7, OR 8 THE ERROR MESSAGE MEANS THE PT INPUT RECORD HAS SPACES OR ALL ZEROS IN POS 11-13.");
			aBIErrorCollection["Q04"] = new MessageError(errorCode: "Q04", shortDesc: "'QT' STATEMENT NUMBER INVALID", narrative: "'QT' STATEMENT NUMBER HAS SPACES, ALL ZEROS, OR OTHER NON-ALPHANUMERIC CHARACTERS IN POSITIONS 14-24. UNDER CURRENT PROGRAMMING, POSITION 14 MUST BE ZERO-FILLED. WHEN CUSTOMS BILLS ARE AVAILABLE FOR PAYMENT THROUGH ACH, POSITION 14 WILL BE CHANGED TO ACCEPT OTHER NUMBERS.");
			aBIErrorCollection["Q05"] = new MessageError(errorCode: "Q05", shortDesc: "'QT' AMOUNT PAID INVALID", narrative: "THE 'QT' RECORD HAS SPACES, OR OTHER NON-NUMERIC DATA IN THE PAYMENT AMOUNT FIELD POSITIONS 25-34. ZERO DOLLARS IS A VALID AMOUNT THAT MAY BE PAID VIA ACH. (THE TRANSMITTING OF ZERO DOLLARS IS AN INDICATOR BY THE FILER THAT THE STATEMENT IS CORRECT IN THAT ALL ENTRIES HAVE NO MONEY DUE. THE TRANSMISSION IS NECESSARY, HOWEVER, IN ORDER TO 'PROCESS/PAY' THE STATEMENT AND ALLOW THE GENERATION OF THE FINAL STATEMENT).");
			aBIErrorCollection["Q06"] = new MessageError(errorCode: "Q06", shortDesc: "STATEMENT NOT ON FILE", narrative: "EITHER THE STATEMENT NUMBER GIVEN IN POSITIONS 15 THROUGH 24 OF THE QT RECORD CANNOT BE FOUND ON THE DSA FILE OR THE STATEMENT NUMBER WAS NOT RIGHT JUSTIFIED WITH A ZERO IN POSITION 14. WHEN CUSTOMS BILLS ARE AVAILABLE FOR PAYMENT THROUGH ACH, POSITION 14 WILL BE CHANGED TO ACCEPT OTHER NUMBERS. THE MOST COMMON REASON FOR THIS MESSAGE IS THAT ALL ENTRIES ORIGINALLY LISTED ON THE STATEMENT HAVE BEEN DELETED, EITHER BY THE FILER OR BY CUSTOMS. ONCE ALL ENTRIES ARE REMOVED FROM THE STATEMENT, THE STATEMENT NUMBER DROPS OUT OF THE SYSTEM AND CANNOT BE USED IN AN ACH PAYMENT TRANSACTION.  NOTE: IF THE STATEMENT NUMBER REJECTED CONTAINS AN ALPHA CHARACTER, IT MUST BE TRANSMITTED IN UPPER CASE. IF NOT, THIS ERROR WILL OCCUR.");
			aBIErrorCollection["Q07"] = new MessageError(errorCode: "Q07", shortDesc: "STATEMENT FILER NOT = 'QT' FILER", narrative: "FILER ON DSA STATEMENT NOT EQUAL TO FILER GIVEN ON THE 'QT' RECORD. IF THE FILER CODE IS OMITTED ENTIRELY FROM POS 11-13 IN THE QT RECORD, ERROR MESSAGE Q03 WILL BE GENERATED. ONLY IF THE FILER CODE IN THE QT RECORD IS NOT AN EXACT MATCH TO THAT ON THE DSAL FILE FOR THE STATEMENT NUMBER IN THE TRANSACTION WILL THIS ERROR MESSAGE BE GENERATED.");
			aBIErrorCollection["Q08"] = new MessageError(errorCode: "Q08", shortDesc: "'QT' AMT PAID NOT = STATEMENT AMT", narrative: "THE 'PAYMENT AMOUNT' SUBMITTED ON THE QT RECORD (POS 25-34) DOES NOT EQUAL THE 'AMT DUE' COLUMN ON THE DSAL FILE FOR THE STATEMENT NUMBER TRANSMITTED. IN MOST CASES, THIS RESULTS WHEN THE FILER ATTEMPTS TO PAY A STATEMENT WITH AN AMOUNT THAT IS LOWER THAN THE ACTUAL AMOUNT BECAUSE THE FILER ASSUMED THAT HIS REMOVAL OF ONE OR MORE ENTRIES FROM THE STATEMENT WAS SUCCESSFULLY TRANSMITTED TO ABI VIA APPLICATION HP (STATEMENT ADD/DELETE). IF THE ACH PAYMENT REJECTS, THE FILER SHOULD RETRANSMIT THE HP FOR THE ENTRY(S) TO BE REMOVED AND ONLY WHEN A SUCCESSFUL ACKNOWLEDGEMENT IS RECEIVED FROM ABI SHOULD THE ACH PAYMENT BE TRANSMITTED.  NOTE: THIS ERROR WILL ALSO GENERATE IF THE FILER ATTEMPTS TO TRANSMIT AN AMOUNT THAT IS GREATER THAN THE ACTUAL STATEMENT AMOUNT REFLECTED IN DSAL.");
			aBIErrorCollection["Q11"] = new MessageError(errorCode: "Q11", shortDesc: "PAYMENT ACCEPTED", narrative: "THE 'QT' RECORD HAS BEEN ACCEPTED ERROR FREE. THE STATEMENT WILL BE MARKED AS 'PAID', POSTINGS TO THE INDIVIDUAL ENTRIES WILL OCCUR, A FINAL STATEMENT WILL BE GENERATED, AND AN ELECTRONIC ACH DEBIT WILL OCCUR TO THE PAYOR'S BANK ACCOUNT DENOTED BY THE 'QT' TRANSACTION PAYOR'S UNIT NUMBER.");
			aBIErrorCollection["Q16"] = new MessageError(errorCode: "Q16", shortDesc: "QT UNIT # NOT FOR 'QT' FILER", narrative: "IF THE STATEMENT IS A BROKER STATEMENT, THE PAYER'S UNIT NUMBER (REC QT, POS 3-8) IS NOT IDENTIFIED ON THE DSI FILE AS BEING ASSIGNED TO THE FILER CITED IN THE QT REC, POS 11-13.");
			aBIErrorCollection["Q17"] = new MessageError(errorCode: "Q17", shortDesc: "DSI FILE MISSING STTMENT IMPORTER", narrative: "THE STATEMENT NUMBER IN THE 'QT' RECORD IS IDENTIFIED AS AN IMPORTER STATEMENT WITH A SPECIFIC IMPORTER NUMBER; THE PAYOR UNIT NUMBER PROVIDED IN THE 'QT' RECORD IS NOT ASSIGNED TO THAT IMPORTER ON THE DSI FILE.");
			aBIErrorCollection["Q18"] = new MessageError(errorCode: "Q18", shortDesc: "PAYOR UNIT # NOT ON FILE", narrative: "PAYOR UNIT # NOT DEFINED ON 'DSI' DATA-BASE - CHECK USING FUNCTION 'DSIL'");
			aBIErrorCollection["Q09"] = new MessageError(errorCode: "Q09", shortDesc: "STATEMENT NOT ELIGIBLE FOR ACH", narrative: "IF THE ABE RECORD FOR THE FILER OF THE QN RECORD IS NOT SET TO 'Y' FOR THE ACH ELEMENT, THIS MESSAGE WILL RESULT. THE ABE RECORD FOR THE FILER SHOULD BE CORRECTED. NOTE: EVEN AFTER THE CORRECTION HAS BEEN DONE, THE REJECTED QN CANNOT BE REPROCESSED FOR PAYMENT VIA ACH UNLESS POSITION 563 ON THE DSA FILE IS RESET TO A '1' OR THE FILER CAN PAY BY CHECK OR THE FILER CAN MOVE THE ENTRIES TO A NEW (FUTURE) PAYMENT DUE DATE.  NOTE: IF THE STATEMENT IS ELIGIBLE FOR CHECK PAYMENT AND AN ONLINE DSAA WAS PERFORMED AND EOD WAS NOT RUN, THEN THIS ERROR MESSAGE WILL ALSO RESULT.  NOTE: (EFT-IND) IS POS 563 ON THE DSA FILE.");
			aBIErrorCollection["Q19"] = new MessageError(errorCode: "Q19", shortDesc: "'QT' PAYMENT TYPE INVALID", narrative: "THE PAYMENT TYPE (REC QT, POS 9-10) MUST BE '01' AT THE CURRENT TIME. EVENTUALLY, OTHER CUSTOMS OBLIGATIONS SUCH AS BILLS WILL BE ELIGIBLE FOR ACH PAYMENT USING OTHER PAYMENT TYPE INDICATORS. UNTIL THAT ENHANCEMENT IS ANNOUNCED, ONLY PAYMENT TYPE 01 WILL BE ACCEPTED BY ABI (WHICH MEANS THAT SPACES '00' OR A '1' WILL ALSO BE REJECTED).");
			aBIErrorCollection["Q20"] = new MessageError(errorCode: "Q20", shortDesc: "'QT' REC PREVIOUSLY ACCEPTED", narrative: "IF A PREVIOUS TRANSMISSION WAS SUCCESSFUL IN SENDING AN ACH AUTHORIZATION FOR THE STATEMENT NUMBER IN THE INSTANT TRANSACTION, THIS MESSAGE WILL RESULT. THE PREVIOUS TRANSMISSION DID NOT HAVE TO OCCUR ON THE SAME DAY AS THE TRANSMISSION BEING REJECTED. CHECK THE FILER'S ABBQ FOR A PREVIOUS SUCCESSFUL TRANSMISSION OR CHECK DSAL/DSLL TO CONFIRM THAT THE STATEMENT HAS ALREADY BEEN PAID.");
			aBIErrorCollection["Q23"] = new MessageError(errorCode: "Q23", shortDesc: "DUPLICATE 'QT' PAYMENT RECORD", narrative: "THE STATEMENT NUMBER BEING TRANSMITTED BY THE FILER HAS BEEN PREVIOUSLY TRANSMITTED AND ACCEPTED. STATEMENTS MAY NOT BE PAID TWICE.");
			aBIErrorCollection["Q41"] = new MessageError(errorCode: "Q41", shortDesc: "STMT PAID, TO DELETE, NEGATE COLL", narrative: "THIS MESSAGE OCCURS WHEN AN ABI FILER ATTEMPTS TO REMOVE AN ENTRY FROM STATEMENT (APPLICATION HP) AND THE STATEMENT HAS ALREADY HAD AN ACH AUTHORIZATION TRANSMITTED TO ABI (APPLICATION QN). THE SOLUTION IS FOR THE FILER TO CONTACT A CLIENT REP WHO CAN PERFORM FUNCTION 'DSGD' IF THE PAYMENT AUTHORIZATION WAS TRANSMITTED ON THE SAME DAY AS THE REQUEST IS MADE.");
			aBIErrorCollection["Q43"] = new MessageError(errorCode: "Q43", shortDesc: "STATEMENT ALREADY PD VIA ACH", narrative: "THIS MESSAGE WILL RESULT IF A FILER ATTEMPTS TO REMOVE AN ENTRY FROM A STATEMENT FOR WHICH THE ACH PAYMENT AUTHORIZATION TRANSACTION (APPLICATION QN) HAS ALREADY BEEN RECORDED IN ACS. FILERS WILL OFTEN SEND APPLICATION HP (STATEMENT ADD/DELETE) AT OR ABOUT THE SAME TIME THAT THEY TRANSMIT THE ACH PAYMENT. IF BOTH ARE RECEIVED SIMULTANEOUSLY, IT IS VERY LIKELY THAT THE ACH TRANSACTION WILL BE PROCESSED PRIOR TO THE STATEMENT ADD/DELETE. IN SUCH A CASE, THIS ERROR MESSAGE WILL BE THE RESULT.");
