			aBIErrorCollection["QO2"] = new MessageError(errorCode: "QO2", shortDesc: "TRANSMIT DATE INVALID", narrative: "THE TRANSMISSION DATE ON THE 'QR' RECORD IS INVALID FOR ONE OF THE FOLLOWING REASONS:  1. THE DATE FORMAT IS INVALID 2. THE DATE IS GREATER THAN THE CURRENT DATE 3. THE EXPECTED FORMAT IS MMDDYY");
			aBIErrorCollection["QO3"] = new MessageError(errorCode: "QO3", shortDesc: "INVALID 'QR' RECORD", narrative: "PER B-Y SET, ONLY ONE 'QR' RECORD CAN BE PROCESSED BECAUSE THE PROCESSING SITE IN THE 'B' RECORD IS USED FOR SEARCH CRITERIA.");
			aBIErrorCollection["QO4"] = new MessageError(errorCode: "QO4", shortDesc: "NO REROUTES REQUESTED", narrative: "'QR' RECORD DID NOT CONTAIN A REROUTE REQUEST. EXPECT ONE OF THREE INDICATORS = Y.");
			aBIErrorCollection["QO5"] = new MessageError(errorCode: "QO5", shortDesc: "INVALID SCOPE INDICATOR", narrative: "THE SCOPE INDICATOR SHOULD BE 'A' OR SPACES. IF 'A', THEN ALL A-Z SETS FOR THE 'A' RECORD RECEIVER SITE ARE REROUTED. IF SPACES, THEN A-Z ARE REROUTED IF BOTH THE 'A' RECORD RECEIVER SITE AND THE 'B' RECORD PROCESSING SITE ARE MATCHED.");
			aBIErrorCollection["QO6"] = new MessageError(errorCode: "QO6", shortDesc: "INVALID REQUEST-MUST BE 'Y OR N'", narrative: "INDICATOR SHOULD BE 'Y' OR 'N'. THIS ERROR MESSAGE APPLIES TO SEVERAL REQUEST INDICATORS ON THE 'QR' RECORD; PRELIMINARY STATEMENT IND, FINAL STATEMENT IND AND ACH PAYMENT IND.  THE FIELDS IN THE QR INPUT RECORD THAT MUST BE 'Y' OR 'N' ARE IN POSITIONS 34, 35, 36,AND 37. POSITION 37 BECAME MANDATORY ON FEB 16, 2005 AND PERMITS THE FILER TO REQUEST A REROUTE OF A PERIODIC MONTHLY STATEMENT PAYMENT AUTHORIZATION.");
