			aBIErrorCollection["SS9"] = new MessageError(errorCode: "SS9", shortDesc: "INV VALUE 9819-21/99990084/99156X", narrative: "AGOA/CBTPA TEXTILE CLAIMS FILED UNDER TARIFF NUMBERS 9819/9820 REQUIRE THE TOTAL VALUE AMOUNTS TO BE REPORTED UNDER THE NON 9819/9820 TARIFF NUMBERS (70 RECORD, POSITIONS 69 - 78). REFER TO ADMINISTRATIVE MESSAGES 01-0388 AND 01-0390. THE ABOVE VALUE PROCEDURE ALSO APPLIES TO ATPDEA 9821 TARIFF NUMBERS. REFER TO ADMIN MESSAGE 03-0793. THE ABOVE ERROR MESSAGE ALSO APPLIES TO TARIFF 99990084 (ISI PROVISION OF THE SINGAPORE FTA). REFER TO ADMIN MESSAGE 04-0859.  CAFTA TPL TARIFF NUMBERS 991561XX AND 991562XX REQUIRE THE TOTAL VALUE TO BE INDICATED ON THE ALTERNATE TARIFF NUMBER (NON CHAPTER 98) REFER TO ADMIN MESSAGE 06-0315.");
			aBIErrorCollection["SSF"] = new MessageError(errorCode: "SSF", shortDesc: "SPI INVALID FOR CAFTA HTS", narrative: "NO SPI INDICATORS SHOULD BE ENTERED FOR A SUMMARY LINE WHEN CAFTA TPL TARIFF NUMBERS 991561XX/991562XX OR 98220510 ARE USED. REFER TO ADMIN MESSAGE 06-0315.");
			aBIErrorCollection["ST1"] = new MessageError(errorCode: "ST1", shortDesc: "PREVIOUS SET IS INCOMPLETE", narrative: "THE PROCESSING OF A SET WAS IN PROGRESS WHEN THIS LINE INTERRUPTED THE SET. IN ABI TERMS, THIS MEANS THAT AN 'X' LINE WAS DETECTED ON A PREVIOUS LINE IN THE SUMMARY INPUT (APPLICATION EI), BUT NO 'V' LINES OCCURRED PRIOR TO THE REPORTING OF THE LINE BEING REJECTED. FOR EXAMPLE, IF LINE 4 HAS AN 'X', LINES 5 AND 6, AT A MINIMUM, MUST HAVE 'V' INDICATORS. IF LINE 5 DOES NOT SHOW THE 'V', IT WILL BE SHOWN IN THE OUTPUT TO THE FILER WITH THIS ERROR MESSAGE.");
			aBIErrorCollection["ST2"] = new MessageError(errorCode: "ST2", shortDesc: "NO PEVIOUS SET HEADER PROCESSED", narrative: "A SET ITEM (SECONDARY SPI OF 'V') WAS ENTERED WITHOUT A SET HEADER (SECONDARY SPI OF 'X') LINE IMMEDIATELY PRECEEDING THIS IINE.");
