			aBIErrorCollection["SUC"] = new MessageError(errorCode: "SUC", shortDesc: "WARNING - SURETY NOW CANCELED", narrative: "FOR RECONCILIATION, THE SURETY ORIGINALLY GIVEN ON THE IMPORT ENTRIES IS NOW CANCELED.");
