			aBIErrorCollection["VHO"] = new MessageError(errorCode: "VHO", shortDesc: "DT HS7: CONTRACT/STMNT CERT REQ'D", narrative: "IF BOXES 2B, 06, 07, 08, OR 09 ARE INDICATED IN THE DT01 RECORD, POSITIONS 8-9, POSITION 36 OF THE DT01 RECORD MUST REFLECT A 'Y'. IF ANY OTHER BOX NUMBERS ARE INDICATED, THIS FIELD MUST BE BLANK.");
			aBIErrorCollection["VHP"] = new MessageError(errorCode: "VHP", shortDesc: "DT HS7: INVAL CONTRACT/STMNT CERT", narrative: "ONLY A 'Y' IS PERMITTED IN REC DT01, POS 36 TO INDICATE THE PRESENCE OF THE IMPORTERS SUBSTANTIATING STATEMENT/CONTRACT/OR MANUFACTURER'S CONFIRMATION LETTER. ANY OTHER CHARACTER WILL RESULT IN THIS ERROR MESSAGE.");
