			aBIErrorCollection["VAP"] = new MessageError(errorCode: "VAP", shortDesc: "FIRMS REQUIRED FOR CERTIFICATION", narrative: "A FACILITIES INFORMATION AND RESOURCES MANAGEMENT SYSTEM (FIRMS) CODE IS REQUIRED FOR ANY ENTRY SUMMARY INPUT THAT REQUESTS CARGO CERTIFICATION IN THE 3O REC, POS 38. THE FIRMS CODE IS TRANSMITTED IN THE 20 REC, POS 72-75. IF THE FIRMS CODE IS OMITTED, THIS ERROR MESSAGE WILL BE GENERATED.");
			aBIErrorCollection["VAQ"] = new MessageError(errorCode: "VAQ", shortDesc: "COMM. INVOICE DATA NOT ON FILE", narrative: "FILERS WHO PARTICIPATE IN THE ELECTRONIC INVOICE PROGRAM (EIP) MUST TRANSMIT COMMERCIAL INVOICE DATA TO ABI PRIOR TO TRANSMITTING THEIR SUMMARY DATA IF THE SUMMARY CONTAINS AN 'E' IN POS 56 OF THE 10 RECORD. IF THE FILER IS PARTICIPATING IN THE INVOICE BY REQUEST PROGRAM, THEN IT IS PERMISSABLE TO TRANSMIT THE 42 RECORD WITH THE INVOICE NUMBER AND THE 43 RECORD WITH THE 'INVREQ' DATA WITHOUT FIRST TRANSMITTING THE COMMERCIAL INVOICE. HOWEVER, UNLESS ONE OF THE TWO CONDITIONS ABOVE IS MET, A TRANSMISSION OF THE SUMMARY AS AN ELECTRONIC SUMMARY (EIP) WILL BE REJECTED WITH THIS ERROR MESSAGE.  **NOTE** IF THE FILER USES MORE THAN ONE 42 RECORD PER 40 RECORD, AND 'INVREQ' PERTAINS TO THE 42 RECORD, EACH 42 RECORD MUST BE ACCOMPANIED BY A 43 RECORD. IF THIS PAIRING IS NOT FOLLOWED, THIS ERROR MESSAGE WILL RESULT.");
			aBIErrorCollection["VAR"] = new MessageError(errorCode: "VAR", shortDesc: "ENT-SUM ACCEPTD-PAPER NOW REQ'D", narrative: "THIS IS AN INFORMATIONAL MESSAGE THAT OCCURS IN ABI ENTRY SUMMARY PROCESSING WHEN A PREVIOUS PAPERLESS ENTRY SUMMARY HAS CHANGED TO A PAPER REQUIRED STATUS. THIS MESSAGE IS AN OLD ONE AND HAS BEEN REPLACED BY 'ACCEPTED, RECORDS REQUIRED'.");
			aBIErrorCollection["VAS"] = new MessageError(errorCode: "VAS", shortDesc: "TEAM NOT EQUAL TO ACS TEAM", narrative: "THIS MESSAGE IS NOT A REJECTION, BUT MERELY A WARNING. THE IMPORT SPECIALIST TEAM IS AN OPTIONAL RECORD IN THE SUMMARY INPUT TRANSACTION (EI). IT IS SENT IN THE 30 REC, POS 77-79. IF THE FILER TRANSMITS THIS ELEMENT AND IT DOES NOT AGREE WITH THE IMPORT SPECIALIST TEAM ASSIGNMENT DESIGNATED BY ACS, THIS MESSAGE WILL RESULT. IN SOME CASES, THE FILER MAY NOT KNOW WHICH TEAM WILL BE ASSIGNED BY ACS, ESPECIALLY IF THE ENTRY CONTAINS SEVERAL LINES. ACS WILL RESPOND TO THE INPUT WITH THIS WARNING MESSAGE AND WITH THE ACTUAL ASSIGNED TEAM NUMBER IN THE E0 OR E90 RECORD OUTPUT. THE FILER HAS THE OPTION OF RETRANSMITTING THE SUMMARY WITH THE CORRECT TEAM NUMBER (RARELY DONE) OR OF PRINTING THE SUMMARY DOCUMENTS WITH THE CORRECT TEAM NUMBER SHOWN.");
			aBIErrorCollection["VAT"] = new MessageError(errorCode: "VAT", shortDesc: "PAPERLESS/PAID MUST CONTAIN 'E'", narrative: "THIS MESSAGE OCCURS IN THE ELECTRONIC INVOICE ENVIRONMENT WHEN A FILER RESENDS AN AII ENTRY SUMMARY, AFTER IT HAS BEEN PAID THEN SUBSEQUENTLY REJECTED BY CUSTOMS, WITHOUT SENDING AN 'E' IN POSITION 56 OF THE ABI 10 RECORD.");
			aBIErrorCollection["VAU"] = new MessageError(errorCode: "VAU", shortDesc: "ULT CONSIGNEE IN ENTRY HEADER", narrative: "WHEN AN ULTIMATE CONSIGNEE NUMBER IS TRANSMITTED IN THE HI APPLICATION, REC H2, POS 11-22 (INDICATING ONE ULTIMATE CONSIGNEE FOR THE SHIPMENT), POS 33-44 IN REC H5 MUST BE SPACE FILLED.");
			aBIErrorCollection["VAV"] = new MessageError(errorCode: "VAV", shortDesc: "ENTRY CANNOT BE BORDER RELEASE", narrative: "THIS ERROR OCCURS IF A FILER TRANSMITS A BORDER CARGO RELESE TRANSACTION (APPLICATION HN) BUT THE COUNTRY OF ORIGIN IN THE 02 RECORD IS NOT MX OR CA.");
			aBIErrorCollection["VBS"] = new MessageError(errorCode: "VBS", shortDesc: "INV CLARIFICATION CODE FOR BOX", narrative: "THIS MESSAGE WILL BE GENERATED IF A CLARIFICATION CODE (REC DT01, POS 37) OTHER THAN 'V' IS USED FOR HS7 BOX NUMBERS 03, 06, OR 12 (REC DT01, POS 8-9). ALSO BOX 2B WILL CAUSE THIS REJECT IF THE CODE IS NOT 'V'");
			aBIErrorCollection["VAW"] = new MessageError(errorCode: "VAW", shortDesc: "PRELIMINARY STMT ALREADY PRODUCED", narrative: "THIS ERROR MESSAGE OCCURS WHEN A FILER TRANSMITS AN ENTRY SUMMARY WITH A PAYMENT DUE DATE THAT IS THE SAME DATE AS THE CALENDAR DATE OF THE STATEMENT. FOR EXAMPLE, IF THE FILER SENDS, ON DECEMBER 28, AN ENTRY SUMMARY WITH A PAYMENT DUE OF DECEMBER 28, THIS MESSSAGE WILL RESULT, BECAUSE ALL THE PRELIMINARY STATEMENTS FOR DECEMBER 28 WILL HAVE BEEN PRODUCED PRIOR TO THE FILER TRANSMITTING HIS DATA. PAYMENT DUE DATES MUST ALWAYS BE AT LEAST ONE CALENDAR DAY IN THE FUTURE WHEN COMPARED TO THE TRANSMISSION DATE.  THIS MESSAGE ALSO OCCURS IN THE NAFTA DUTY DEFERRAL MODULE. IT HAS OCCURRED WHEN A FILER SENT A PAYMENT INDICATOR OF '2' '3' OR '5' IN POSITION 59 OF THE D30 RECORD AND DID NOT SEND AT LEAST ONE D20 RECORD.  THIS MESSAGE ALSO OCCURS FOR RECONCILIATION ('RA' TRANSACTION) IF THE FILER TRANSMITS A RECON SUMMARY WITH A PAYMENT DUE DATE AFTER STATEMENT GENERATION (SEE FIRST PARAGRAPH ABOVE). UPDATE THIS MESSAGE ALSO OCCURS WHEN ZEROES ARE TRANSMITTED IN POS 19-24 OF THE HP TRANSACTION.");
			aBIErrorCollection["VAX"] = new MessageError(errorCode: "VAX", shortDesc: "PAY BASIS INVALID-CUSTOMS STATUS", narrative: "ENTRY SUMMARIES THAT ARE FILED WITH CUSTOMS AND PAID BY CHECK ARE CONSIDERED TO BE 'SINGLE PAY' ENTRIES. THESE SUMMARIES, IF REJECTED BY CUSTOMS FOR ABI RETRANSMISSION BY THE FILER, CANNOT BE SCHEDULED FOR STATEMENT PROCESSING AT A FUTURE DATE. IF THE FILER TRANSMITS A PAYMENT TYPE AND PAYMENT DUE DATE ON SUCH AN ENTRY, THIS ERROR MESSAGE WILL BE GENERATED.  ALSO, IF AN ENTRY IS ACCEPTED BY CUSTOMS WITHOUT AN ABI SUMMARY BEING PREVIOUSLY TRANSMITTED, THE REJECTION OF THE SUMMARY TO THE FILER FOR ABI TRANSMISSION WILL REQUIRE PAYMENT TYPE 1 (SINGLE PAY).");
