			aBIErrorCollection["VC9"] = new MessageError(errorCode: "VC9", shortDesc: "MPF SURCHARGE NOT REQUIRED", narrative: "THIS MESSAGE IS GENERATED IN RESPONSE TO AN ENTRY SUMMARY INPUT TRANSACTION (APPLICATION EI). FILERS WHO HAVE ABE RECORDS ANYWHERE IN THE UNITED STATES THAT INDICATE OPERATIONAL STATUS FOR CARGO RELEASE OR BORDER CARGO RELEASE ARE NOT REQUIRED TO DEPOSIT THE MANUAL MPF SURCHARGE. IF THE FILER TRANSMITS CLASS CODE 500 WITH $2.00 ON ANY ENTRY AFTER OBTAINING OPERATIONAL CARGO STATUS, THIS ERROR MESSAGE WILL RESULT.  NOTE: THIS MESSAGE WILL ALSO RESULT IF THE FILER TRANSMITS THE SURCHARGE ON AN ENTRY THAT CLAIMS NAFTA, EVEN IF THE FILER IS NOT YET OPERATIONAL FOR ABI IN ANY U.S. PORT.");
