			aBIErrorCollection["VEN"] = new MessageError(errorCode: "VEN", shortDesc: "FDA LINE ALREADY REJECTED", narrative: "THIS ERROR MESSAGE HAPPENS ONLY BETWEEN CUSTOMS ACS AND FDA'S SYSTEM. FDA SENDS INFORMATION VIA CUSTOMS TO THE FILER BY THE 'LP' TRANSACTION. THIS ERROR OCCURS WHEN FDA HAS SENT AN 'LP' INDICATING THAT THE ENTRY SHOULD BE REJECTED FOR FDA PURPOSES AND THE LINE IN QUESTION IS ALREADY IN FDA REJECT STATUS.");
