			aBIErrorCollection["VER"] = new MessageError(errorCode: "VER", shortDesc: "***ISIS TABLE OVERFLOW - ERROR***", narrative: "THIS MESSAGE IS INTERNAL TO FDA'S ISIS PROCESSING SYSTEM. IT WILL OCCUR IN SEVERAL APPLICATIONS UNDER FILER CODE 9900/I99.");
