			aBIErrorCollection["VG1"] = new MessageError(errorCode: "VG1", shortDesc: "REQUEST SENT TO FDA, PROC PENDING", narrative: "THIS IS NOT AN ERROR MESSAGE BUT AN INFORMATIONAL MESSAGE. IT OCCURS WHEN A FILER HAS SENT A REQUEST FOR AN FDA ESTABLISHMENT IDENTIFIED (FEI) NUMBER THROUGH ACS TO FDA. THIS INTERIM MESSAGE IS TELLING THE FILER THAT THEIR REQUEST PASSED ABI EDITS AND HAS BEEN SENT TO THE FDA SYSTEM. FDA WILL PROCESS THE REQUEST AND SEND BACK THE FEI NUMBER IN A SEPARATE ABI TRANSACTION");
