			aBIErrorCollection["VG6"] = new MessageError(errorCode: "VG6", shortDesc: "INVALID ACTION CODE", narrative: "THIS ERROR MESSAGE RESULTS WHEN A FILER ATTEMPTS TO QUERY AN FDA ESTABLISHMENT IDENTIFIER NUMBER (FEI) OR IS TRIES TO OBTAIN ONE AND IS USES AN INVALID ACTION CODE IN REC FD10, POS 5 OR IN REC FD20, POS 5 OF THE PP TRANSACTION. IN REC FD10, POS 5, ONLY A 'Q' (QUERY) IS ALLOWED. IN REC FD20, POS 5, ONLY A 'Q' (QUERY) OR 'A' (ADD) IS ALLOWED.");
			aBIErrorCollection["VGA"] = new MessageError(errorCode: "VGA", shortDesc: "FD701: INV LINE#/SEQ", narrative: "THIS ERROR MESSAGE RESULTS WHEN A FILER SENDS AN FDA CORRECTION (CP TRANS- ACTION) TO RESPOND TO AN FDA DT REJECT MESSAGE AND THE CUSTOMS LINES THAT THEY ARE SENDING IN THE FDA CORRECTION DO NOT MATCH THE EXACT SEQUENCE OF LINES IN THE SSA RECORD. WHEN A CORRECTION IS DONE, THE FILER MUST SEND THE CUSTOMS LINES (WITH THE CORRESPONDING FDA DATA OR DISCLAIM AS APPLICABLE) IN THE EXACT ORDER AS IT APPEARS ON THE SSBL (LINE ITEM) SCREEN. THE FILER MUST ALSO SEND ALL CUSTOMS LINES WHETHER OR NOT THEY ARE FDA REGULATED. CHECK THE ORDER OF THE TARIFF NUMBERS IN THE CP SEND AGAINST THE SSBL SCREEN. THEY MUST MATCH EXACTLY. THIS MESSAGE ALSO RESULTS WHEN A FILER ATTEMPS TO START A FDA LINE NUMBER WITHIN A CUSTOMS LINE WITH A NUMBER OTHER THAN 001. THE MOST COMMON OCCURANCE IS WHEN CUSTOMS LINE 001 IS SENT AND, FOR EXAMPLE FDA LINES 001 AND 002 ARE SENT WITH IT. THEN THE FILER SENDS CUSTOMS LINE 002 AND STARTS THE FDA LINE NUMBERING WITH 003. THIS REJECT WILL ALSO OCCUR IF THE FILER SENDS BOTH AN FD0 (DISCLAIM) AND FDA DATA FOR THE SAME CUSTOMS LINE ON AN ENTRY SUMMARY INPUT TRANSACTION.");
			aBIErrorCollection["VGD"] = new MessageError(errorCode: "VGD", shortDesc: "FD 701: INV CNTRY OF PRODUCTION", narrative: "THE FDA COUNTRY OF PRODUCTION IS A REQUIRED DATA ELEMENT IN THE FDA INTER- FACE. THE COUNTRY MUST BE A VALID COUNTRY CODE RESIDENT IN THE RFJ FILE (QUERY=RFJL). THIS IS THE ONLY EDIT PERFORMED SO A COUNTRY CODE THAT IS VALID, BUT RESTRICTED FOR ABI PURPOSES, WILL GO THROUGH THE FDA PORTION.");
			aBIErrorCollection["VGE"] = new MessageError(errorCode: "VGE", shortDesc: "FD 701: AFFRM/CMPLNCE NOT ON FILE", narrative: "THE FDA AFFIRMATION OF COMPLIANCE (REC FD01, POS 20-22) MAY APPLY TO CERTAIN FDA LINES. THE FDA AFFIRMATIONS OF COMPLIANCE ARE IN THE ACS FDC FILE (QUERY - FDCL). IF USED, THE CODE MUST RESIDE IN THIS FILE OR THE ABOVE MESSAGE WILL RESULT.  NOTE: WITH THE ADVENT OF BTA IN DEC 2002, MANY MORE AFFIRMATION OF COMPLIANCE CODES ARE BEING TRANSMITTED TO SATISFY PRIOR NOTICE REQUIREMENTS. THESE ARE TRANSMITTED IN THE FD05 RECORD. IF THE A/C IN ONE OF THESE RECORDS IS NOT FOUND ON FDCL, THIS MESSAGE WILL ALSO APPLY.");
			aBIErrorCollection["VGF"] = new MessageError(errorCode: "VGF", shortDesc: "AFFRM/CMPLNCE QUALFYR IS BLANK", narrative: "THE FDA AFFIRMATION OF COMPLIANCE MAY APPLY TO CERTAIN FDA LINES. THE FDA AFFIRMATIONS OF COMPLIANCE ARE IN THE ACS FDC FILE (QUERY = FDCL). SOME OF THE AFFIRMATIONS OF COMPLIANCE ARE SHOWN IN THE FILE AS QUALIFIER - 'Y' (YES). THIS QUALIFIER CAN TAKE MANY FORMS. IT MAY BE A FORM, STATEMENT OR LICENSE NUMBER. IF THE FILER USES AN FDA AFFIRMATION OF COMPLIANCE AND IT HAS A 'Y' FOR QUALIFIER REQUIRED THEN THE QUALIFIER MUST BE SENT IN REC FD01, POS 23-47.");
			aBIErrorCollection["VGG"] = new MessageError(errorCode: "VGG", shortDesc: "FD 701: FDA MFR NOT ON FILE", narrative: "THIS ERROR MESSAGE IS A REJECTION IN THE FDA INTERFACE. THE MANUFACTURER IDENTIFICATION NUMBER (MID, REC FD01, POS 48-62, MUST BE ON FILE BEFORE THE FDA ENTRY WILL PROCESS. THE FILER MUST ADD THE MANUFACTURER TO THE DATABASE VIA ABI AND RESEND THE ENTRY.  MAKE SURE YOU CHECK THE FD01 RECORD STARTING IN POSITION 48. SOMETIMES THE FILER WILL SEND SOME EXTRANEOUS DATA IN THERE OR LEAVE THE MFR BLANK YET SEND THE MID FOR THE SHIPPER. WHEN THE ERROR MESSAGE IS GENERATED ABI RETURNS BOTH THE FDA MFR, EVEN IF BLANK, AND THE SHIPPER WHICH MAY LEAD TO CONFUSION WHEN THE SHIPPER IS ON FILE.");
			aBIErrorCollection["VGH"] = new MessageError(errorCode: "VGH", shortDesc: "FD 701: NO FDA MFR NAME/ADDR", narrative: "DATA SUBMITTED AS PART OF THE FDA INTERFACE MUST INCLUDE AN MID THAT REPRESENTS THE ACTUAL MANUFACTURER. THIS MID WILL BE COMPARED TO THOSE LISTED ON THE SSML FILE. IF THE MID IN QUESTION IS LISTED ON THIS FILE IN 'PENDING' STATUS, THIS MESSAGE WILL RESULT. THE SSML FILE NO LONGER ACCEPTS MID'S WITHOUT NAMES AND ADDRESSES, SO THE PENDING FILE SHOULD NOT INCREASE IN SIZE. THIS MESSAGE SHOULD NOT OCCUR IN NORMAL ABI INPUT TRANSACTIONS.");
			aBIErrorCollection["VGI"] = new MessageError(errorCode: "VGI", shortDesc: "FD 701: FDA SHPPR NOT ON FILE", narrative: "THIS ERROR MESSAGE IS A REJECTION IN THE FDA INTERFACE. THE FDA SHIPPER IDENTIFICATION NUMBER (MID, REC FD01, POS 63-77) MUST BE ON FILE FOR THE SHIPPER BEFORE THE FDA ENTRY WILL PROCESS. THE FILER MUST ADD THE SHIPPER IDENTIFICATION NUMBER TO THE DATABASE VIA ABI AND RESEND THE ENTRY.  THE ABOVE MESSAGE SHOULD BE INTERPRETED TO THE FILER AS REQUIRING THE MID TO BE ADDED TO THE CUSTOMS MANUFACTURER ID DATABASE VIA AN ABI INPUT (APPLICATION $I) OR THAT THE FILER SHOULD VERIFY THAT THEY HAVE TRANSMITTED THE CORRECT MID TO REPRESENT THE FDA SHIPPER (SIMILAR INSTRUCTIONS WILL APPLY TO ERROR MESSAGE VGG FOR THE FDA MANUFACTURER).");
			aBIErrorCollection["VGJ"] = new MessageError(errorCode: "VGJ", shortDesc: "FD 701: NO FDA SHPPR NAME/ADDR", narrative: "DATA SUBMITTED AS PART OF THE FDA INTERFACE MUST INCLUDE AN MID THAT REPRESENTS THE ACTUAL SHIPPER. THIS MID WILL BE COMPARED TO THOSE LISTED ON THE SSML FILE. IF THE MID IN QUESTION IS LISTED ON THIS FILE IN 'PENDING' STATUS, THIS MESSAGE WILL RESULT. THE SSML FILE NO LONGER ACCEPTS MID'S WITHOUT NAMES AND ADDRESSES, SO THE PENDING FILE SHOULD NOT INCREASE IN SIZE. THIS MESSAGE SHOULD NOT OCCUR IN NORMAL ABI INPUT TRANSACTIONS.");
			aBIErrorCollection["VGK"] = new MessageError(errorCode: "VGK", shortDesc: "FD 701: QTY 1 REQUIRED", narrative: "THIS ERROR MESSAGE RESULTS WHEN AN FDA INTERFACE ENTRY CONTAINS AN FDA QUANTITY OR QUANTITIES IN THE FD02 RECORD (THERE CAN BE UP TO SIX QUANTITIES IN AN FDA ENTRY) AND THE QUANTITY FOR THE QUANTITY 1 FIELD (REC FD02, POS 5-14) WAS LEFT BLANK. IF THERE IS ONE OR MORE QUANTITIES SENT, THE QUANTITY 1 FIELD MUST CONTAIN A QUANTITY.");
			aBIErrorCollection["VGL"] = new MessageError(errorCode: "VGL", shortDesc: "FD 701: UOM 1 REQUIRED", narrative: "THIS ERROR MESSAGE OCCURS WHEN A FILER TRANSMITS A QUANTITY IN POSITIONS 5-14 OF THE FD02 RECORD BUT DOES NOT TRANSMIT A UNIT OF MEASURE IN POSITIONS 15-18 OF THE FD02 RECORD. THIS WOULD ALSO APPLY TO SUBSEQUENT QUANTITIES IN THE FD02 RECORD.");
			aBIErrorCollection["VGM"] = new MessageError(errorCode: "VGM", shortDesc: "FD 701: QTY IND;PREV QTY=0'S", narrative: "UP TO SIX QUANTITIES CAN BE SENT IN THE FDA INTERFACE. IF ZEROS WERE TRANSMITTED IN A PRECEDING QUANTITY BLOCK AND A QUANTITY WAS TRANSMITTED IN THE INSTANT BLOCK, THIS ERROR MESSAGE RESULTS. FOR INSTANCE, IF ZEROS ARE TRANSMITTED IN THE UNIT 1 QUANTITY BLOCK OF REC FD02, POS 5-14 AND 0000000009 TRANSMITTED IN THE UNIT 2 QUANTITY BLOCK OF REC FD02, POS 19-28, THIS ERROR MESSAGE OCCURS.");
			aBIErrorCollection["VHH"] = new MessageError(errorCode: "VHH", shortDesc: "DT HS7: INVALID ISO CODE", narrative: "IF THE FILER TRANSMITS DOT INFORMATION FOR BOX 05, 06, OR 12, THE ISO CODE OF THE COUNTRY OF ORIGIN IS REQUIRED. THIS CODE MUST BE LISTED ON THE RFJL DATABASE. IF A CODE NOT FOUND ON THE RFJL FILE IS TRANSMITTED IN POSITIONS 30-31 OF THE DT01 RECORD, THIS ERROR MESSAGE WILL BE GENERATED.");
			aBIErrorCollection["VHI"] = new MessageError(errorCode: "VHI", shortDesc: "DT HS7: DOT BOND CODE REQUIRED", narrative: "IF BOX 03 IS USED (REC DT01, POS 8-9), THE ENTRY MUST BE BONDED FOR DOT. A BOND SURETY CODE MUST BE TRANSMITTED IN THE DT01 RECORD, POS 32-34. NO OTHER BOX NUMBER PERMITS THE USE OF THE BOND CODE.");
			aBIErrorCollection["VHJ"] = new MessageError(errorCode: "VHJ", shortDesc: "DT HS7: BOND (SURETY) NOT ON FILE", narrative: "IF BOX 03 IS USED (REC. DT01, POS 8-9,) THE DOT BOND MUST BE REPRESENTED BY A VALID SURETY CODE FROM THE BDAL FILE. ABI DOES NOT EDIT THE SURETY CODE IN THIS FIELD TO SEE IF IT MATCHES THE SURETY CODE IN THE 10 RECORD OF THE SUMMARY INPUT.");
			aBIErrorCollection["VHL"] = new MessageError(errorCode: "VHL", shortDesc: "DT HS7: APP LTR/ORD CERT REQ'D", narrative: "IF BOX 2B, 06, 07, OR 12 (REC DT01, POS 8-9), IS USED, THEN POSITION 35 OF THE DT01 RECORD MUST REFLECT A 'Y'. NO OTHER BOX NUMBER WILL BE ACCEPTED WITH THE 'Y' IN POS 35, HOWEVER.");
			aBIErrorCollection["VGN"] = new MessageError(errorCode: "VGN", shortDesc: "FD 701: UOM REQ IF QTY USED", narrative: "IF A QUANTITY IS SENT IN THE FDA INTERFACE, REC FD02, POS 5-14, 19-28, 33-42, 47-56, 61-70 AND REC FD04, POS 5-14, A UNIT OF MEASURE (UOM) MUST BE TRANSMITTED. VALID FDA UNITS OF MEASURE ARE SHOWN ON PAGE OGA-31 OF THE CATAIR DOCUMENT. THESE UNITS ARE CONSIDERED TO BE 'BASE UNITS' AND MUST BE EITHER THE LAST UNIT SENT (WHEN MORE THAN ONE QUANTITY/UOM PAIR IS ALSO TRANSMITTED) OR MUST BE THE UOM WHEN ONLY ONE QUANTITY IS SENT.");
			aBIErrorCollection["VGO"] = new MessageError(errorCode: "VGO", shortDesc: "FD 701: FDA VALUE EXCEEDS USCS", narrative: "THE FDA VALUE (REC03, POS 5-14) MUST NOT EXCEED THE CUSTOMS VALUE IN THE 40+70+80+81 RECORD(S) OR THIS REJECT WILL OCCUR. THIS REJECT WILL ALSO OCCUR IF MULTIPLE FDA LINES (FD01-FD05 RECORDS) ARE SENT WITHIN ONE CUSTOMS LINE AND ALL OF THE VALUES COMBINED IN THOSE LINES EXCEED THE CUSTOMS VALUE.");
			aBIErrorCollection["VGP"] = new MessageError(errorCode: "VGP", shortDesc: "FD 701: VALUE MUST BE } 0", narrative: "THE FDA VALUE IN REC FD03, POS 5-15, MUST BE MORE THAN ZERO. BLANKS ARE PERMITTED.");
			aBIErrorCollection["VGQ"] = new MessageError(errorCode: "VGQ", shortDesc: "FD 701: ESTBLSMNT ID NOT ON FILE", narrative: "AN FDA ESTABLISHMENT IDENTIFIER (FEI) NUMBER IS A TWELVE-DIGIT NUMBER THAT IDENTIFIES A DOMESTIC LOCATION (ADDRESS) OF AN FDA IMPORTER OR DOMESTIC CLIENT. THESE NUMBERS RESIDE IN ACS IN THE FDF (FDFL) FILE. THEY ARE CRE- ATED IN THE FDA INTERFACE BY FILERS REQUESTING, THROUGH ABI TO FDA, A NUMBER FOR A DOMESTIC LOCATION. THE REQUEST IS MOST OFTEN MADE WHEN THE FILER HAS SENT A FOREIGN-BASED CONSIGNEE AND HAS RECEIVED AN FDA REJECT. THE FEI NUMBER, IF USED, IS SENT IN REC FD03, POS 15-26 AND MUST CONTAIN 12 NUMERIC CHARACTERS. THE MOST COMMON MISTAKE IS TO OMIT THE FIRST TWO ZEROS AND TRANSMIT ONLY TEN NUMBERS.");
			aBIErrorCollection["VGR"] = new MessageError(errorCode: "VGR", shortDesc: "FD 701: DMNS MUST BE IN INCH/16TH", narrative: "IN THE FDA INTERFACE THE FILER MUST SEND CONTAINER DIMENSIONS FOR LOW ACID CANNED FOODS. CONTAINER DIMENSIONS ARE FOUND IN THE FD03 RECORD. CONTAINER DIMENSION 1 IS FOUND IN POSITIONS 65-68, CONTAINER DIMENSION 2 IN POSITIONS 69-72 AND CONTAINER DIMENSION 3 IN POSITIONS 73-76. IF A CONTAINER DIMENSION IS TRANSMITTED IT MUST BE IN INCHES AND 16THS OF AN INCH. FOR EXAMPLE, IF THE CAN SIZE IS 5 AND 3/16, IT WOULD BE REPORTED AS '0503'. IF THE CAN SIZE IS 13 AND 13/16, IT WOULD BE REPORTED AS '1313'.");
			aBIErrorCollection["VGS"] = new MessageError(errorCode: "VGS", shortDesc: "FD 701: DMNS INV;PREV DMNS=0'S", narrative: "THIS ERROR MESSAGE OCCURS WHEN A FILER HAS TRANSMITTED A CONTAINER DIMENSION IN THE 'CONTAINER DIMENSION #2' FIELD (REC FD03, POS 69-72) OR 'CONTAINER DIMENSION #3' FIELD (REC FD03, POS 73-76) AND THE PREVIOUS CONTAINER DIMENSION FIELD WAS ZERO FILLED. FOR EXAMPLE, IF 0511 WAS TRANSMITTED IN THE 'CONTAINER DIMENSION #2' FIELD AND 0000 IN THE 'CONTAINER DIMENSION #1' FIELD, THIS REJECT WOULD RESULT.");
			aBIErrorCollection["VGT"] = new MessageError(errorCode: "VGT", shortDesc: "FD 701: UOM NOT ALLOWED W/O QTY", narrative: "IN THE FDA INTERFACE A UOM (UNIT OF MEASURE), REC FD02, POS 15-18, 29-32, 43-46I, 57-60, 71-74 AND REC FD04, POS 15-18 IS NOT ACCEPTED UNLESS IT IS TRANSMITTED WITH A QUANTITY. THE REVERSE IS ALSO TRUE, A QUANTITY IS NOT ALLOWED WITHOUT A UNIT OF MEASURE.");
			aBIErrorCollection["VGU"] = new MessageError(errorCode: "VGU", shortDesc: "FDA 701:FDA NOTIFY NOT REQUIRED", narrative: "THIS ERROR MESSAGE RESULTS WHEN A FILER ATTEMPTS TO SEND FDA DATA FOR A TARIFF NUMBER THAT IS CODED IN THE HARMONIZED DATA BASE AS AN 'FD0' (FDA NOT REQUIRED). FDA DOES NOT WANT INFORMATION FOR THESE TARIFF NUMBERS.");
			aBIErrorCollection["VGW"] = new MessageError(errorCode: "VGW", shortDesc: "FD 701: ACTUAL MFG REQUIRED", narrative: "THERE ARE FIVE REQUIRED DATA ELEMENTS IN THE FDA INTERFACE. ONE IS THE FDA MANUFACTURER. IT IS REQUIRED TO BE SHOWN IN REC FD01, POS 48-62 (SEE CATAIR, PAGE OGA-28). THIS REJECT OCCURS WHEN NO MID IS TRANSMITTED.");
			aBIErrorCollection["VGX"] = new MessageError(errorCode: "VGX", shortDesc: "INVALID FORMAT", narrative: "THIS ERROR MESSAGE OCCURS IN THE FDA INTERFACE WHEN A FILER ATTEMPTS TO SEND A QUERY OR AN ADD REQUEST FOR AN FDA ESTABLISHMENT NUMBER (FEI) IN THE PP TRANSACTION AND THE FORMAT OF THEIR QUERY IS INCORRECT. THIS CAN TAKE MANY FORMS BUT USUALLY INVOLVES TRYING TO FIT A FOREIGN ADDRESS INTO FIELDS THAT ONLY ACCEPT A US ADDRESS. IN MOST CASES, IT INVOLVES A PROGRAMMING PROBLEM IN THE FILERS SOFTWARE. PROPER FORMAT FOR THE PP TRANSACTION IS SHOWN ON PAGES OGQ 14-20 OF THE CATAIR.");
			aBIErrorCollection["VGY"] = new MessageError(errorCode: "VGY", shortDesc: "FEI FOUND ON ACS", narrative: "THIS MESSAGE OCCURS WHEN A FILER QUERIES ABI TO DETERMINE WHETHER AN FDA ESTABLISHMENT NUMBER (FEI) IS ON FILE. IT IS NOT AN ERROR MESSAGE. THESE NUMBERS RESIDE IN THE FDF FILE AND CAN BE QUERIED USING FDFL. ALL TWELVE NUMBERS MUST BE USED INCLUDING THE LEADING ZEROS. THE FILER USES THE FDPP-10 RECORD SHOWN ON PAGE OGQ-14 OF THE CATAIR WITH A 'Q' IN THE ACTION CODE. THIS MESSAGE IS RETURNED WHEN THE FEI NUMBER QUERIED IS FOUND IN ACS.");
			aBIErrorCollection["VGZ"] = new MessageError(errorCode: "VGZ", shortDesc: "FEI NOT FOUND ON ACS", narrative: "THIS MESSAGE OCCURS WHEN A FILER QUERIES ABI TO DETERMINE WHETHER AN FDA ESTABLISHMENT NUMBER (FEI) IS ON FILE. THESE NUMBERS RESIDE IN THE FDF FILE AND CAN BE QUERIED USING FDFL. ALL TWELVE NUMBERS MUST BE USED INCLUDING LEADING ZEROS. THE FILER USES THE FDPP-10 RECORD SHOWN ON PAGE OGQ-14 OF THE CATAIR WITH A 'Q' IN THE ACTION CODE. THIS MESSAGE IS RETURNED WHEN THE FEI NUMBER QUERIED IS NOT FOUND IN ACS. A COMMON REASON IS BECAUSE THE FILER IS NOT QUERYING ALL 12 NUMBERS. THEY SHOULD RESEND THE QUERY USING ALL NUMBERS INCLUDING LEADING ZEROS.");
			aBIErrorCollection["VH2"] = new MessageError(errorCode: "VH2", shortDesc: "DT HS7: VIN# ALREADY ON FILE", narrative: "THE VIN NUMBER TRANSMITTED IN POSITIONS 39-55 OF THE DT02 RECORD HAS ALREADY BEEN TRANSMITTED ON A PREVIOUS ENTRY.");
			aBIErrorCollection["VH3"] = new MessageError(errorCode: "VH3", shortDesc: "FD 701 : ACTUAL SHPR ID REQUIRED", narrative: "THERE ARE FIVE REQUIRED DATA ELEMENTS IN THE FDA INTERFACE. ONE IS THE FDA ACTUAL SHIPPER. IT IS REQUIRED TO BE SHOWN IN THE REC FD01, POS 63-77 (SEE CATAIR, PAGE OGA-28). THIS REJECT OCCURS WHEN NO MID IS TRANSMITTED.");
			aBIErrorCollection["VH4"] = new MessageError(errorCode: "VH4", shortDesc: "DT HS7: INV LINE #/SEQ", narrative: "IF MULTIPLE SETS OF DOT DATA RE TRANSMITTED FOR THE SAME CUSTOMS LINE NUMBER (WHETHER ON THE HI OR EI APPLICATION), EACH DT01 RECORD MUST BE INCREMENTED IN POS 5-7 TO REFLECT '001' FOR THE FIRST SET OF DATA, '002' FOR THE SECOND SET, ETC. IF A NUMBER IS REPEATED IN THE DOT LINE NUMBER FIELD OR IF A NUMBER IS SKIPPED (IE FROM 001 TO 003), THIS MESSAGE WILL RESULT.");
			aBIErrorCollection["VH5"] = new MessageError(errorCode: "VH5", shortDesc: "DT HS7: DUPLICATE VIN ENCOUNTERED", narrative: "IF TWO SETS OF DOT DATA ARE TRANSMITTED FOR THE SAME CUSTOMS LINE ON AN ENTRY, THE VIN NUMBERS TRANSMITTED IN THE DT02 RECORD CANNOT BE THE SAME. IF THEY ARE, THIS ERROR MESSAGE WILL RESULT. (NOTE: IF THE FILER NEEDS TO REPORT MORE THAN ONE VIN NUMBER FOR MULTIPLE IMPORTS ON THE SAME CUSTOMS LINE, A SEPARATE SET OF DT01/DT02 RECORDS IS REQUIRED FOR EACH VIN. THE DT03, ORIGINALLY DESIGNED TO PROVIDE SPACE TO REPORT MULTIPLE VINS, WILL NOT BE ACCEPTED BY ABI IF A DT02 IS ALSO TRANSMITTED. FOR BOX 2A ONLY, A DT03 CAN BE TRANSMITTED WITH VIN DATA IN LIEU OF A DT02. ALL OTHER BOX NUMBERS REQUIRE A DT02 TO REPORT VEHICLE DATA.)  IF A CHAP 98 HTS IS CODED DT2 AND THE ASSOCIATED HTS IN THE 70 RECORD IS ALSO DT2, A DT01 RECORD IS REQUIRED FOR BOTH TARIFF NUMBERS. IF THE IMPORTED ARTICLE IS A VEHICLE, THE DT02 RECORD MAY BE SUBMITTED ONLY ONCE, EITHER FOLLOWING THE CHAP 98 HTS (50 RECORD) OR THE 70 RECORD HTS. IN APRIL 2004 FILER HAD TO PUT ZEROES IN VIN FIELD OF THE CH 98 NUMBER IN ORDER FOR THE HN TO GO ERROR FREE");
			aBIErrorCollection["VHB"] = new MessageError(errorCode: "VHB", shortDesc: "ISIS INPUT BYPASSED/ERRORS FOLLOW", narrative: "THIS MESSAGE IS ISSUED IN CONJUNCTION WITH ERROR MESSAGE 1AS. IT MEANS THAT ABI REJECTED FDA'S ATTEMPT TO UPDATE (USUALLY A RELEASE) AN ENTRY THAT HAS GONE INTO ARCHIVE STATUS.");
			aBIErrorCollection["VHE"] = new MessageError(errorCode: "VHE", shortDesc: "FC 740: INV PUBLIC W/HOLD IND", narrative: "A CODE OF 'W' (WITHHOLD) IS SENT IN THE FC02 RECORD, POSITION 17, IF THE IMPORTER REQUESTS FCC 740 DATA BE WITHHELD FROM PUBLIC INSPECTION. ANY OTHER CODE WILL BE REJECTED.");
			aBIErrorCollection["VHA"] = new MessageError(errorCode: "VHA", shortDesc: "FD 701:AFFRM/COMPLNCE REQ ON FD05", narrative: "IF THE FILER REPORTS FDA AFFIRMATION OF COMPLIANCE DATA IN THE FD01 RECORD (POS 20-22), AND THERE IS AT LEAST ONE MORE AFFIRMATION OF COMPLIANCE CODE TO REPORT, THE FD05 RECORD MUST BE TRANSMITTED. HOWEVER, THIS RECORD CANNOT BE BLANK. IF THE SECOND OR SUCCEEDING AFFIRMATION OF COMPLIANCE CODES/QUALIFIERS ARE NOT INCLUDED IN THE FD05 RECORD, THIS ERROR MESSAGE WILL BE GENERATED.");
			aBIErrorCollection["VHC"] = new MessageError(errorCode: "VHC", shortDesc: "FD 701:PHONE NBR MUST BE NUMERIC", narrative: "THIS ERROR MESSAGE OCCURS WHEN NON-NUMERIC CHARACTERS ARE INPUT INTO THE 'CONTACT PHONE NUMBER' FIELD, REC FD04, POS 29-38. THIS IS AN OPTIONAL FIELD. A COMMON PROBLEM IS THAT THE USER WILL SEND A 'CONTACT NAME' (REC FD04 POS 19-28) THAT IS LONGER THAN 10 CHARACTERS AND THE FILER'S PROGRAM ALLOWS THE EXTRA CHARACTERS TO SPILL OVER INTO THE PHONE NUMBER FIELD.  ALSO, PHONE NUMBERS MUST INCLUDE THE AREA CODE. IF THIS PART OF THE PHONE NUMBER ELEMENT IS LEFT BLANK, ERROR VHC ALSO RESULTS.");
			aBIErrorCollection["VHD"] = new MessageError(errorCode: "VHD", shortDesc: "FDA701:AFRM/CMPLNCE NOT ALLOWED", narrative: "THIS MESSAGE OCCURS WHEN A FILER ATTEMPTS TO SEND A FDA AFFIRMATION OF COMPLIANCE CODE IN THE FD05 RECORD, POSITIONS 5-7 WHEN THE AFFIRMATION OF COMPLIANCE CODE IN THE FD01 RECORD, POSITIONS 20-22 IS BLANK. IF THERE IS ONLY ONE AFFIRMATION OF COMPLIANCE CODE IT MUST BE SENT IN THE FD01 RECORD. ANY ADDITIONAL (UP TO FOUR) CODES ARE SENT IN THE FD05 RECORD AND THEY CANNOT BE DUPLICATES OF THE CODE IN THE FD01 RECORD.");
			aBIErrorCollection["VHG"] = new MessageError(errorCode: "VHG", shortDesc: "DT HS7: ISO CODE REQUIRED", narrative: "THIS CODE (RECORD DT01 POS 30-31) IS REQUIRED WHEN BOX NUMBER (RECORD DT01, POS 8-9) 05, 06, OR 12 IS TRANSMITTED. (NOTE: IF BOX 05 IS USED, A DT02 RECORD IS ALSO REQUIRED, EVEN IF THE IMPORTED ARTICLE IS NOT A VEHICLE. (THIS IS A SYSTEM DESIGN FLAW.) ISO CODE CANNOT BE USED WITH ANY OTHER HS-7 BOX NUMBER THAN THOSE SPECIFIED IN THIS MESSAGE.");
			aBIErrorCollection["VHK"] = new MessageError(errorCode: "VHK", shortDesc: "DT HS7: DT02 REQUIRED", narrative: "REGARDLESS OF WHICH BOX IS USED (REC DT01, POS 8-9) IF THE CLARIFICATION CODE IN THE DT01 RECORD IS 'V', THEN A DT02 RECORD IS REQUIRED. HOWEVER, IF BOX 05 IS USED AND THE CLARIFICATION CODE IN THE DT01 RECORD IS 'E' OR 'T', A DT02 RECORD IS STILL REQUIRED (SEE COMMENTS FOR MESSAGE VHG). .  AS OF JUNE 2000, ALL BOXES EXCEPT 2B AND 11 REQUIRE A DT02 RECORD IF THE CLARIFICATION CODE IN THE DT01 RECORD IS 'V'.");
			aBIErrorCollection["VHM"] = new MessageError(errorCode: "VHM", shortDesc: "DT HS7: WRONG DATA -ADMIN 96-0608", narrative: "CERTAIN ELEMENTS ARE REQUIRED FOR EACH BOX NUMBER ON THE HS7 FORM (REFERENCE APPENDIX J OF THE CATAIR). CONVERSELY, IF AN ELEMENT IS NOT NEEDED BY DOT, ABI WILL NOT PERMIT THOSE ELEMENTS TO BE TRANSMITTED. CONSULT ADMIN MESSAGE 96-0608 TO SEE WHICH ELEMENTS GO WITH WHICH BOX NUMBERS.  NOTE: IF THE ERRONEOUS DATA ELEMENT IS BEING TRANSMITTED IN THE DT02 RECORD, ABI WILL NOT RETURN THE DT02 IN THE OUTPUT. CHECK ALL THE FIELDS IN THE DT02 TO INSURE THAT ANY ITEM NOT IDENTIFIED IN THE REFERENCED ADMIN MSG ABOVE IS NOT BEING INCLUDED BY THE FILER.");
			aBIErrorCollection["VHQ"] = new MessageError(errorCode: "VHQ", shortDesc: "DT HS7: MAKE REQUIRED", narrative: "THIS ERROR MESSAGE OCCURS IN THE DOT INTERFACE. THE MAKE (NAME OF COMPANY THAT MANUFACTURED VEHICLE) SENT IN POSITIONS 5-19 OF THE DT02 RECORD IS MANDATORY IF BOXES 03, 05 OR 12 IS SENT IN POSITIONS 8-9 OF THE DT01 RECORD.");
			aBIErrorCollection["VHR"] = new MessageError(errorCode: "VHR", shortDesc: "DT HS7: INVALID MAKE", narrative: "THIS ERROR RESULTS IF THE MAKE OF THE VEHICLE IN THE DT02 RECORD, POS 5-19 HAS FEWER THAN 3 CHARACTERS.");
			aBIErrorCollection["VHS"] = new MessageError(errorCode: "VHS", shortDesc: "DT HS7: MODEL REQUIRED", narrative: "THIS MESSAGE IS GENERATED IN RESPONSE TO A DOT INTERFACE RECORD (DT02). IF THE FILER TRANSMITS A DT02 RECORD WITH THE VEHICLE IDENTIFICATION DATA, A MODEL NAME IS REQUIRED IN POS 20-34 OF THE DT02 RECORD. IF THE MODEL NAME IS LEFT BLANK, THIS MESSAGE WILL RESULT.");
			aBIErrorCollection["VHT"] = new MessageError(errorCode: "VHT", shortDesc: "DT HS7: YEAR REQUIRED", narrative: "THIS MESSAGE IS GENERATED IN RESPONSE TO A DOT INTERFACE TRANSMISSION RECORD. IF THE FILER TRANSMITS VEHICLE IDENTIFICATION DATA IN THE DT02 RECORD, THE RECORD MUST INCLUDE A YEAR OF MANUFACTURE IN POS 35-38. IF THIS FIELD IS LEFT BLANK, THIS ERROR MESSAGE WILL BE GENERATED.");
			aBIErrorCollection["VHU"] = new MessageError(errorCode: "VHU", shortDesc: "DT HS7: INVALID YEAR", narrative: "THE DT02 REC, POS 35-38 MUST REFLECT THE FOUR-DIGIT YEAR. ANY YEAR NOT IN THE RANGE FROM 1901 THROUGH 2099, INCLUSIVE, WILL GENERATE THIS ERROR MESSAGE.");
			aBIErrorCollection["VHV"] = new MessageError(errorCode: "VHV", shortDesc: "DT HS7: VIN REQUIRED", narrative: "IF THE FILER REPORTS DOT INFORMATION TO ABI AND THE DT01 RECORD SHOWS A CLARIFICATION CODE OF 'V' IN POSITION 37, A SECOND RECORD (DT02) IS REQUIRED TO REPORT THE VEHICLE IDENTIFICATION NUMBER. IF THAT RECORD OMITS THE VIN, THIS ERROR MESSAGE WILL BE GENERATED.");
			aBIErrorCollection["VHW"] = new MessageError(errorCode: "VHW", shortDesc: "DT HS7: NHTSA REG IMP NBR REQ'D", narrative: "IF BOX 03 IS REFLECTED IN THE DT01 REC, POS 8-9, THIS ELEMENT IN POS 56-63 OF THE DT02 RECORD IS REQUIRED.");
			aBIErrorCollection["VHX"] = new MessageError(errorCode: "VHX", shortDesc: "DT HS7: NHTSA RI NBR NOT ON FILE", narrative: "IF A REGISTERED IMPORTER NUMBER IS TRANSMITTED IN THE DT02 RECORD, POS 56-63, IT MUST BE TRANSMITTED IN THE FOLLOWING FORMAT: R-YY-NNN. THE NUMBER TRANSMITTED MUST ALSO RESIDE ON THE DTRL DATABASE. IF THE NUMBER IS NOT ON THE DTRL FILE OR IS NOT TRANSMITTED IN THE PROPER FORMAT, THIS MESSAGE WILL RESULT.");
			aBIErrorCollection["VHY"] = new MessageError(errorCode: "VHY", shortDesc: "DT HS7: NHTSA RI NOT EFF FOR EDA", narrative: "THE DTRL FILE LISTS ALL VALID REGISTERED IMPORTERS BY A SPECIFICALLY ASSIGNED NUMBER (RI NUMBER). EACH NUMBER ALSO HAS AN EFFECTIVE DATE, USUALLY FOR ONE YEAR AT A TIME. IF THE RI NUMBER IS NOT IN EFFECT ON THE ESTIMATED DATE OF ARRIVAL AS TRANSMITTED BY THE FILER IN THE HI OR EI RECORDS, THIS MESSAGE WILL RESULT.");
			aBIErrorCollection["VHZ"] = new MessageError(errorCode: "VHZ", shortDesc: "DT HS7: V ELIGIBILITY NBR REQ'D", narrative: "IF BOX 03 IS TRANSMITTED IN THE DT01 REC, POS 8-9, A VEHICLE ELIGIBILITY NUMBER MUST BE TRANSMITTED IN POS 64-69 OF THE DT01 RECORD.");
			aBIErrorCollection["VIG"] = new MessageError(errorCode: "VIG", shortDesc: "MULTIPLE I.T. DATES NOT ALLOWED", narrative: "IF AN ENTRY OR ENTRY SUMMARY TRANSMISSION FROM AN ABI FILER CONTAINS MORE THAN 1 INTRANSIT NUMBER, THE DATE OF EACH I.T. NUMBER MUST BE THE SAME. THUS, AN I.T. OPENED ON JAN 15 AND ANOTHER I.T., OPENED ON JAN 16, COULD NOT BOTH BE TRANSMITTED UNDER THE SAME ENTRY NUMBER, EVEN IF THE ARRIVAL PORT AND DESTINATION PORT ARE THE SAME FOR BOTH I.T.'S.  NOTE: AS OF MAY, 1999, THIS ERROR MESSAGE APPEARED ON AN ENTRY WITH ONE I.T. NUMBER IN A 22 RECORD AND NO I.T. NUMBER IN THE NEXT 22 RECORD. THIS CONDITION IS MORE PROPERLY COVERED BY ERROR MESSAGE VII (WHICH WAS ALSO APPENDED TO THE ENTRY TRANSMISSION).");
			aBIErrorCollection["VIH"] = new MessageError(errorCode: "VIH", shortDesc: "NO MANIFEST/INBOND DATA ENTERED", narrative: "THIS MESSAGE OCCURS IN THE NAFTA DUTY DEFERRAL MODULE. IF THE OPTIONAL D03 RECORD (DATA PERTAINING TO THE IE/TE NUMBER, DATE, QUANTITY AND UNIT) IS TRANSMITTED, THEN THERE MUST BE 'IE/TE NUMBER' INFORMATION TRANSMITTED IN POSITIONS 4-15 OF THIS RECORD.");
			aBIErrorCollection["VII"] = new MessageError(errorCode: "VII", shortDesc: "COMBINED I.T./NON I.T. INVALID", narrative: "IF AN ENTRY OR ENTRY SUMMARY TRANSMISSION FROM AN ABI FILER CONTAINS AN I.T. NUMBER AND DATE FOR ONE BILL OF LADING, THEN ANY OTHER BILLS OF LADING MUST ALSO REFLECT AN I.T. NUMBER AND DATE. IF A BILL OF LADING NUMBER IS TRANSMITTED WITHOUT AN I.T. NUMBER AND DATE FOR SUCH AN ENTRY OR ENTRY SUMMARY, THIS ERROR MESSAGE WILL RESULT.");
			aBIErrorCollection["VIK"] = new MessageError(errorCode: "VIK", shortDesc: "FD 701: CMPLNCE QUAL W/O AFFRM CD", narrative: "THIS ERROR MESSAGE IS SEEN IN THE FDA INTERFACE. SOME FDA PRODUCT CODES MAY REQUIRE WHAT IS KNOWN AS AN FDA AFFIRMATION OF COMPLIANCE (FDC FILE). THERE IS NO EDIT LINKING THE AFFIRMATION OF COMPLIANCE WITH THE PRODUCT CODE. THE FILERS, THROUGH PAST KNOWLEDGE OF THE SHIPMENT OR FROM INQUIRIES WITH FDA, KNOW WHICH PRODUCTS REQUIRE AFFIRMATIONS. AFFIRMATIONS ARE A THREE CHARACTER CODE WHICH IS MEANINGFUL TO FDA. SOME OF THESE AFFIRMATIONS REQUIRE 'QUALIFIERS' WHICH MAY BE FORMS, LICENSES OR DECLARATIONS. IN THE FDC FILE THESE ARE CODED WITH 'Y' FOR 'YES, REQUIRED'. THIS ERROR IS GENERATED WHEN THE FILER SENDS THE AFFIRMATION QUALIFIER BUT NOT THE AFFIRMATION CODE ITSELF. THE AFFIRMATION OF COMPLIANCE IS SENT IN REC FD01, POS 20-22. THE AFFIRMATION OF COMPLIANCE QUALIFIER IS SENT IN REC FD01, POS 23-47. SEE CATAIR, PAGE OGA-28.");
			aBIErrorCollection["VJC"] = new MessageError(errorCode: "VJC", shortDesc: "CONT BOND INSUFFICIENT: STB REQD", narrative: "THIS MESSAGE INDICATES THAT THE BOND FILE (FUNCTION CODE BNDL) HAS BEEN UPDATED TO REFLECT AN 'N' IN THE FIELD 'BOND SUFFICIENT - Y/N'. THE NFC REVIEWS CONTINUOUS BONDS WITH A REPORT THAT COMPARES THE BOND AMOUNT TO THE TOTAL OF THE IMPORTER'S DUTIES/TAXES/FEES PAID IN THE PRIOR BOND YEAR. IF THE RATIO OF THE BOND TO THE TOTAL MONETARY OBLIGATIONS IS UNDER 10%, A 'BOND-IS-INSUFFICIENT' LETTER IS SENT BY THE NFC TO THE IMPORTER OF RECORD (FROM SRE). IF NO ADEQUATE OR TIMELY REPLY IS RECEIVED TO THE NFC LETTER, THE BND RECORD IS SET TO 'N' FOR SUFFICIENCY AND THIS ERROR MSG RESULTS. PROVISIONAL ABI CARGO SELECTIVITY WILL BE WITHHELD UNTIL THE FILER RETRANSMITS THE ENTRY WITH AN STB. (SOME BONDS KEPT AT THE LOCAL PORTS ARE REVIEWED LOCALLY, BUT CENTRALIZATION OF CONTINUOUS BONDS WILL EVENTUALLY ELIMINATE LOCAL REVIEW).  FILERS/IMPORTERS SHOULD CALL THE NFC BOND DESK AT 317-614-4880");
			aBIErrorCollection["VKI"] = new MessageError(errorCode: "VKI", shortDesc: "HLT:DUPE DEF. NOT FOUND (HLT)", narrative: "THE TABLE NAME/SEARCH NUMBER COMBINATION SPECIFIED TO BE DUPLICATED FROM DOES NOT EXIST ON THE HLT DB.");
			aBIErrorCollection["VL1"] = new MessageError(errorCode: "VL1", shortDesc: "DBK IMPORT ENTRY DATE INVALID", narrative: "THIS DRAWBACK MODULE ERROR MESSAGE MEANS THAT THE DATE GIVEN ON THE DISKETTE WAS NOT A VALID DATE IN YYMMDD (IN Y2K YYYYMMDD) FORMAT. THE ACTUAL DATE OF ENTRY IS NOT VALIDATED.");
			aBIErrorCollection["VL2"] = new MessageError(errorCode: "VL2", shortDesc: "DBK IMPORT ENTRY CANNOT = CLAIM #", narrative: "THIS DRAWBACK MODULE ERROR MESSAGE MEANS THAT THE FILER HAS ERRONEOUSLY ATTEMPTED TO DESIGNATE AN IMPORT ENTRY WITH THE SAME ENTRY NUMBER AS THE DRAWBACK CLAIM BEING MADE.");
			aBIErrorCollection["VL3"] = new MessageError(errorCode: "VL3", shortDesc: "DRAWBACK DDPP INVALID", narrative: "IN THE DRAWBACK MODULE THIS MESSAGE MEANS THAT THE FILER HAS GIVEN US A CLAIM THAT DOES NOT USE ONE OF THE EIGHT CORRECT PORT CODES BY FILING LOCATION. 0401, 1001, 2002, 3901, 5201, 5301, 2704, 2809");
			aBIErrorCollection["VL4"] = new MessageError(errorCode: "VL4", shortDesc: "DRAWBACK TEAM INVALID", narrative: "IN THE DRAWBACK MODULE THIS MESSAGE MEANS THAT THE FILER HAS GIVEN US A DRAWBACK CLAIM WITH AN INVALID DRAWBACK TEAM NUMBER.");
			aBIErrorCollection["VL5"] = new MessageError(errorCode: "VL5", shortDesc: "DRAWBACK TEAM INVALID FOR DDPP", narrative: "IN THE DRAWBACK MODULE THIS MESSAGE MEANS THAT THE DDPP/TEAM COMBINATION IS NOT CORRECT. THIS WILL MOST OFTEN APPEAR IN COMBINATION WITH ERROR MESSAGE VL4. THERE IS A DIRECT CODED LINK BETWEEN THE VALID FILING DDPP CODES AND THE VALID TEAM CODES.");
			aBIErrorCollection["VL6"] = new MessageError(errorCode: "VL6", shortDesc: "DRAWBACK DDPP MUST = B REC DDPP", narrative: "THIS MESSAGE MEANS THAT WHILE THE DRAWBACK CLAIM DDPP MAY BE CORRECT, IT DOES NOT MATCH THE DDPP OF THE DRAWBACK FILING LOCATION (THE PC PORT CODE THAT THE MAINFRAME RECOGNIZES). THIS MESSAGE MAY APPEAR IN COMBINATION WITH ANY OTHER INVALID DDPP MESSAGES. IN ABI, THE PORT CODE IN THE 'B' CONTROL RECORD MUST MATCH THE PORT CODE FOR THE CLAIM IN THE 'D10' RECORD.");
			aBIErrorCollection["VL7"] = new MessageError(errorCode: "VL7", shortDesc: "DRAWBACK DDPP NOT FOUND", narrative: "THIS MESSAGE MEANS THAT THE FILER HAS USED AN IMPOSSIBLE DDPP IN THE DRAWBACK MODULE.");
			aBIErrorCollection["VL8"] = new MessageError(errorCode: "VL8", shortDesc: "DBK FILER/LOCATION NOT PERMITTED", narrative: "THIS MESSAGE OCCURS ONLY WHEN THERE IS A MISMATCH BETWEEN THE LICENSE PORT AND THE PORT OF THE DRAWBACK CLAIM.");
			aBIErrorCollection["VL9"] = new MessageError(errorCode: "VL9", shortDesc: "DRAWBACK CLAIMANT ID INVALID", narrative: "THIS ERROR MESSAGE INDICATES THAT THE FORMAT OF THE DRAWBACK CLAIMANT ID IS NOT A VALID IRS/SS/CUSTOMS ASSIGNED NUMBER FORMAT. VALID IRS FORMAT IS NN-NNNNNNNXX (WHERE 'XX'=SUFFIX); SS IS NNN-NN-NNNN; CUSTOMS ASSIGNED NUMBER IS YYDDPP-NNNNN.");
			aBIErrorCollection["VLB"] = new MessageError(errorCode: "VLB", shortDesc: "FC 740: INVALID FCC ID VALUE", narrative: "FCC IDENTIFIERS ARE TRANSMITTED IN THE FC01 REC, POS 11-27. A MINIMUM OF FOUR ALPHANUMERIC CHARACTERS (INCLUDING SPECIAL CHARACTERS SUCH AS '/' '-', ETC) ARE REQUIRED FOR THIS ELEMENT. THE FCC ID IS REQUIRED WHEN POS 5-6 OF THE FC01 REC INDICATE '1' AS THE IMPORT CONDITION.");
			aBIErrorCollection["VLE"] = new MessageError(errorCode: "VLE", shortDesc: "INVALID NAFTA NET COST CLAIM", narrative: "THE NAFTA NET COST CLAIM INDICATOR IS SENT IN THE EI TRANSACTION, RECORD 40, POSITION 79. IT CAN BE EITHER A 'Y' FOR 'YES' OR SPACE FILLED IF IT DOES NOT APPLY. TO QUALIFY FOR NAFTA THE REGIONAL VALUE CONTENT (RVC) MUST BE A CERTAIN PERCENTAGE. THE VALUE CAN EITHER BE TRANSACTION VALUE OR NET COST METHOD. IF THE LATTER, THIS CLAIM IS MADE. IF THE CLAIM IS MADE THERE MUST BE A VALID SPI OF CA, MX, B# OR C# IN POSITIONS 78-79 OF THE EI 50 RECORD. SEE ADMINISTRATIVE MESSAGES 94-0238 AND 94-0840.");
			aBIErrorCollection["VLF"] = new MessageError(errorCode: "VLF", shortDesc: "GREATER THAN 9,999 ITEMS SENT", narrative: "THE TOTAL OF ALL IMPORT ENTRY AND CM RECORDS IN A DRAWBACK TRANSACTION CANNOT EXCEED THE MAXIMUM OF 9,999. THAT NUMBER IS THE MAXIMUM ACS CAN HANDLE.  FOR RECONCILIATION, THIS MEANS THAT MORE THAN 9,999 IMPORT ENTRY ASSOCIATION RECORDS WERE TRANSMITTED.");
			aBIErrorCollection["VLG"] = new MessageError(errorCode: "VLG", shortDesc: "IMPORT TRAILER # OUT OF SEQUENCE", narrative: "THIS MESSAGE MEANS THAT THE IMPORT TRAILER SEQUENCE NUMBERS ARE OUT OF SEQUENCE IN THE DRAWBACK MODULE.  NOTE THAT CONTRACT SEQUENCE NUMBERS ARE 01-99. IF ONLY 1 CONTRACT IS USED ON A CLAIM, THAT CONTRACT NUMBER SHOULD APPEAR IN THE CLAIM HEADER RECORD. THE CONTRACT TRAILER RECORD SHOULD NOT BE USED UNLESS THERE ARE MULTIPLE CONTRACTS ON A CLAIM. THE CONTRACT TRAILER COUNTER IS NOT A COUNT OF CONTRACTS, BUT IS A COUNT OF THE CONTRACT TRAILER RECORDS. IF ONLY ONE CONTRACT IS USED, THE COUNTER SHOULD BE 00, SINCE THERE WILL BE NO TRAILER RECORDS. IF 2 CONTRACTS ARE USED THERE WILL BE ONE CONTRACT TRAILER AND THE COUNT WILL BE 01. THREE CONTRACTS WOULD MEAN TWO TRAILERS AND THE COUNT WOULD BE 02, ETC.  FOR RECONCILIATION, THIS MEANS THAT THE SEQUENCING OF THE IMPORT ENTRY ASSOCIATION RECORDS ('R20') IS OUT OF ORDER.");
			aBIErrorCollection["VLJ"] = new MessageError(errorCode: "VLJ", shortDesc: "DUP MFGR # ENCOUNTERED/CERT MFGR", narrative: "THIS DRAWBACK MODULE ERROR MESSAGE MEANS THAT THE FILER HAS GIVEN US THE SAME CM NUMBER (CERT MFGR #) MORE THAN ONCE ON THE CLAIM. JUST AS WITH IMPORT ENTRIES CLAIMED ON THE DISKETTE OR VIA ABI, THE CM NUMBER SHOULD ONLY APPEAR ONCE WITH THE TOTAL DRAWBACK CLAIMED FOR THAT CM.");
			aBIErrorCollection["VLN"] = new MessageError(errorCode: "VLN", shortDesc: "DRAWBACK CLAIM TYPE INVALID", narrative: "THIS MESSAGE INDICATES THE USE OF A DRAWBACK CLAIM TYPE (OR AN ENTRY TYPE) OF OTHER THAN '41' '42' '43' '44' '45', OR '46'.");
			aBIErrorCollection["VLO"] = new MessageError(errorCode: "VLO", shortDesc: "DRAWBACK NAFTA IND INVALID", narrative: "THIS MESSAGE INDIACTES THE DRAWBACK FILER HAS USED A CODE OF OTHER THAN 'Y' OR 'N' FOR WHETHER THIS IS A NAFTA CLAIM. THE FILER MUST USE EITHER 'Y' OR 'N' VIA DISKETTE OR A SPACE ('NO') OR '1' ('YES') FOR ABI.");
			aBIErrorCollection["VLH"] = new MessageError(errorCode: "VLH", shortDesc: "CERT MFR TRAILER # OUT OF SEQUENC", narrative: "THIS MESAGE MEANS THAT THE CERT MFR (CM) TRAILER SEQUENCE NUMBERS ARE OUT OF SEQUENCE IN THE DRAWBACK MODULE.  NOTE THAT CONTRACT SEQUENCE NUMBERS ARE 01-99. IF ONLY 1 CONTRACT IS USED ON A CLAIM, THAT CONTRACT NUMBER SHOULD APPEAR IN THE CLAIM HEADER RECORD. THE CONTRACT TRAILER RECORD SHOULD NOT BE USED UNLESS THERE ARE MULTIPLE CONTRACTS ON A CLAIM. THE CONTRACT TRAILER COUNTER IS NOT A COUNT OF CONTRACTS, BUT IS A COUNT OF THE CONTRACT TRAILER RECORDS. IF ONLY ONE CONTRACT IS USED, THE COUNTER SHOULD BE 00, SINCE THERE WILL BE NO TRAILER RECORDS.IF 2 CONTRACTS THEN THERE WILL BE ONE CONTRACT TRAILER AND THE COUNT WILL BE 01. THREE CONTRACTS WOULD MEAN TWO TRAILERS AND THE COUNT WOULD BE 02, ETC.");
			aBIErrorCollection["VLI"] = new MessageError(errorCode: "VLI", shortDesc: "DUP ENTRY # ENCOUNTERED/IMPORT", narrative: "THIS DRAWBACK MODULE MESSAGE MEANS THAT THE IMPORT ENTRY CITED ON THE DRAWBACK DISKETTE WAS SHOWN MORE THAN ONCE. SINCE THE DISKETTE AND ABI TRANSMISSION ARE CLAIM SUMMARIES, FILERS ARE INSTRUCTED TO ONLY SHOW AN IMPORT ENTRY ONE TIME AND SUMMARIZE THE TOTAL CLAIMED AMOUNT FOR THAT ENTRY. ON THE LEGAL PAPER CLAIM, A SINGLE IMPORT ENTRY MAY BE SHOWN MANY TIMES (FOR EXAMPLE, WHEN THEY BREAK A CLAIM DOWN BY PART NUMBER), BUT ON THE DISKETTE IT CAN ONLY APPEAR ONCE  FOR RECONCILIATION, THIS MESSAGE MEANS THAT ONE OF THE ASSOCIATED IMPORT ENTRIES WAS CITED MORE THAN ONCE ON THIS RECON SUMMARY. AN IMPORT ENTRY CAN ONLY BE LISTED ONCE FOR THE RECONCILIATION.");
			aBIErrorCollection["VLK"] = new MessageError(errorCode: "VLK", shortDesc: "TOT IMPORT TRAILER COUNT INVALID", narrative: "THIS DRAWBACK MODULE ERROR MESSAGE MEANS THAT THE SUM OF ALL THE DISKETTE 'IT' IMPORT TRAILER, 'CN' CONTRACT TRAILER, 'CM' IMPORT TRAILER, OR 'CI' CANADIAN IMPORT TRAILER RECORDS OR ABI 'D12', 'D30', 'D40', OR 'D50' RECORDS DOES NOT ADD UP TO WHAT THE COUNT IS IN THE 'CT CLAIM TRAILER' RECORD, OR ABI 'D90' RECORD. BECAUSE IT DOES NOT ADD UP ABI CANNOT KNOW WHETHER THE TOTAL COUNT IS SIMPLY WRONG, OR THE TOTAL COUNT IS RIGHT AND THERE ARE MISSING RECORDS.  FOR RECONCILIATION, THE 'R90' TOTAL IMPORT TRAILER RECORD COUNT OF 'R20' RECORDS DOES NOT MATCH THE ACTUAL NUMBER OF 'R20' RECORDS GIVEN VIA THE ABI 'RA' TRANSACTION. IF THE R20 RECORD, POS 78-79 IS BLANK, THIS MESSAGE WILL BE GENERATED, EVEN IF THE FIGURE IN THE R90 REC, POS 4-7, EQUALS THE NUMBER OF R20 RECORDS IN THE RECONCILIATION INPUT TRANSACTION.");
			aBIErrorCollection["VLL"] = new MessageError(errorCode: "VLL", shortDesc: "TOT CERT MFGR COUNT INVALID", narrative: "THIS DRAWBACK MODULE ERROR MESSAGE MEANS THAT THE SUM OF ALL THE DISKETTE 'IT' IMPORT TRAILER, 'CN' CONTRACT TRAILER, 'CM' IMPORT TRAILER, OR 'CI' CANADIAN IMPORT TRAILER RECORDS OR ABI 'D12', 'D30', 'D40', OR 'D50' RECORDS DOES NOT ADD UP TO WHAT THE COUNT IS IN THE 'CT CLAIM TRAILER' RECORD, OR ABI 'D90' RECORD. BECAUSE IT DOES NOT ADD UP ABI CANNOT KNOW WHETHER THE TOTAL COUNT IS SIMPLY WRONG, OR THE TOTAL COUNT IS RIGHT AND THERE ARE MISSING RECORDS.");
			aBIErrorCollection["VLM"] = new MessageError(errorCode: "VLM", shortDesc: "DRAWBACK DELETE CODE INVALID", narrative: "THIS MESSAGE WILL APPEAR IF THE FILER HAS USED AN ADDITION/DELETION CODE OF 'D' ON THE 'CH' HEADER RECORD OF THE DRAWBACK DISKETTE (THE D10 ABI RECORD) AND THE CLAIM IS ALREADY IN A CUSTOMS STATUS. A DELETE OF A CLAIM BY A FILER CAN ONLY BE HONORED IF THE CLAIM IS STILL IN 'ABI' STATUS. ALL CLAIMS CREATED BY DISKETTE OR VIA ABI ARE PLACED IN ABI STATUS BY ACS WHEN FIRST ACCEPTED ERROR-FREE. THE SAME LOGIC APPLIES TO IMPORT ENTRIES FILED ELECTRONICALLY VIA ABI. ONCE IN CUSTOMS STATUS, THEY CANNOT BE DELETED BY THE FILER.  NOTE: THE CLAIM CANNOT BE DELETED AT ALL IF ACCELERATED DRAWBACK HAS BEEN PAID. IF ACCELERATED DRAWBACK HAS BEEN PAID AND THE FILER WISHES TO DELETE, THE CLAIM WILL HAVE TO BE LIQUIDATED 'NO DRAWBACK' AND A BILL ISSUED FOR REPAYMENT OF THE ACCELERATED DRAWBACK. IF ACCELERATED HAS NOT BEEN PAID, BUT THE ENTRY IS IN A CUSTOMS STATUS, IT CAN BE CANCELLED, BUT NOT DELETED.");
			aBIErrorCollection["VLP"] = new MessageError(errorCode: "VLP", shortDesc: "DRAWBACK GOVT CLAIM INVALID", narrative: "THIS MEANS THE DRAWBACK FILER HAS USED A CODE OF OTHER THAN 'Y' ('YES') OR 'N' ('NOâ€) FOR WHETHER THIS IS A GOVERNMENT CLAIM. THE FILER MUST USE EITHER 'Y' OR 'N' VIA DISKETTE OR A SPACE ('NO') OR '1' ('YES') FOR ABI.");
			aBIErrorCollection["VLQ"] = new MessageError(errorCode: "VLQ", shortDesc: "DRAWBACK EXPORT SUMM IND INVALID", narrative: "THIS MESSAGE MEANS THAT THE FILER HAS USED A CODE OF OTHER THAN 'Y' (YES) OR 'N' (NO) FOR WHETHER THIS IS AN EXPORT SUMMARY CLAIM. THE FILER MUST USE EITHER 'Y' OR 'N' VIA DISKETTE OR A SPACE (NO) OR '1' (YES) FOR ABI. APPLIES TO DRAWBACK MODULE.");
			aBIErrorCollection["VLR"] = new MessageError(errorCode: "VLR", shortDesc: "DRAWBACK WAIVER IND INVALID", narrative: "IN THE DRAWBACK MODULE THIS MESSAGE MEANS THAT THE FILER HAS USED A CODE OF OTHER THAN 'Y' (YES) OR 'N' (NO) VIA DISKETTE OR '1' (YES) OR SPACE (NO) IF VIA ABI FOR WHETHER THIS IS A WAIVER OF PRIOR NOTICE CLAIM. THE FILER MUST USE EITHER 'Y' ('1' IF ABI) OR 'N' (SPACE IF ABI).");
			aBIErrorCollection["VLS"] = new MessageError(errorCode: "VLS", shortDesc: "DRAWBACK INSPECTION IND INVALID", narrative: "THIS ERROR MESSAGE MEANS THAT THE FILER HAS USED A CODE OF OTHER THAN 'Y' ('YES') OR 'N' ('NO') FOR WHETHER THIS IS AN INSPECTION CLAIM. THE FILER MUST USE EITHER 'Y' OR 'N' VIA DISKETTE OR SPACE ('NO') OR '1' ('YES') FOR ABI.");
			aBIErrorCollection["VLT"] = new MessageError(errorCode: "VLT", shortDesc: "TOT DRAWBACK DUTY AMOUNT INVALID", narrative: "THE TOTAL AMOUNT OF DRAWBACK DUTY CLAIMED IN REC 90, POS 4-15 DOES NOT REFLECT THE SUM TOTAL OF DRAWBACK DUTY CLAIMED IN RECS D30, POS 30-41 AND RECS D40, POS 20-31.");
			aBIErrorCollection["VLU"] = new MessageError(errorCode: "VLU", shortDesc: "TOT DRAWBACK TAX AMOUNT INVALID", narrative: "THIS DRAWBACK MODULE ERROR MESSAGE MEANS THAT THE TOTAL CLAIMED TAX DOES NOT ADD UP FROM THE DESIGNATED IMPORTS/CM'S. ACS TOTALS ALL IMPORT ENTRY AND CM CLAIMED AMOUNTS AND COMPARES THEM TO THE TOTAL THAT THE FILER GAVE IN THE DISKETTE IN THE 'CT' TRAILER RECORD. NOTE: THERE IS NOW A TOLERANCE OF + OR - $1.00 ALLOWED ON THE TOTAL BEFORE THIS MESSAGE WILL BE GENERATED.");
			aBIErrorCollection["VLV"] = new MessageError(errorCode: "VLV", shortDesc: "DRAWBACK DUTY OR TAX REQUIRED", narrative: "THIS DRAWBACK MODULE ERROR MESSAGE MEANS THAT THE FILER HAS LEFT THE AMOUNT OF DUTY AND TAX BLANK. FOR THE CLAIM TO BE VALID, THERE MUST BE EITHER DUTY OR TAX (OR BOTH) TRANSMITTED.");
			aBIErrorCollection["VLW"] = new MessageError(errorCode: "VLW", shortDesc: "DRAWBACK ACCELERATED CODE INVALID", narrative: "IN THE DRAWBACK MODULE THIS MESSAGE MEANS THE FILER HAS USED A CODE OF OTHER THAN 'Y' (YES) OR 'N' (NO) IF VIA DISKETTE OR 'Y' (YES) OR 'N' (NO) IF ABI FOR WHETHER THIS IS AN ACCELERATED CLAIM. THE FILER MUST USE EITHER 'Y' ('Y' IF ABI) OR 'N' ('N' IF ABI) AND CANNOT LEAVE A SPACE IN THE FIELD.");
			aBIErrorCollection["VLX"] = new MessageError(errorCode: "VLX", shortDesc: "DRAWBACK CM/CD CODE INVALID", narrative: "THIS DRAWBACK MODULE ERROR MESSAGE MEANS THAT THE FILER USED AN INDICATOR OF OTHER THAN 'E' (DIRECT DESIGNATION), 'D' (DESIGNATION FROM A CD) OR 'M' (DESIGNATION FROM A CM) WHERE THEY ARE GIVING IMPORT ENTRY DATA BECAUSE IT IS AVAILABLE.");
			aBIErrorCollection["VLY"] = new MessageError(errorCode: "VLY", shortDesc: "DRAWBACK ENTRY NOT FND FOR DELETE", narrative: "THIS ERROR MESSAGE WILL APPEAR IF THE FILER USES THE ADDITION/DELETION CODE OF 'D' IN THE DRAWBACK 'CH' HEADER RECORD, BUT THE CLAIM RECORD DOES NOT EXIST IN ACS.");
			aBIErrorCollection["VLZ"] = new MessageError(errorCode: "VLZ", shortDesc: "DRAWBACK CLAIM DATE INVALID", narrative: "IN THE DRAWBACK MODULE THIS MESSAGE MEANS THAT THE DATE IS NOT IN A VALID YYMMDD FORMAT ON THE DISKETTE.");
			aBIErrorCollection["VM0"] = new MessageError(errorCode: "VM0", shortDesc: "HLN:OVERRIDE SEQUENCE NBR INVALID", narrative: "THE OVERRIDE SEQUENCE NUMBER IS A REQUIRED FIELD. SEQUENCE NUMBERS MUST BE UNIQUE SEQUENTIAL ASCENDING NUMBERS STARTING FROM 01.");
			aBIErrorCollection["VM9"] = new MessageError(errorCode: "VM9", shortDesc: "ENTRY NOT WAREHOUSE", narrative: "AN ENTRY NUMBER WAS GIVEN AS BEING WAREHOUSE FOR ENTRY TYPES 31, 32, 34, OR 38 BUT THE ENTRY TYPE WAS NOT 21 OR 22.");
			aBIErrorCollection["VMK"] = new MessageError(errorCode: "VMK", shortDesc: "INVALID DIST/PORT ON WHSE ENTRY", narrative: "THE DISTRICT PORT ON 30 RECORD OF EI APPLICATION DID NOT MATCH THE DIST/PORT OF THE WITHDRAWAL SUMMARY. CHECK THE DDPP SENT IN THE 30 RECORD, POSITIONS 32-35 WITH THE DDPP ON FILE FOR THE ENTRY NUMBER CITED IN THE 30 RECORD.");
			aBIErrorCollection["VML"] = new MessageError(errorCode: "VML", shortDesc: "WARNING-WHSE/WTHDR FLR MISMATCH", narrative: "THIS IS A WARNING MESSAGE ONLY. IT OCCURS WHEN THE FILER CODE OF THE ASSOCIATED WAREHOUSE ENTRY, SENT IN POSITIONS 21-23 OF THE 30 RECORD, DOES NOT MATCH THE FILER CODE OF THE WAREHOUSE WITHDRAWAL ENTRY SENT IN POSITIONS 59-61 OF THE 10 RECORD.  NOTE: IF THE WAREHOUSE ENTRY NUMBER IS NOT TRANSMITTED IN THE 30 RECORD, THIS WARNING WILL ALSO BE GENERATED.");
			aBIErrorCollection["VMM"] = new MessageError(errorCode: "VMM", shortDesc: "INVALID WHSE ENTRY SUMMARY", narrative: "THE WHSE SUMMARY CITED ON THE 30 REC EITHER 1) DOES NOT EXIST, 2) IS NOT A TYPE 21 OR 22, OR 3) IS LIQUIDATED, RELIQUIDATED, OR CANCELLED. OR THE 30 RECORD FIELD FOR THE WAREHOUSE ENTRY IS BLANK.");
			aBIErrorCollection["VMO"] = new MessageError(errorCode: "VMO", shortDesc: "WHSE FINALLED; WITHDRAWAL INVALID", narrative: "THE WAREHOUSE SUMMARY CITED ON AN EI'S 30 REC INDICATES THE FINAL WITHDRAWAL HAS ALREADY BEEN PROCESSED AGAINST IT.  CHECK THE PAYMENT STATUS OF THE UNDERLYING WAREHOUSE ENTRY. IF IT IS 'NOT PAID', THE WAREHOUSE ENTRY WAS NEVER PROCESSED. THUS, A WAREHOUSE RECORD (WHSL) WAS NEVER BUILT.  IF A FILER SENDS THE FINAL WAREHOUSE INDICATOR (1 IN POSITION 36 OF THE 30 RECORD) WHEN THEY SEND THE EI FOR THE UNDERLYING WAREHOUSE ENTRY, ACS WILL NOT SET UP THE NECESSARY WHSL RECORD AND THIS ERROR WILL OCCUR FOR THE WAREHOUSE ENTRY WITHDRAWAL. THE ENTRY SPECIALIST NEEDS TO UNSET THE FINALIZED FLAG ON THE WAREHOUSE ENTRY BY CHANGING 'IS THIS THE FINAL WITHDRAWAL?' FROM Y TO N ON ENAC. THEN THE FILER CAN THEN RESEND THE WAREHOUSE WITHDRAWAL.");
			aBIErrorCollection["VMP"] = new MessageError(errorCode: "VMP", shortDesc: "FINAL WITHDRAWAL INDICATR INVALID", narrative: "FOR WAREHOUSE WITHDRAWALS TRANSMITTED THROUGH ABI (CURRENTLY THESE ARE ENTRY TYPES 31, 32, 34, 38), THE FILER MUST STATE WHETHER OR NOT THE INSTANT WITHDRAWAL IS THE FINAL ONE AGAINST THE WAREHOUSE ENTRY NUMBER REPORTED IN THE 30 REC, POS 21-31. THE ONLY ACCEPTABLE INDICATORS FOR THIS FIELD ARE '0' (NOT FINAL WITHDRAWAL) OR '1' (FINAL WITHDRAWAL). ANY OTHER CHARACTER, INCLUDING A BLANK, WILL GENERATE THIS ERROR MESSAGE.  NOTE: IF THE FILER TRANSMITS A FINAL WITHDRAWAL INDICATOR ON ANY OTHER ENTRY TYPE THAN THE 3N SERIES, THIS MESSAGE WILL ALSO BE GENERATED.");
			aBIErrorCollection["VMQ"] = new MessageError(errorCode: "VMQ", shortDesc: "CANNOT RELEASE WAREHOUSE WITHDRAW", narrative: "AN ATTEMPT WAS MADE TO PERFORM AN ANAR AGAINST AN ENTRY THAT IS TYPE 31, 32, 34 OR 38.");
			aBIErrorCollection["VMR"] = new MessageError(errorCode: "VMR", shortDesc: "CARGO RELEASE ON WHSE WITHDRAWAL", narrative: "A WAREHOUSE WITHDRAWAL WAS ATTEMPTED USING AN ENTRY NUMBER THAT ALREADY HAS A RELEASE ON FILE.");
			aBIErrorCollection["VMT"] = new MessageError(errorCode: "VMT", shortDesc: "INVALID EST. ENTRY DATE", narrative: "THE ESTIMATED ENTRY DATE, POS 50-55 ON THE 10 RECORD, IS REQUIRED ON ALL WAREHOUSE WITHDRAWAL TRANSACTIONS SUBMITTED THROUGH ABI. IF THIS ELEMENT IS MISSING, OR IS SENT IN AN INVALID FORMAT (MMYYDD), THIS ERROR MESSAGE IS GENERATED.  REWAREHOUSE ENTRIES (TYPE 22) ALSO REQUIRE AN ESTIMATED ENTRY DATE AS DESCRIBED ABOVE.");
			aBIErrorCollection["VMU"] = new MessageError(errorCode: "VMU", shortDesc: "MOT NOT REQUIRED FOR WHSE WITHDRL", narrative: "MOT CANNOT BE SUPPLIED FOR ENTRY TYPES 31, 32, 34, AND 38");
			aBIErrorCollection["VMV"] = new MessageError(errorCode: "VMV", shortDesc: "WHSE WTHDR REQUIRES PYMNT BY ACH", narrative: "A TYPE 31, 32, 34 OR 38 THAT'S ON STATEMENT MUST BE PAID VIA ACH NOTE: IF THE TRANSMITTER IS AN ACH CREDIT PARTICIPANT, IT WILL NEED TO ESTABLISH A PAYER UNIT NUMBER (SEE FUNCTION DSIL). IT WILL NOT BE REQUIRED TO TRANSMIT THE NUMBER ON ACH PAYMENTS, HOWEVER, SO IT CAN CONTINUE TO PAY VIA ACH CREDIT. SEE ERROR VAM FOR MORE INFORMATION.");
			aBIErrorCollection["VMW"] = new MessageError(errorCode: "VMW", shortDesc: "WHSE WITHDRAWAL ON FILE", narrative: "WAREHOUSE WITHDRAWAL ENTRIES ARE NOT ELIGIBLE FOR CARGO SELECTIVITY BECAUSE THE SUBJECT MERCHANDISE HAS BEEN PREVIOUSLY SUBJECTED TO ADMISSIBILITY REVIEW WHEN THE ORIGINAL WAREHOUSE ENTRY (TYPE 21 OR 22) WAS PROCESSED. HENCE, IF THE FILER'S WAREHOUSE WITHDRAWAL INPUT CONTAINS A CARGO CERTIFICATION FLAG ('1' IN POS 38 OF THE 30 REC), THIS ERROR MESSAGE WILL BE GENERATED. THIS MESSAGE WILL USUALLY BE PRECEDED BY THE LETTERS 'CERT' INDICATING THAT THIS REJECTION IS RELATED TO THE DENIAL OF CARGO RELEASE CERTIFICATION.");
			aBIErrorCollection["VN1"] = new MessageError(errorCode: "VN1", shortDesc: "CERT MFGR NBR INVALID", narrative: "THIS DRAWBACK MODULE ERROR MESSAGE MEANS THAT THE CM (CERT MFGR) NUMBER IS NOT IN VALID CMNNNNNN FORMAT (E.G. CM123456).");
			aBIErrorCollection["VN2"] = new MessageError(errorCode: "VN2", shortDesc: "CERT MFGR NBR NOT ON FILE", narrative: "THIS DRAWBACK MODULE ERROR MESSAGE MEANS THAT THE CM (CERT MFGR) NUMBER FORMAT IS VALID, BUT THE CM NUMBER DOES NOT EXIST IN ACS.");
			aBIErrorCollection["VN3"] = new MessageError(errorCode: "VN3", shortDesc: "CERT MFGR UOM INVALID", narrative: "IN THE DRAWBACK MODULE IF A UNIT OF MEASURE IS GIVEN ON THE CM (CERT MFGR), IT MUST BE A VALID 3 ALPHA-NUMERIC CHARACTER CODE (E.G. BBL, CWT, PCS). ALSO, IT MEANS THAT IF A QUANTITY IS GIVEN, A UNIT OF MEASURE MUST BE REPORTED.");
			aBIErrorCollection["VN4"] = new MessageError(errorCode: "VN4", shortDesc: "D41 RECORD MUST CONTAIN DATA", narrative: "THIS ERROR MESSAGE COULD BE THE RESULT OF A DRAWBACK OR ABI DRAWBACK PROBLEM. IT IS SAYING THEN WHEN CUSTOMS FORMATTED THE RECORDS FROM THE DISKETTE OR WHEN THE DATA WAS SENT VIA ABI, NO DATA WAS PRESENT IN THE GIVEN RECORD. IF THE DRAWBACK DISKETTE HAS NO DATA, THE PC PROGRAM SHOULD STOP IT BEFORE TRANSMISSION; HOWEVER, THERE MAY HAVE BEEN DATA THERE, BUT IT WAS BAD DATA.");
			aBIErrorCollection["VN5"] = new MessageError(errorCode: "VN5", shortDesc: "DESCRIPTION MUST BE } 1 CHARACTER", narrative: "WHILE DESCRIPTION FIELD IS CURRENTLY OPTIONAL DATA IN THE DRAWBACK MODULE, IF A FILER DOES INPUT DESCRIPTIONS, THEY MUST BE MORE THAN A SINGLE CHARACTER.");
			aBIErrorCollection["VN6"] = new MessageError(errorCode: "VN6", shortDesc: "SECURITY VIOLATION/JJ NOT ALLOWED", narrative: "THIS ERROR INDICATES THAT THE FILER'S ABI CONTROL RECORD IN ACS HAS NOT BEEN CORRECTLY SET UP. IF THIS MESSAGE APPEARS ON A CLAIM FILED VIA DISKETTE, IT WILL BE DISREGARDED BY CUSTOMS AND THE FIELD OFFICE WILL CONTACT HEADQUARTERS. IF THIS MESSAGE APPEARS ON A CLAIM FILED VIA ABI, THE FILER SHOULD CONTACT THEIR ASSIGNED CLIENT REPRESENTATIVE");
			aBIErrorCollection["VN7"] = new MessageError(errorCode: "VN7", shortDesc: "LICENSE DDPP INVALID", narrative: "IN THE DRAWBACK MODULE, THIS MESSAGE MEANS THAT THE FILER GAVE ACS A DDPP AS THE LICENSE PORT THAT DOES NOT EXIST IN ACS.");
			aBIErrorCollection["VN8"] = new MessageError(errorCode: "VN8", shortDesc: "FLR CANNOT VARY IN B=}Y BLOCK", narrative: "THIS ERROR INDICATES THAT THE FILER CODE SENT ON THIS CLAIM OR CLAIMS DIFFERS FROM THAT OF THE FILER SENDING THE DATA. THIS ERROR RARELY OCCURS WITH THE DISKETTE, SINCE USCS IS SUBMITTING THE DATA FOR THE FILER. IT CAN OCCUR WITH ABI, FOR EXAMPLE, WHERE A FILER MAY BE SENDING DATA FOR THEIR 3901 OFFICE AND INADVERTENTLY INCLUDES A 5301 OFFICE CLAIM.  FOR RECONCILIATION, THIS MEANS THAT THE FILER IN THE 'B' RECORD DIFFERS FROM THE FILER IN THE 'R10' RECORD.");
			aBIErrorCollection["VN9"] = new MessageError(errorCode: "VN9", shortDesc: "LICENSE DDPP NOT FOUND", narrative: "THIS MESSAGE OCCURS IN THE DRAWBACK MODULE WHEN THE LICENSE DDPP SENT INTO THE PC LICENSE PORT FIELD DOES NOT EXIST IN ACS.  FOR RECONCILIATION, THIS MESSAGE OCCURS WHEN THE LICENSE DDPP FOR THE FILER DOES NOT EXIST IN ACS.");
			aBIErrorCollection["VNA"] = new MessageError(errorCode: "VNA", shortDesc: "FD 701: FORM MAY BE REQUIRED", narrative: "THIS ERROR MESSAGE OCCURS WHEN THE FILER SENDS A TARIFF LINE WHERE THE HARMONIZED NUMBER IS CODED FD1 (FDA MAY BE REQUIRED) IN THE HSA FILE BUT NEITHER FDA INFORMATION (RECS FD01-FD05) NOR A DISCLAIM (FD0 IN REC OA, POS 5-7) WAS SENT.");
			aBIErrorCollection["VNB"] = new MessageError(errorCode: "VNB", shortDesc: "FD 701: FORM REQUIRED", narrative: "THIS ERROR MESSAGE OCCURS WHEN THE FILER SENDS A TARIFF NUMBER LINE WHERE THE HARMONIZED NUMBER IS CODED FD2 (FDA DATA IS REQUIRED) IN THE HSA FILE BUT FDA INFORMATION (RECS FD01-FD05) HAS NOT BEEN TRANSMITTED. A DISCLAIM WOULD NOT BE ALLOWED.");
			aBIErrorCollection["VND"] = new MessageError(errorCode: "VND", shortDesc: "OGA/LINE RLSE CANNOT BE INDICATED", narrative: "THIS ERROR MESSAGE OCCURS WHEN A FILER SENDS A '1' IN REC 10, POS 80 TO INDICATE THAT THE ENTRY SUMMARY CONTAINS FDA DATA FOR AN ENTRY RELEASE THROUGH LINE RELEASE AND THE ENTRY IS NOT A LINE RELEASE ENTRY.");
			aBIErrorCollection["VNC"] = new MessageError(errorCode: "VNC", shortDesc: "OGA/LINE RLSE MUST BE INDICATED", narrative: "LINE RELEASE ENTRIES ARE ELIGIBLE FOR THE FDA INTERFACE. THE PRODUCT/ MANUFACTURER MUST BE APPROVED BY BOTH CUSTOMS AND FDA BEFORE IT CAN GO ON LINE RELEASE. ONCE IT IS APPROVED IT IS CONSIDERED 'MAY PROCEEDED' WHEN ENTERED. THE FDA INFORMATION IS THEN SENT VIA THE ENTRY SUMMARY TRANSACTION. THE FILER MUST SEND A '1' IN APPLICATION EI, REC 10, POS 80 TO INDICATE THAT THE FDA SHIPMENT WAS RELEASED VIA LINE RELEASE. IF THEY DO NOT SEND THIS INDICATOR, THIS ERROR MESSAGE WILL OCCUR.  THE CAPABILITY HAS BEEN EXPANDED 6/9/2004 TO INCLUDE MERCHANDISE FILED ON THE ENTRY SUMMARY THAT WAS RELEASED THROUGH NCAP/FAST. FOR THESE, THE FILER MUST SEND A '2' IN THE 'EI' APPLICATION RECORD 10, POSITION 80 TO INDICATE THAT THE MERCHANDISE WAS RELEASED THROUGH NCAP/FAST. IF THEY FAIL TO DO SO, THIS ERROR MESSAGE WILL OCCUR.");
			aBIErrorCollection["VNE"] = new MessageError(errorCode: "VNE", shortDesc: "OGA/LINE RLSE INDICATOR INVALID", narrative: "THE ONLY LINE RELEASE INDICATOR ALLOWED IN REC 10, POS 80 IS A '1'. IF IT DOES NOT APPLY THEN THE FILER SHOULD SPACE FILL THIS POSITION.");
			aBIErrorCollection["VNF"] = new MessageError(errorCode: "VNF", shortDesc: "FD 701: NO BASE UNIT REPORTED", narrative: "IF A FILER SENDS QUANTITY/UOM (UNIT OF MEASURE) INFORMATION (REC FD02) FOR AN FDA LINE, THE UOM MUST BE ONE OF THE FDA BASE UNITS LISTED ON PG OGA-30/31 CATAIR IF ONLY ONE QUANTITY/UOM IS SENT. IF MORE THAN ONE QUANTITY/UOM IS SENT, THE LAST ONE MUST BE A BASE UNIT AND MUST BE A VALID ONE.");
			aBIErrorCollection["VNG"] = new MessageError(errorCode: "VNG", shortDesc: "FD 701: UOM INVALID/UNKNOWN", narrative: "A MAXIMUM OF SIX QUANTITIES AND UNITS OF MEASURE (UOM) CAN BE SENT ON A SINGLE FDA LINE. THE UOM MUST BE ONE OF THE BASE UNITS SHOWN ON PAGE OG-31 OF THE CATAIR OR ONE OF THE VALID FDA CONTAINER CODES SHOWN ON PAGES OG-32-33 OF THE CATAIR. IF ANY OTHER UOM IS TRANSMITTED, EVEN IF IT IS A VALID ONE FOR CUSTOMS PURPOSES, THE ABOVE REJECT WILL BE GENERATED.");
			aBIErrorCollection["VNH"] = new MessageError(errorCode: "VNH", shortDesc: "FD 701: BASE UNIT MUST BE LAST", narrative: "IN THE FDA INTERFACE, UP TO SIX QUANTITIES AND UNITS OF MEASURE (UOM) CAN BE TRANSMITTED. FIVE QUANTITIES/UOM CAN BE SENT IN REC FD02, POS 5-18, 19-32, 33-46, 47-60 AND 61-74 (CATAIR, PAGE OGA-30). THE SIXTH, IF APPLICABLE, IS SENT IN REC FD04, POS 5-18 (CATAIR, PAGE OGA-35). IF QUANTITIES/UOM'S ARE SENT THEN AT LEAST ONE OF THEM MUST BE A 'BASE UNIT' AND IF MORE THAN ONE IS SENT THE BASE UNIT MUST BE IN THE LAST POSITION. IF, FOR EXAMPLE, THREE QUANTITIES/UOM'S ARE SENT THE BASE QUANTITY MUST BE IN THE 'UNIT 3 QUANTITY AND MEASURE BLOCK (REC FD01, POS 33-46). IF ONLY ONE QUANTITY/UOM IS SENT IT MUST BE A BASE UNIT AND SENT IN THE UNIT 1 QUANTITY AND MEASURE BLOCK (REC FD02, POS 1-18). FDA BASE UNITS ARE SHOWN IN THE CATAIR, PAGES OGA-29.");
			aBIErrorCollection["VNI"] = new MessageError(errorCode: "VNI", shortDesc: "FD 701: MLTPLE BASE UNITS INVALID", narrative: "IN THE FDA INTERFACE, UP TO SIX QUANTITIES AND UNITS OF MEASURE (UOM) CAN BE TRANSMITTED. FIVE QUANTITIES/UOM CAN BE SENT IN REC FD02, POS 5-18, 92-32, 33-46, 47-60 AND 61-74 (CATAIR, PAGE OGA-30). THE SIXTH, IF APPLICABLE, IS SENT IN REC FD04, POS 5-18 (CATAIR PAGE OGA-35). IF QUANTITIES/UOM'S ARE SENT THEN AT LEAST ONE OF THEM MUST BE A 'BASE UNIT' AND IF MORE THAN ONE IS SENT, THE BASE UNIT MUST BE IN THE LAST POSITION. THE FILER CANNOT SEND MORE THAN ONE BASE UNIT. BASE UNITS ARE LOCATED IN THE CATAIR, PAGE OGA-31. TO SOLVE THIS ERROR, THE FILER MUST USE THE BASE UNIT AND A CONTAINER CODE (S) FOUND ON PAGES OGA 32-33, CATAIR.");
			aBIErrorCollection["VNJ"] = new MessageError(errorCode: "VNJ", shortDesc: "DCMCI IMPORTER/FILER INVALID", narrative: "DCMCI ENTRIES FOR EMERGENCY WAR MATERIAL MAY BE ENTERED BY ANY FILER WHO USES ENTRY TYPE 01. IF ENTRY TYPE 51 IS USED, HOWEVER, THE ONLY ACCEPTABLE FILER CODE AND IMPORTER NUMBER MUST BELONG TO DCMCI. THE CURRENT VALID FILER CODE IS P99. IF A DIFFERENT FILER CODE IS USED, THIS ERROR MESSAGE WILL RESULT.");
			aBIErrorCollection["VNK"] = new MessageError(errorCode: "VNK", shortDesc: "INVALID IN-BOND FILER CODE", narrative: "THIS ERROR MESSAGE OCCURS WHEN THERE IS AN INCORRECT 'V' NUMBER IN-BOND FILER CODE TRANSMITTED IN THE FIRST THREE POSITIONS OF THE IN BOND NUMBER SENT IN THE EI 22 RECORD, POSITIONS 3-14 OR THE HI HA RECORD, POSITIONS 3-14. THE 'V' NUMBER MUST BE ON THE CARL FILE.");
			aBIErrorCollection["VNL"] = new MessageError(errorCode: "VNL", shortDesc: "AUTOCERT INVALID - OGA LINE RLSE", narrative: "THIS MESSAGE OCCURS IN AN ENTRY SUMMARY TRANSACTION WHEN THE FILER ATTEMPTS TO CERTIFY FOR CARGO SELECTIVITY FOR AN ENTRY NUMBER WHICH WAS RELEASED AS A FDA LINE RELEASE ENTRY. THE FILER MUST SEND THE EI TRANSACTION WITHOUT CARGO RELEASE CERTIFICATION AND SEND A '1' IN POSITION 80 OF THE EI 10 RECORD WHICH IDENTIFIES THE ENTRY AS A FDA LINE RELEASE ENTRY.  NOTE: THE ABOVE MESAGE WILL ALSO BE GENERATED FOR AN ENTRY NUMBER THAT HAS NOT BEEN PROCESSED THROUGH LINE RELEASE IF THE SAME CONDITIONS AS OUTLINED ABOVE EXIST (CARGO CERT IN POS 38 OF THE 30 RECORD ACCOMPANIED BY A 1 IN POS 80 OF THE 10 REC). THUS, THIS MESSAGE WILL RESULT ON NON-LINE RELEASE ENTRIES IF THE AUTO CERTIFICATION INDICATOR IS '1' AND THE OGA INDICATOR IS ALSO TRANSMITTED. (IF A TRUE NON-LINE RELEASE ENTRY, THE CORRECTION IS TO REMOVE THE OGA INDICATOR IN THE 10 RECORD).");
			aBIErrorCollection["VNM"] = new MessageError(errorCode: "VNM", shortDesc: "WAIVER INVALID FOR BOND OR CLAIM", narrative: "IN THE DRAWBACK MODULE THE WAIVER INDICATOR MAY ONLY BE 'Y' ('1' IF ABI) IF THE BOND TYPE CODE IS NOT '0' (WOULD BE EITHER '8' OR '9'), AND THE CLAIM TYPE IS NOT '41' OR '44 (MANUFACTURING DRAWBACK). IF 'Y' ('1' IF ABI) IS USED AND THE CONDITION IS NOT CORRECT THIS MESSAGE IS GENERATED. (JO 050898) ALSO, WAIVER OF PRIOR NOTICE IS NOT VALID FOR TYPE '43' DRAWBACK CLAIMS.");
			aBIErrorCollection["VNN"] = new MessageError(errorCode: "VNN", shortDesc: "ACCEL. NOT ALLOWED FOR BOND TYPE", narrative: "IN THE DRAWBACK MODULE THE ACCELERATED INDICATOR MAY ONLY BE A 'Y' IF THE BOND TYPE CODE IS NOT '0' (WOULD BE EITHER '8' OR '9'), UNLESS THE GOVERNMENT CLAIM INDICATOR IS ALSO 'Y' ('1' IF ABI).");
			aBIErrorCollection["VNO"] = new MessageError(errorCode: "VNO", shortDesc: "EXPORT SUM INVALID FOR BOND TYPE", narrative: "IN THE DRAWBACK MODULE THE EXPORT SUMMARY INDICATOR MAY ONLY BE A 'Y' (OR '1' IF ABI) IF THE BOND TYPE CODE IS NOT '0' (WOULD BE EITHER '8' OR '9'), UNLESS THE GOVERNMENT CLAIM INDICATOR IS ALSO 'Y' (OR '1' IF ABI). IF 'Y' (OR '1' IF ABI) IS USED AND THE CONDITION IS NOT CORRECT, MESSAGE VNO APPEARS.");
			aBIErrorCollection["VNP"] = new MessageError(errorCode: "VNP", shortDesc: "D11 RECORD MUST CONTAIN DATA", narrative: "THIS ERROR MESSAGE COULD BE THE RESULT OF A DRAWBACK DISKETTE OR ABI PROBLEM. WHEN CUSTOMS FORMATTED THE RECORDS FROM THE DISKETTE OR WHEN THE DATA WAS SENT VIA ABI, NO DATA WAS PRESENT IN THE GIVEN RECORD. IF THE DISKETTE HAS NO DATA, THE PC PROGRAM SHOULD STOP IT BEFORE TRANSMISSION; HOWEVER, THERE MAY HAVE BEEN DATA THERE, BUT IT WAS BAD DATA.");
			aBIErrorCollection["VNQ"] = new MessageError(errorCode: "VNQ", shortDesc: "DRAWBACK CONTRACT NBR INVALID", narrative: "THIS MESSAGE MEANS THAT THE FILER CHOSE TO GIVE A DRAWBACK CONTRACT NUMBER, BUT THE NUMBER USED DOES NOT EXIST ON THE CONTRACT FILE IN ACS OR IS NOT IN A VALID FORMAT (NN-NNNNN-NNN), AS OUTLINED ON PAGE DRW-9 OF THE CATAIR.");
			aBIErrorCollection["VNR"] = new MessageError(errorCode: "VNR", shortDesc: "CLAIM DTE OVER 30 DAYS IN FUTURE", narrative: "IN THE DRAWBACK MODULE THIS MESSAGE INDIACTES THAT THE DATE IS IN A VALID FORMAT, BUT IS GREATER THAN 30 DAYS IN THE FUTURE. FUTURE DATES ARE NOT ACCEPTED FOR THE DISKETTE PROGRAM. DATES UP TO 30 DAYS IN ADVANCE ARE ACCEPTED VIA ABI. FOR ABI TRANSMISSIONS, MESSAGE VLZ WILL BE USED IF OVER 30 DAYS IN ADVANCE.");
			aBIErrorCollection["VNS"] = new MessageError(errorCode: "VNS", shortDesc: "CLAIM DATE CANNOT BE LT 941001", narrative: "IN THE DRAWBACK MODULE, THIS MESSAGE MEANS THAT THE DRAWBACK CLAIM DATE IS PRIOR TO OCTOBER 1, 1994. THE DISK PROGRAM IS ONLY VALID FOR CLAIMS FILED ON OR AFTER THAT DATE.");
			aBIErrorCollection["VOM"] = new MessageError(errorCode: "VOM", shortDesc: "INVALID REMOTE ENTRY DDPP", narrative: "THE DDPP SENT IN THE 'REMOTE DDPP' PORTION OF THE 'B' RECORD, POSITIONS 47-50 MUST BE A VALID DDPP IN THE RDP FILE.");
			aBIErrorCollection["VNT"] = new MessageError(errorCode: "VNT", shortDesc: "DBK IMPORT ENTRY NOT ON FILE", narrative: "THIS DRAWBACK MODULE ERROR MESSAGE MEANS THAT THE DESIGNATED IMPORT ENTRY DOES NOT EXIST AS GIVEN. ACS DOES A MATCH ON THE IMPORT ENTRY NUMBER AND THE PORT OF ENTRY GIVEN ON THE DISKETTE BY THE FILER. IF THE FILER USES AN IMPORT ENTRY/PORT COMBINATION THAT IS NOT VALID IN ACS, THIS MESSAGE WILL BE GENERATED. THEREFORE, EITHER THE ENTRY DOES NOT EXIST AT ALL, OR IT DOES NOT EXIST FOR THE PORT INDICATED. NOTE: THERE ARE INSTANCES WHERE VALID ENTRIES ARE NOT IN ACS (E.G. INFORMALS THAT WERE JUST DONE ON CASH RECEIPTS). FOR THESE, A SPECIAL CM NUMBER HAS BEEN ESTABLISHED IN ACS. IF THE FILER INDICATES THAT THIS IS THE CASE, THE FILER MAY DESIGNATE THE MONIES FROM CM888888/9900. THIS CM HAS BEEN ESTABLISHED JUST FOR THIS CASE WHERE EITHER AN INFORMAL OR MAIL ENTRY WAS DONE ON A CASH RECEIPT WITH NO ACS ENTRY RECORD CREATED.");
			aBIErrorCollection["VNU"] = new MessageError(errorCode: "VNU", shortDesc: "INVALID ACS IMPORT ENTRY TYPE", narrative: "THIS DRAWBACK MODULE ERROR MESSAGE MEANS THAT THE ENTRY TYPE FOR THE DESIGNATED IMPORT IS NOT VALID FOR USE ON A DRAWBACK TRANSACTION. THE VALID ENTRY IMPORT ENTRY TYPES ARE '01', '02', '03', '04', '06', '07', '08', '11', '12', '21', '22', '51', '52', AND '53'. IF THE IMPORT HAS ANY OTHER ENTRY TYPE, THIS REJECTION WILL OCCUR BECAUSE THE IMPORT IS NOT A CONSUMPTION OR WAREHOUSE WITHDRAWAL ENTRY.  FOR RECONCILIATION, THIS ERROR MEANS THAT THE IMPORT ENTRY WAS NOT A TYPE '01', '02' OR '06'. THESE ARE THE ONLY VALID ENTRY TYPES FOR RECONCILIATION.");
			aBIErrorCollection["VNV"] = new MessageError(errorCode: "VNV", shortDesc: "INVALID STATUS ON IMPORT ENTRY", narrative: "THIS DRAWBACK MODULE ERROR MESSAGE MEANS THAT THE DESIGNATED IMPORT IS NOT IN A VALID PROCESS STATUS. IT MAY BE CANCELLED, OR MAY ONLY BE A SHELL PAYMENT, OR ONLY A RELEASE. THE FILER WILL BE ADVISED OF THE CONDITION.  THIS SAME ERROR WILL BE USED FOR RECONCILIATION TO INDICATE THAT AN ASSOCIATED IMPORT IS NOT IN A VALID PROCESS STATUS. NORMALLY, THIS MEANS THAT THE IMPORT ENTRY HAS BEEN CANCELLED, BUT THERE MAY BE OTHER INVALID STATUSES.");
			aBIErrorCollection["VNW"] = new MessageError(errorCode: "VNW", shortDesc: "IMPORT MUST BE IN CUSTOMS STATUS", narrative: "THIS DRAWBACK MODULE ERROR MESSAGE MEANS THAT THE IMPORT ENTRY IS STILL IN ABI STATUS AND HAS NOT BEEN PROCESSED BY CUSTOMS.");
			aBIErrorCollection["VNX"] = new MessageError(errorCode: "VNX", shortDesc: "IMPORT SUMM DATE MUST BE } SPACES", narrative: "THIS DRAWBACK MODULE ERROR MESSAGE MEANS THAT THERE IS NO ENTRY SUMMARY DATE IN ACS FOR THE DESIGNATED IMPORT. IN ALL PROBABILITY, THIS MESSAGE WILL APPEAR IN CONJUNCTION WITH MESSAGE VNW.");
			aBIErrorCollection["VNY"] = new MessageError(errorCode: "VNY", shortDesc: "CLAIM DUTY CANNOT EXCEED PAID", narrative: "THIS DRAWBACK MODULE ERROR MESSAGE MEANS THAT THE AMOUNT OF DUTY CLAIMED AGAINST THE IMPORT FOR THIS DRAWBACK CLAIM EXCEEDS THE TOTAL DUTY ORIGINALLY AVAILABLE FOR THE ENTRY. THESE ERRORS WILL OCCUR IF THE IMPORT ENTRY IS BEING DESIGNATED FOR DRAWBACK FOR THE FIRST TIME AND THE CLAIMED DUTY AMOUNT EXCEEDS THE ORIGINAL AVAILABLE AMOUNT, OR IF THE CLAIM IS A TYPE '46' AND THE CLAIMED DRAWBACK EXCEEDS THE CURRENT AVAILABLE DUTY. NOTE: THERE ARE OTHER ODD CONDITIONS WHERE THE MESSAGE WILL OCCUR DUE TO NO FAULT OF THE FILER. IF THE FILER INDICATES THAT MORE MONIES WERE PAID THAN ARE REFLECTED IN ACS (E.G. SUPPLEMENTAL DUTIES ON A VOULUNTARY TENDER FOR ASSISTS WAS TENDERED, BUT THE COLLECTION WAS NOT POSTED TO THE ENTRY), THE FILER SHOULD BE INSTRUCTED TO DESIGNATE THE ADDITIONAL MONIES ON CM 999999/9900. THIS CM WAS CREATED JUST FOR THIS TYPE OF CONDITION.");
			aBIErrorCollection["VNZ"] = new MessageError(errorCode: "VNZ", shortDesc: "CLAIM TAX CANNOT EXCEED PAID", narrative: "THIS DRAWBACK MODULE ERROR MESSAGE MEANS THAT THE AMOUNT OF TAX CLAIMED AGAINST THE IMPORT FOR THIS DRAWBACK CLAIM EXCEEDS THE TOTAL TAX ORIGINALLY AVAILABLE FOR THE ENTRY. THESE ERRORS WILL OCCUR IF THE IMPORT ENTRY IS BEING DESIGNATED FOR DRAWBACK FOR THE FIRST TIME AND THE CLAIMED TAX AMOUNT EXCEEDS THE ORIGINAL AVAILABLE AMOUNT, OR IF THE CLAIM IS A TYPE '46' AND THE CLAIMED DRAWBACK EXCEEDS THE CURRENT AVAILABLE TAX. NOTE: THERE ARE OTHER ODD CONDITIONS WHERE THE MESSAGE WILL OCCUR DUE TO NO FAULT OF THE FILER. IF THE FILER INDICATES THAT MORE MONIES WERE PAID THAN ARE REFLECTED IN ACS (E.G. SUPPLEMENTAL DUTIES ON A VOULUNTARY TENDER FOR ASSISTS WAS TENDERED, BUT THE COLLECTION WAS NOT POSTED TO THE ENTRY), THE FILER SHOULD BE INSTRUCTED TO DESIGNATE THE ADDITIONAL MONIES ON CM 999999/9900. THIS CM WAS CREATED JUST FOR THIS TYPE OF CONDITION");
			aBIErrorCollection["VO1"] = new MessageError(errorCode: "VO1", shortDesc: "DT HS7: FORM REQUIRED", narrative: "IMPORTED PRODUCTS SUBJECT TO REVIEW BY THE DEPARTMENT OF TRANSPORTATION ARE CODED DT1 OR DT2 ON THE HARMONIZED TARIFF DATABASE. IF THE CODING IS DT2, THE FILER IS REQUIRED TO REPORT DOT INFORMATION FOR THE TARIFF NUMBER. IF NO DATA IS TRANSMITTED, THE ABOVE ERROR MESSAGE WILL RESULT.");
			aBIErrorCollection["VO2"] = new MessageError(errorCode: "VO2", shortDesc: "PREPARER SITE INVALID/MISSING", narrative: "HP TRANSACTION WAS REJECTED BECAUSE THE EI WAS ORIGINALLY FILED WITH A PREPARER INDICATOR IN THE 'B' RECORD AND A VALID PREPARER SITE, BUT THE 'B' RECORD OF THE HP DOES NOT CONTAIN THE SAME PREPARER DATA.  NOTE: THIS ERROR WILL ALSO RESULT IF THE ENTRY SUMMARY IS NO LONGER IN ABI STATUS.");
			aBIErrorCollection["VO3"] = new MessageError(errorCode: "VO3", shortDesc: "PREPARER SITE REQUIRED", narrative: "HP TRANSACTION WAS REJECTED BECAUSE THE EI WAS ORIGINALLY FILED WITH A PREPARER INDICATOR IN THE 'B' RECORD AND A PREPARER SITE, BUT THE 'B' RECORD OF THE HP DOES NOT CONTAIN PREPARER DATA.");
			aBIErrorCollection["VO4"] = new MessageError(errorCode: "VO4", shortDesc: "NAT'L PERMIT REQUIRED FOR RLF", narrative: "WHEN B RECORD PREPARER DDPP SITE INDICATOR = '1' AND THE FILER TYPE IS 'BROKER' WITH AN 'ACTIVE' STATUS, THE FILER MUST HAVE A NATIONAL PERMIT (9900) ON FILE IN ACS.");
			aBIErrorCollection["VO5"] = new MessageError(errorCode: "VO5", shortDesc: "NAT'L PERMIT REQD FOR RECON", narrative: "EXPECT A 'BFC' AND 'BFB' RECORD FOR 'RA' TRANSACTIONS. 'BFC' AND 'BFB' RECORDS ARE READ BY EITHER PREP-SITE FILER CODE, IF PRESENT, OR BY B-REC FILER CODE.  NOTE: IF AN ABI FILER WITH A REVOKED NATIONAL PERMIT ON BFB (FOR PORT 9900) ATTEMPTS TO TRANSMIT A RECON ENTRY, THIS ERROR WILL RESULT. THE 'OPERATING STATUS INDICATOR ON BFB WILL SHOW 'REVOKED.'");
			aBIErrorCollection["VOA"] = new MessageError(errorCode: "VOA", shortDesc: "DBK FLR NOT PERMITTED IN LOCATION", narrative: "THE EDIT THAT PRODUCES THIS MESSAGE ONLY APPLIES TO LICENSED BROKERS. IT IS NOT PERFORMED AGAINST FILERS WHO FILE THEIR OWN DRAWBACK CLAIMS. ACS KNOWS WHICH ARE NOT LICENSED. THE MESSAGE INDICATES THAT, WHILE THE FILER IS A LICENSED BROKER, THE FILER DOES NOT HAVE AN OPERATING PERMIT WITHIN THE REGION WHERE THE DRAWBACK CLAIM IS BEING FILED.  PR HAD AN ENTRY IN 08/03 THAT REJECTED WITH THIS MESSAGE. FOUND THAT THE DDPP IN THE 'LICENSE PORT' D10 RECORD, POSITIONS 74-77 MUST BE IN THE SAME 'REGION' AS THE 'CLAIM PORT' D10 RECORD, POSITIONS 18-21. THE FILER ALSO MUST BE PERMITTED IN A PORT WITHIN THAT REGION. (JO 082003).  NOW THAT WE HAVE 'NATIONAL FILERS' THE DDPP IN POSITIONS 74-77 OF THE D10 RECORD SHOULD BE '9900'.");
			aBIErrorCollection["VOC"] = new MessageError(errorCode: "VOC", shortDesc: "DRAWBACK FILER NOT ON FILE", narrative: "THIS MESSAGE MEANS THAT THE FILER CODE GIVEN ON THE DRAWBACK DISKETTE DOES NOT EXIST IN ACS.");
			aBIErrorCollection["VOH"] = new MessageError(errorCode: "VOH", shortDesc: "PREPARER/REMOTE IND CONLICT", narrative: "THE REMOTE PROCESSING DISTRICT PORT IS SENT IN THE 'B' RECORD, POSITIONS 47-50. THE REMOTE PREPARER FILER IS SENT IN THE 'B' RECORD, POSITIONS 51-53. IF THE REMOTE PREPARER INDICATOR IN POSITION 56 OF THE 'B' RECORD IS SET TO '1' (YES) THEN THE DDPP/FILER MUST BE SET UP IN THE ABJ FILE.");
			aBIErrorCollection["VOK"] = new MessageError(errorCode: "VOK", shortDesc: "INVALID REMOTE PROC DDPP", narrative: "IN A REMOTE ENTRY TRANSACTION, THE PROCESSING DDPP SENT IN THE 'B' RECORD, POSITIONS 4-7, MUST BE A VALID DDPP IN THE RDP FILE.");
			aBIErrorCollection["VOL"] = new MessageError(errorCode: "VOL", shortDesc: "PROC FLR MUST=PREPARER FLR", narrative: "THE REMOTE PREPARER FILER CODE SENT IN POSITIONS 51-53 OF THE EI 'B' RECORD MUST BE THE SAME AS THE PROCESSING (ENTRY) FILER CODE 'B' RECORD, POSITIONS 8-10.");
			aBIErrorCollection["VOB"] = new MessageError(errorCode: "VOB", shortDesc: "EXISTING ENTRY NOT DRAWBACK CLAIM", narrative: "THIS MESSAGE RESULTS WHEN THE FILER TRANSMITS AN ADDITION/DELETION CODE OF EITHER 'A' OR 'D' AND THE CLAIM NUMBER USED ALREADY EXISTS IS ACS AND IS NOT A DRAWBACK CLAIM. IF THE ENTRY NUMBER HAS ALREADY BEEN USED AND IS NOT A DRAWBACK CLAIM, THE CLAIM AND DISKETTE WILL BE RETURNED FOR CORRECTION. ABI WILL REJECT THE TRANSMISSION.");
